const ENABLE_SHARED_SYSTEM_ACCOUNTS = false;

function isLocalDevelopmentHost() {
  const hostname = String(window.location.hostname || "").toLowerCase();
  return window.location.protocol === "file:"
    || ["localhost", "127.0.0.1", "::1"].includes(hostname);
}

function readDeveloperSession() {
  try {
    const session = JSON.parse(sessionStorage.getItem(DEV_MOD_SESSION_KEY) || "null");
    if (!session?.authorized || Number(session.expiresAt || 0) <= Date.now()) {
      sessionStorage.removeItem(DEV_MOD_SESSION_KEY);
      return null;
    }
    return session;
  } catch {
    sessionStorage.removeItem(DEV_MOD_SESSION_KEY);
    return null;
  }
}

function isDeveloperModeEnabled() {
  return isLocalDevelopmentHost() && !!readDeveloperSession();
}

// Chrome, Edge und Safari erlauben WebAudio und Vibration erst nach einer
// echten Benutzeraktion. Automatische Firebase-, Start- oder Anrufsvorgänge
// dürfen diese APIs vorher nicht aktivieren.
function hasTransientUserGesture(event = null) {
  if (event?.isTrusted === true) return true;
  return navigator.userActivation?.isActive === true;
}

let jkUserActivationSeen = navigator.userActivation?.hasBeenActive === true;

["pointerdown", "touchend", "keydown"].forEach((eventName) => {
  window.addEventListener(eventName, () => {
    jkUserActivationSeen = true;
  }, { capture: true, passive: true, once: true });
});

function safeVibrate(pattern) {
  if (typeof navigator.vibrate !== "function") return false;
  if (!jkUserActivationSeen && navigator.userActivation?.hasBeenActive !== true) return false;
  try {
    return navigator.vibrate(pattern);
  } catch {
    return false;
  }
}

