const finderJobs = ["Pflegefachkraft", "Elektroniker/in", "Bauzeichner/in", "Verkäufer/in", "Webdesigner/in", "Student/in", "Koch/Köchin", "Mechatroniker/in", "Fotograf/in", "Erzieher/in", "Bürokraft", "Fitnesstrainer/in", "Reiseberater/in", "Handwerker/in", "Selbstständig"];
const finderInterests = ["Reisen", "Kochen", "Sport", "Gaming", "Autos", "Musik", "Tiere", "Filme", "Natur", "Fotografie", "Fitness", "Konzerte", "Handwerk", "Cafés", "Fußball", "Bücher", "Tanzen", "Technik", "Strand", "Städtetrips"];
const finderIntentions = ["eine feste Beziehung", "jemanden zum Kennenlernen", "gemeinsame Abenteuer", "ehrliche Gespräche", "etwas Langfristiges"];
const finderValues = ["Ehrlichkeit", "Humor", "Verlässlichkeit", "Familie", "Freiheit", "Ehrgeiz", "Respekt", "Neugier"];
const finderLifestyles = ["ruhig und bodenständig", "spontan und reiselustig", "sportlich und aktiv", "kreativ und entspannt", "karriereorientiert, aber herzlich", "gesellig und unternehmungslustig"];
const finderDealbreakers = ["ständige Unzuverlässigkeit", "Respektlosigkeit", "nur oberflächliche Gespräche", "extreme Eifersucht", "fehlender Humor", "unehrliche Absichten"];
const finderDateTastes = ["walk", "cafe", "restaurant", "premium", "luxury", "ultimate"];

function finderPetSnapshot(pet) {
  if (!pet || typeof pet !== "object") return null;
  const type = String(pet.type || "pet").trim().slice(0, 32) || "pet";
  return {
    id: String(pet.id || `finder-pet-${type}`).trim().slice(0, 80),
    type,
    name: String(pet.name || "Haustier").trim().slice(0, 40) || "Haustier",
    icon: String(pet.icon || characterPetIcon(pet) || "🐾").slice(0, 8),
    description: String(pet.description || "Treuer Begleiter.").trim().slice(0, 160)
  };
}

function buildFinderProfiles() {
  const cities = travelDestinations.map((place) => place.name);
  const make = (name, index, gender) => {
    const interestA = finderInterests[(index * 3 + (gender === "female" ? 1 : 5)) % finderInterests.length];
    const interestB = finderInterests[(index * 5 + 7) % finderInterests.length];
    const interestC = finderInterests[(index * 7 + 11) % finderInterests.length];
    const city = cities[(index * 7 + (gender === "female" ? 2 : 9)) % cities.length];
    const age = 18 + ((index * 5 + (gender === "female" ? 2 : 4)) % 23);
    const valueA = finderValues[(index * 2 + 1) % finderValues.length];
    const valueB = finderValues[(index * 3 + 4) % finderValues.length];
    const lifestyle = finderLifestyles[index % finderLifestyles.length];
    const dealbreaker = finderDealbreakers[(index * 5 + 2) % finderDealbreakers.length];
    const botPet = index % 4 === 0
      ? finderPetSnapshot(index % 8 === 0
        ? { id: `finder-pet-dog-${index}`, type: "dog", name: ["Buddy", "Bruno", "Loki", "Milo"][index % 4], icon: "🐕", description: "Ein freundlicher Hund, der gern bei Ausflügen dabei ist." }
        : { id: `finder-pet-cat-${index}`, type: "cat", name: ["Luna", "Nala", "Mimi", "Simba"][index % 4], icon: "🐈", description: "Eine ruhige Katze, die gemütliche Abende liebt." })
      : null;
    return {
      id: `finder-${gender}-${index + 1}`,
      source: "bot",
      name,
      gender,
      age,
      city,
      job: finderJobs[(index * 4 + (gender === "female" ? 0 : 3)) % finderJobs.length],
      interests: [interestA, interestB, interestC],
      intention: finderIntentions[index % finderIntentions.length],
      bio: `Ich mag ${interestA.toLowerCase()}, ${interestB.toLowerCase()} und spontane ${interestC.toLowerCase()}-Pläne. Ich suche ${finderIntentions[index % finderIntentions.length]}.`,
      aboutLong: `Mein Alltag ist ${lifestyle}. Besonders wichtig sind mir ${valueA.toLowerCase()} und ${valueB.toLowerCase()}. Ich mag Menschen, die offen kommunizieren und auch über sich selbst lachen können. Am Wochenende bin ich gern bei ${interestA.toLowerCase()} oder ${interestB.toLowerCase()} dabei.`,
      values: [valueA, valueB],
      lifestyle,
      dealbreaker,
      dateTaste: finderDateTastes[(index * 3 + (gender === "female" ? 1 : 4)) % finderDateTastes.length],
      prompt: ["Mein perfekter Sonntag: Kaffee, rausgehen und abends entspannt essen.", "Ich lache über trockenen Humor und schlechte Wortspiele.", "Überzeuge mich mit Ehrlichkeit statt Anmachsprüchen.", "Mein nächstes Ziel ist eine Reise, die ich nie vergesse."][index % 4],
      colors: gender === "female"
        ? ["#d982a6", "#8c5fc7", "#3f8fb8", "#cc7a58"][index % 4]
        : ["#3c7f9f", "#5366a8", "#2f876f", "#8a6548"][index % 4],
      hair: ["#2a1811", "#6f472c", "#c59b54", "#171717", "#8b3d2f"][index % 5],
      skin: ["#f1c8a8", "#dca17a", "#b97855", "#8e5b42", "#e7b58f"][index % 5],
      ...(botPet ? { pet: botPet } : {})
    };
  };
  return [
    ...finderWomenNames.map((name, index) => make(name, index, "female")),
    ...finderMenNames.map((name, index) => make(name, index, "male"))
  ];
}

const finderProfiles = buildFinderProfiles();
let finderOnlineProfiles = [];
let finderOnlineOwnProfile = null;
let finderOnlineLoadState = "idle";
let finderOnlineLoadError = "";
let finderOnlineLastLoadedAt = 0;
let finderOnlineChatUnsub = null;
let finderOnlineChatConversationId = "";
let finderOnlineChatProfileId = "";
let finderOnlineChatMessages = [];
let finderOnlineChatState = "idle";
let finderOnlineChatError = "";
let finderOnlineChatItem = null;
let finderOnlineChatStartPromise = null;
let finderIncomingLikesUnsub = null;
let finderIncomingLikesUid = "";
let finderIncomingLikesBusy = false;
let finderIncomingLikesRetryTimer = null;
let finderIncomingLikesRetryDelay = 4000;
let finderRuntimeUid = "";

function onlineFirebaseTimeout(promise, timeoutMs = 12000, label = "Online-Anfrage") {
  // V241: Firestore-Operationen werden nicht mehr durch Promise.race künstlich
  // "abgebrochen". Ein Race kann die SDK-Anfrage nicht stoppen; sie lief im
  // Hintergrund weiter, während bereits ein Retry gestartet wurde.
  return Promise.resolve(promise);
}

function finderOnlineProfileFromData(uid, data = {}) {
  const gender = data.gender === "female" ? "female" : "male";
  const interests = Array.isArray(data.interests) && data.interests.length
    ? data.interests.slice(0, 5).map(String)
    : ["Freizeit", "Musik", "Reisen"];
  return {
    id: `online-${uid}`,
    source: "player",
    onlineUid: uid,
    name: String(data.displayName || "Online-Spieler").slice(0, 40),
    gender,
    age: Math.max(18, Math.min(99, Number(data.age || 18))),
    city: String(data.city || "Deutschland").slice(0, 50),
    job: String(data.job || "JK.Games-Spieler/in").slice(0, 60),
    interests,
    intention: String(data.intention || "jemanden zum Kennenlernen").slice(0, 100),
    bio: String(data.bio || "Ich bin ein echter JK.Games-Spieler.").slice(0, 240),
    aboutLong: String(data.aboutLong || data.bio || "Echtes Spielerprofil aus Finder.KL.").slice(0, 500),
    values: Array.isArray(data.values) ? data.values.slice(0, 3).map(String) : ["Ehrlichkeit", "Respekt"],
    lifestyle: String(data.lifestyle || "individuell").slice(0, 100),
    dealbreaker: String(data.dealbreaker || "Respektlosigkeit").slice(0, 100),
    dateTaste: finderDateTastes.includes(data.dateTaste) ? data.dateTaste : "cafe",
    prompt: String(data.prompt || "Schreib mir etwas Persönliches statt nur Hallo.").slice(0, 180),
    colors: String(data.color || (gender === "female" ? "#c66b88" : "#3c7f9f")),
    hair: String(data.hair || "#2a1811"),
    skin: String(data.skin || "#dca17a"),
    pet: finderPetSnapshot(data.pet),
    online: data.online === true,
    createdAtMs: Number(data.createdAtMs || 0),
    updatedAtMs: Number(data.updatedAtMs || 0),
    lastSeenAtMs: Number(data.lastSeenAtMs || 0)
  };
}

function finderAllProfiles() {
  return [...finderProfiles, ...finderOnlineProfiles];
}

async function startFinderIncomingLikesListener(item = null) {
  try {
    const fb = await onlineFirebaseTimeout(loadFirebasePhoneRuntime(), 9000, "Finder.KL-Anmeldung");
    const ownUid = fb.auth.currentUser?.uid || "";
    if (!ownUid) return;
    if (finderIncomingLikesUnsub && finderIncomingLikesUid === ownUid) return;
    try { finderIncomingLikesUnsub?.(); } catch {}
    finderIncomingLikesUnsub = null;
    finderIncomingLikesUid = ownUid;
    clearTimeout(finderIncomingLikesRetryTimer);
    finderIncomingLikesRetryTimer = null;
    const incomingQuery = fb.query(
      fb.collectionGroup(fb.db, "targets"),
      fb.where("toUid", "==", ownUid),
      fb.limit(100)
    );
    finderIncomingLikesUnsub = fb.onSnapshot(incomingQuery, async (snapshot) => {
      if (finderIncomingLikesBusy || fb.auth.currentUser?.uid !== ownUid) return;
      finderIncomingLikesBusy = true;
      try {
        const ownLikesSnap = await onlineFirebaseTimeout(
          fb.getDocs(fb.collection(fb.db, "finderLikes", ownUid, "targets")),
          8000,
          "Finder.KL-Likes"
        );
        const outgoing = new Set(ownLikesSnap.docs.map((entry) => String(entry.id)));
        const mutualUids = [...new Set(snapshot.docs.map((entry) => String(entry.data()?.fromUid || "")).filter((uid) => uid && outgoing.has(uid)))];
        if (!mutualUids.length) return;
        let changed = false;
        const finder = ensureFinderState();
        for (const sourceUid of mutualUids) {
          let profile = finderOnlineProfiles.find((entry) => entry.onlineUid === sourceUid) || null;
          if (!profile) {
            const profileSnap = await onlineFirebaseTimeout(fb.getDoc(fb.doc(fb.db, "finderProfiles", sourceUid)), 7000, "Finder.KL-Profil");
            if (!profileSnap.exists()) continue;
            profile = finderOnlineProfileFromData(sourceUid, profileSnap.data());
            finderOnlineProfiles.push(profile);
          }
          if (finder.matches.includes(profile.id)) continue;
          const allowed = finderCanCreateMatch();
          if (!allowed.ok) continue;
          finder.matches.unshift(profile.id);
          if (!finder.liked.includes(profile.id)) finder.liked.push(profile.id);
          finder.totalMatches += 1;
          const chat = finderChatFor(profile.id);
          chat.lost = false;
          if (!chat.messages.length) chat.messages.push({ from: "them", text: "Gegenseitiges Like – ihr seid jetzt ein Online-Match.", at: Date.now() });
          addFeed(`Finder.KL: Echtes Online-Match mit ${profile.name}. Ihr könnt jetzt schreiben.`);
          changed = true;
        }
        if (changed) {
          window.LifeBuilderSaveControl?.applyRemote?.(() => save());
          if (els.dialog?.open && els.dialog.querySelector(".finder-app")) refreshDeviceApp("finder", item || ownedPhoneItem());
        }
        finderIncomingLikesRetryDelay = 4000;
      } catch (error) {
        console.warn("Finder incoming likes", error);
      } finally {
        finderIncomingLikesBusy = false;
      }
    }, (error) => {
      console.warn("Finder incoming likes listener", error);
      try { finderIncomingLikesUnsub?.(); } catch {}
      finderIncomingLikesUnsub = null;
      if (fb.auth.currentUser?.uid !== ownUid) return;
      clearTimeout(finderIncomingLikesRetryTimer);
      const delay = finderIncomingLikesRetryDelay;
      finderIncomingLikesRetryDelay = Math.min(30000, Math.round(finderIncomingLikesRetryDelay * 1.7));
      finderIncomingLikesRetryTimer = window.setTimeout(() => {
        finderIncomingLikesRetryTimer = null;
        if (navigator.onLine !== false && !document.hidden) startFinderIncomingLikesListener(item).catch(console.warn);
      }, delay);
    });
  } catch (error) {
    console.warn("Finder incoming likes start", error);
  }
}

async function loadFinderOnlineProfiles(force = false, item = null) {
  if (finderOnlineLoadState === "loading") return;
  if (!force && finderOnlineLoadState === "ready" && Date.now() - finderOnlineLastLoadedAt < 45000) return;
  finderOnlineLoadState = "loading";
  finderOnlineLoadError = "";
  let ownLoaded = false;
  let publicError = null;
  try {
    const fb = await onlineFirebaseTimeout(loadFirebasePhoneRuntime(), 9000, "Finder.KL-Anmeldung");
    const uid = fb.auth.currentUser?.uid || "";
    if (!uid) throw new Error("Online-Anmeldung fehlt.");
    if (finderRuntimeUid && finderRuntimeUid !== uid) {
      try { finderIncomingLikesUnsub?.(); } catch {}
      finderIncomingLikesUnsub = null;
      finderIncomingLikesUid = "";
      clearTimeout(finderIncomingLikesRetryTimer);
      finderIncomingLikesRetryTimer = null;
      stopFinderOnlineChat();
      finderOnlineProfiles = [];
      finderOnlineOwnProfile = null;
    }
    finderRuntimeUid = uid;

    // Das eigene Profil wird getrennt vom öffentlichen Feed geladen. Ein Fehler
    // im Feed darf das vorhandene eigene Profil nicht mehr als „verschwunden“ anzeigen.
    try {
      const ownSnap = await onlineFirebaseTimeout(
        fb.getDoc(fb.doc(fb.db, "finderProfiles", uid)),
        8000,
        "Eigenes Finder.KL-Profil"
      );
      finderOnlineOwnProfile = ownSnap.exists() ? finderOnlineProfileFromData(uid, ownSnap.data()) : null;
      ownLoaded = true;
      const finder = ensureFinderState();
      const registered = !!finderOnlineOwnProfile;
      const visible = !!finderOnlineOwnProfile?.online;
      if (finder.onlineProfileRegistered !== registered || finder.onlineVisible !== visible) {
        finder.onlineProfileRegistered = registered;
        finder.onlineVisible = visible;
        window.LifeBuilderSaveControl?.applyRemote?.(() => save());
      }
    } catch (error) {
      console.warn("Eigenes Finder.KL-Profil konnte nicht geladen werden", error);
      if (!finderOnlineOwnProfile) publicError = error;
    }

    try {
      const onlineSnap = await onlineFirebaseTimeout(
        fb.getDocs(fb.query(fb.collection(fb.db, "finderProfiles"), fb.where("online", "==", true), fb.limit(50))),
        9000,
        "Finder.KL-Spielerliste"
      );
      finderOnlineProfiles = onlineSnap.docs
        .filter((docSnap) => docSnap.id !== uid)
        .map((docSnap) => finderOnlineProfileFromData(docSnap.id, docSnap.data()))
        .filter((profile) => profile.age >= 18);
    } catch (error) {
      publicError = error;
      console.warn("Finder.KL-Spielerliste konnte nicht geladen werden", error);
      // Vorhandene Cache-Profile bleiben sichtbar, statt die App leer zu machen.
    }

    finderOnlineLoadState = ownLoaded || finderOnlineOwnProfile ? "ready" : "error";
    finderOnlineLoadError = publicError && !ownLoaded ? String(publicError?.message || publicError) : "";
    finderOnlineLastLoadedAt = Date.now();
    startFinderIncomingLikesListener(item).catch(console.warn);
    if (publicError && !ownLoaded) throw publicError;
  } catch (error) {
    finderOnlineLoadState = "error";
    finderOnlineLoadError = String(error?.message || error || "Finder.KL konnte nicht verbunden werden.");
    console.warn("Finder online profiles failed", error);
    window.LifeBuilderFirebaseCore?.scheduleReconnect?.(500);
    addFeed(`Finder.KL Online konnte nicht aktualisiert werden: ${error.message || error}`);
  }
  if (item && els.dialog?.open && els.dialog.querySelector('.finder-app')) refreshDeviceApp("finder", item);
}

async function saveFinderOnlineProfile(form, item) {
  try {
    const fb = await loadFirebasePhoneRuntime();
    const uid = fb.auth.currentUser?.uid;
    if (!uid) throw new Error("Bitte zuerst mit deinem JK.Games-Account anmelden.");
    const data = new FormData(form);
    const displayName = String(data.get("displayName") || `${state.firstName || "Spieler"} ${state.lastName || ""}`).trim().replace(/\s+/g, " ").slice(0, 40);
    if (displayName.length < 3) throw new Error("Bitte einen Namen mit mindestens 3 Zeichen eingeben.");
    const activePet = finderPetSnapshot(activeCharacterPet());
    const profile = {
      uid,
      displayName,
      gender: data.get("gender") === "female" ? "female" : "male",
      age: Math.max(18, Math.min(99, Math.round(Number(data.get("age") || age() || 18)))),
      city: String(data.get("city") || state.worldLocation || state.homeCity || "Deutschland").trim().slice(0, 50),
      job: String(data.get("job") || state.job || "JK.Games-Spieler/in").trim().slice(0, 60),
      bio: String(data.get("bio") || "Ich bin ein echter JK.Games-Spieler.").trim().slice(0, 240),
      interests: String(data.get("interests") || "Freizeit, Musik, Reisen").split(",").map((entry) => entry.trim()).filter(Boolean).slice(0, 5),
      intention: String(data.get("intention") || "jemanden zum Kennenlernen").trim().slice(0, 100),
      online: data.get("online") === "on",
      createdAtMs: finderOnlineOwnProfile?.createdAtMs ? Number(finderOnlineOwnProfile.createdAtMs) : Date.now(),
      updatedAtMs: Date.now(),
      lastSeenAtMs: Date.now(),
      ...(activePet ? { pet: activePet } : {})
    };
    // Vollständig ersetzen statt mit alten Profilfeldern zu verschmelzen. Dadurch
    // werden veraltete Felder aus früheren Versionen entfernt, die neue Regeln
    // sonst als ungültig ablehnen würden.
    await fb.setDoc(fb.doc(fb.db, "finderProfiles", uid), profile);
    const finder = ensureFinderState();
    finder.onlineProfileRegistered = true;
    finder.onlineVisible = profile.online;
    save();
    addFeed(`Finder.KL-Profil gespeichert und ${profile.online ? "online" : "offline"} gestellt.`);
    await loadFinderOnlineProfiles(true, item);
  } catch (error) {
    addFeed(`Finder.KL-Profil konnte nicht gespeichert werden: ${error.message || error}`);
  }
}

async function setFinderOnlinePresence(enabled, item) {
  try {
    const fb = await loadFirebasePhoneRuntime();
    const uid = fb.auth.currentUser?.uid;
    if (!uid || !finderOnlineOwnProfile) throw new Error("Erstelle zuerst dein Finder.KL-Profil.");
    await fb.updateDoc(fb.doc(fb.db, "finderProfiles", uid), { online: !!enabled, updatedAtMs: Date.now(), lastSeenAtMs: Date.now() });
    ensureFinderState().onlineVisible = !!enabled;
    save();
    addFeed(`Finder.KL: Du bist jetzt ${enabled ? "online" : "offline"}.`);
    await loadFinderOnlineProfiles(true, item);
  } catch (error) {
    addFeed(`Online-Status konnte nicht geändert werden: ${error.message || error}`);
  }
}

async function finderOnlineLike(profile) {
  const fb = await loadFirebasePhoneRuntime();
  const uid = fb.auth.currentUser?.uid;
  const targetUid = profile?.onlineUid;
  if (!uid || !targetUid || uid === targetUid) return false;
  await fb.setDoc(fb.doc(fb.db, "finderLikes", uid, "targets", targetUid), {
    fromUid: uid,
    toUid: targetUid,
    createdAtMs: Date.now()
  });
  const mutual = await fb.getDoc(fb.doc(fb.db, "finderLikes", targetUid, "targets", uid));
  return mutual.exists();
}

function finderConversationIdForUids(uidA, uidB) {
  return [String(uidA || ""), String(uidB || "")].sort().join("_");
}

function finderOnlineChatMessageHtml(message, ownUid) {
  const mine = String(message.senderUid || "") === String(ownUid || "");
  const time = new Date(Number(message.createdAtMs || Date.now())).toLocaleTimeString("de-DE", { hour: "2-digit", minute: "2-digit" });
  return `<p class="${mine ? "me" : "them"}"><span>${escapeHtml(message.text || "")}</span><small>${time}</small></p>`;
}

function stopFinderOnlineChat() {
  try { finderOnlineChatUnsub?.(); } catch {}
  finderOnlineChatUnsub = null;
  finderOnlineChatConversationId = "";
  finderOnlineChatProfileId = "";
  finderOnlineChatMessages = [];
  finderOnlineChatState = "idle";
  finderOnlineChatError = "";
  finderOnlineChatItem = null;
}

async function startFinderOnlineChat(profile, item) {
  if (!profile || profile.source !== "player" || !profile.onlineUid) return stopFinderOnlineChat();
  if (finderOnlineChatStartPromise && finderOnlineChatProfileId === profile.id) return finderOnlineChatStartPromise;
  finderOnlineChatStartPromise = (async () => {
  try {
    const fb = await loadFirebasePhoneRuntime();
    const ownUid = fb.auth.currentUser?.uid || "";
    if (!ownUid) throw new Error("Bitte zuerst mit deinem JK.Games-Account anmelden.");
    const conversationId = finderConversationIdForUids(ownUid, profile.onlineUid);
    if (finderOnlineChatUnsub && finderOnlineChatConversationId === conversationId) return;
    stopFinderOnlineChat();
    finderOnlineChatState = "loading";
    finderOnlineChatProfileId = profile.id;
    finderOnlineChatConversationId = conversationId;
    finderOnlineChatItem = item;
    const participantUids = [ownUid, profile.onlineUid].sort();
    const conversationRef = fb.doc(fb.db, "finderConversations", conversationId);
    // Create-if-missing without reading a non-existent private document first.
    // For an existing conversation the immutable createdAt check rejects this
    // harmless create attempt; the listener below can then read the real document.
    try {
      const now = Date.now();
      await fb.setDoc(conversationRef, {
        participantUids,
        userA: participantUids[0],
        userB: participantUids[1],
        createdAtMs: now,
        updatedAtMs: now,
        lastMessage: ""
      });
    } catch (error) {
      const code = String(error?.code || "");
      if (!code.includes("permission-denied")) console.debug("Finder conversation already exists or could not be initialized", error);
    }
    const messagesQuery = fb.query(
      fb.collection(fb.db, "finderConversations", conversationId, "messages"),
      fb.orderBy("createdAtMs", "asc"),
      fb.limit(200)
    );
    finderOnlineChatUnsub = fb.onSnapshot(messagesQuery, (snapshot) => {
      finderOnlineChatMessages = snapshot.docs.map((entry) => ({ id: entry.id, ...entry.data() }));
      finderOnlineChatState = "ready";
      finderOnlineChatError = "";
      const finder = ensureFinderState();
      if (els.dialog?.open && els.dialog.querySelector(".finder-app") && finder.view === "chat" && finder.activeProfileId === profile.id) refreshDeviceApp("finder", finderOnlineChatItem || item);
    }, (error) => {
      finderOnlineChatState = "error";
      finderOnlineChatError = String(error?.message || error || "Chat konnte nicht geladen werden.");
      addFeed(`Finder.KL Chat: ${finderOnlineChatError}`);
    });
  } catch (error) {
    finderOnlineChatState = "error";
    finderOnlineChatError = String(error?.message || error || "Chat konnte nicht geöffnet werden.");
    addFeed(`Finder.KL Chat: ${finderOnlineChatError}`);
    if (els.dialog?.open && els.dialog.querySelector(".finder-app")) refreshDeviceApp("finder", item);
  } finally {
    finderOnlineChatStartPromise = null;
  }
  })();
  return finderOnlineChatStartPromise;
}

async function sendFinderOnlineMessage(profile, text, item) {
  const clean = String(text || "").trim().slice(0, 360);
  if (!profile?.onlineUid || !clean) return addFeed("Schreibe zuerst eine Nachricht.");
  try {
    const fb = await loadFirebasePhoneRuntime();
    const ownUid = fb.auth.currentUser?.uid || "";
    if (!ownUid) throw new Error("Bitte zuerst mit deinem JK.Games-Account anmelden.");
    const participantUids = [ownUid, profile.onlineUid].sort();
    const conversationId = finderConversationIdForUids(ownUid, profile.onlineUid);
    const conversationRef = fb.doc(fb.db, "finderConversations", conversationId);
    const now = Date.now();
    try {
      await fb.setDoc(conversationRef, {
        participantUids,
        userA: participantUids[0],
        userB: participantUids[1],
        createdAtMs: now,
        updatedAtMs: now,
        lastMessage: clean.slice(0, 100)
      });
    } catch (createError) {
      // Existing conversation: only mutable summary fields are changed.
      await fb.updateDoc(conversationRef, { updatedAtMs: now, lastMessage: clean.slice(0, 100) });
    }
    await fb.addDoc(fb.collection(fb.db, "finderConversations", conversationId, "messages"), {
      senderUid: ownUid,
      recipientUid: profile.onlineUid,
      participantUids,
      text: clean,
      createdAtMs: Date.now()
    });
    if (!finderOnlineChatUnsub || finderOnlineChatConversationId !== conversationId) await startFinderOnlineChat(profile, item);
  } catch (error) {
    addFeed(`Finder.KL Nachricht konnte nicht gesendet werden: ${error.message || error}`);
  }
}

