  if (!Array.isArray(save.phoneNotesList)) {
    save.phoneNotesList = (save.phoneNotes || "").trim()
      ? [{ id: `note-${Date.now()}`, text: String(save.phoneNotes).trim(), createdAt: Date.now(), updatedAt: Date.now() }]
      : [];
  }
  save.phoneEditingNoteId ||= "";
  save.installedPhoneApps = Array.isArray(save.installedPhoneApps)
    ? [...new Set(save.installedPhoneApps.filter((id) => [
        "finder", "finster", "event", "dailygifts", "dailyquests",
        "ringpack-neon", "smspack-classic",
        "aergermensch-kl", "grundstueck-kampf", "paket-chaos", "reaktions-battle"
      ].includes(id)))]
    : [];
  save.finder = normalizeFinderSave(save.finder, save);
  save.starterHome ||= { city: save.homeCity || "Essen", type: "Einraumwohnung", rooms: ["Eingang", "Wohn-/Schlafraum", "Küche", "Bad"], rentable: false, active: true, dailyRent: 65, lastPaidDay: save.day || 1 };
  if (save.starterHome.active == null) save.starterHome.active = true;
  save.starterHome.dailyRent = Math.max(0, Number(save.starterHome.dailyRent ?? 65) || 65);
  save.starterHome.lastPaidDay = Math.max(1, Number(save.starterHome.lastPaidDay || save.day || 1));
  save.onlineBanking ||= false;
  save.bankAvailable = save.onlineBanking === true || save.bankAvailable === true;
  save.bankOpeningCreditGranted = save.bankOpeningCreditGranted === true || (save.onlineBanking === true && Number(save.bank || 0) >= JK_RESET_V180.bankOpeningCredit);
  save.bankOpeningCreditPending = !save.bankOpeningCreditGranted;
  save.bankOpenedAtMs = Math.max(0, Number(save.bankOpenedAtMs || 0));
  save.exchangeEnabled ||= false;
  save.tradingEnabled ||= false;
  if (save.tradingEnabled) save.exchangeEnabled = true;
