  save.tradingPositions = Array.isArray(save.tradingPositions)
    ? save.tradingPositions.filter((entry) => entry && typeof entry === "object" && entry.id && Number(entry.amount) > 0)
    : [];
  save.phoneBattery ??= 100;
  save.inventoryCategory ||= "all";
  save.inventoryOrder = Array.isArray(save.inventoryOrder) ? [...new Set(save.inventoryOrder.filter((id) => typeof id === "string" && id))] : [];
  save.inventorySlots = Array.isArray(save.inventorySlots)
    ? save.inventorySlots.map((id) => typeof id === "string" && id ? id : null)
    : [...save.inventoryOrder];
  save.deviceExchangeGroup ||= "etf";
