document.addEventListener("visibilitychange", () => { if (document.hidden) flushLocalSaveNow(); });

function clamp(value, min = 0, max = 100) {
  return Math.max(min, Math.min(max, value));
}

function fillCityOptions() {
  const citySelect = els.form?.querySelector('[name="homeCity"]');
  if (!citySelect) return;
  const current = citySelect.value || "Essen";
  citySelect.innerHTML = germanCities.map((city) => `<option value="${city}">${city}</option>`).join("");
  citySelect.value = germanCities.includes(current) ? current : "Essen";
}

function setSetupView(view) {
  const isStart = view === "start";
  els.startHero?.classList.toggle("hidden", !isStart);
  document.querySelector(".start-actions")?.classList.toggle("hidden", !isStart);
  els.slotView?.classList.toggle("hidden", view !== "slots");
  els.settingsView?.classList.toggle("hidden", view !== "settings");
  els.loadingView?.classList.toggle("hidden", view !== "loading");
  els.form?.classList.toggle("hidden", view !== "creator");
  if (view === "slots") renderSaveSlots();
}

function openSettingsOverlay() {
  els.setup.classList.remove("hidden");
  els.setup.classList.add("settings-overlay");
  setSetupView("settings");
}

function closeSettingsOverlay() {
  els.setup.classList.remove("settings-overlay");
  if (state) {
    els.setup.classList.add("hidden");
    return;
  }
  setSetupView("start");
}

function startGameLoading(nextState) {
  startLoading({
    nextState,
    duration: 4200,
    infos: [
      "JK.Games wird gestartet.",
      "Dein Charakter und Spielstand werden geladen.",
      "Cottbus und die Online-Bereiche werden vorbereitet.",
      "Gleich geht es los."
    ]
  });
}

function startLoading({ nextState = null, duration = 12000, infos = loadingInfos, onComplete = null } = {}) {
  if (nextState) state = nextState;
  if (state) save();
  loadingDuration = duration;
  activeLoadingInfos = infos;
  loadingComplete = onComplete;
  isLoadingGame = true;
  loadingStartedAt = Date.now();
  clearInterval(loadingTimer);
  els.setup.classList.remove("hidden", "settings-overlay");
  els.game.classList.add("hidden");
  setSetupView("loading");
  updateLoadingView();
  loadingTimer = setInterval(updateLoadingView, 120);
}

function updateLoadingView() {
  const elapsed = Date.now() - loadingStartedAt;
  const progress = Math.min(1, elapsed / loadingDuration);
  const percent = Math.round(progress * 100);
  if (els.loadingFill) els.loadingFill.style.width = `${percent}%`;
  if (els.loadingPercent) els.loadingPercent.textContent = `${percent}%`;
  if (els.loadingInfo) {
    const infoTime = Math.max(1, loadingDuration / Math.max(1, activeLoadingInfos.length));
    const infoIndex = Math.min(activeLoadingInfos.length - 1, Math.floor(elapsed / infoTime));
    els.loadingInfo.textContent = activeLoadingInfos[infoIndex];
  }
  if (progress >= 1) {
    clearInterval(loadingTimer);
    loadingTimer = null;
    isLoadingGame = false;
    const done = loadingComplete;
    loadingComplete = null;
    if (done) done();
    render();
  }
}

function renderSaveSlots() {
  if (!els.saveSlotGrid) return;
  els.saveSlotGrid.innerHTML = Array.from({ length: 4 }, (_, index) => {
    const saveData = saveSlots[index];
    const name = saveData ? `${saveData.firstName} ${saveData.lastName}` : "Neuer Charakter";
    const meta = saveData ? `Tag ${saveData.day} · ${saveData.homeCity}` : "Freier Speicherplatz";
    const plus = saveData ? "" : '<span class="slot-plus">+</span>';
    return `
      <button class="save-slot ${saveData ? "filled" : "empty"}" data-save-slot="${index}" type="button">
        ${plus}
        <strong>${escapeHtml(name)}</strong>
        <small>${escapeHtml(meta)}</small>
      </button>
    `;
  }).join("");
  els.saveSlotGrid.querySelectorAll("[data-save-slot]").forEach((button) => {
    button.addEventListener("click", () => selectSaveSlot(Number(button.dataset.saveSlot)));
  });
}

function selectSaveSlot(index) {
  selectedSlot = index;
  const saveData = saveSlots[index];
  if (saveData) {
    startGameLoading(saveData);
    return;
  }
  fillCityOptions();
  els.form?.reset();
  const dateInput = els.form?.querySelector('[name="birthDate"]');
  if (dateInput) {
    dateInput.max = latestBirthDateForAge(18);
    dateInput.value = "2000-01-01";
  }
  setSetupView("creator");
}

function latestBirthDateForAge(minimumAge) {
  const today = new Date();
  const year = today.getFullYear() - Math.max(0, Number(minimumAge) || 0);
  const month = String(today.getMonth() + 1).padStart(2, "0");
  const day = String(today.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function calculateAge(birthDate) {
  const born = new Date(`${birthDate}T00:00:00`);
  const today = new Date();
  let age = today.getFullYear() - born.getFullYear();
  const birthdayPassed = today.getMonth() > born.getMonth() || (today.getMonth() === born.getMonth() && today.getDate() >= born.getDate());
  if (!birthdayPassed) age -= 1;
  return age;
}

function applySettings() {
  document.body.classList.remove("gfx-minimum", "gfx-medium", "gfx-high", "gfx-diamond", "gfx-ultra");
  document.body.classList.add(`gfx-${settings.graphicsQuality || "high"}`);
  if (els.customMusicLink) els.customMusicLink.value = settings.customMusicLink || "";
  if (els.musicVolume) els.musicVolume.value = settings.musicVolume;
  if (els.effectVolume) els.effectVolume.value = settings.effectVolume;
  if (els.graphicsQuality) els.graphicsQuality.value = settings.graphicsQuality;
  updateMusicVolume();
  if (!settings.musicEnabled) {
    stopMenuMusic();
    clearCustomMusicPlayer();
  }
}

function clearCustomMusicPlayer() {
  if (!els.customMusicPlayer) return;
  els.customMusicPlayer.classList.add("hidden");
  els.customMusicPlayer.innerHTML = "";
}

function renderCustomMusic() {
  const link = settings.customMusicLink?.trim();
  const data = youtubeVideoData(link);
  if (!els.customMusicPlayer) return false;
  if (!data.id) {
    clearCustomMusicPlayer();
    alert("Der YouTube-Link konnte nicht erkannt werden. Bitte füge einen normalen YouTube-, YouTube-Music-, Shorts-, Live- oder youtu.be-Videolink ein.");
    return false;
  }
  stopMenuMusic();
  clearCustomMusicPlayer();
  settings.musicEnabled = true;
  settings.musicSource = "youtube";
  saveSettings();
  els.customMusicPlayer.classList.remove("hidden");
  const origin = /^https?:$/.test(location.protocol) && location.origin ? `&origin=${encodeURIComponent(location.origin)}` : "";
  const playlist = data.list ? `&list=${encodeURIComponent(data.list)}` : `&loop=1&playlist=${encodeURIComponent(data.id)}`;
  els.customMusicPlayer.innerHTML = `
    <iframe
      title="Eigene YouTube-Musik"
      src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(data.id)}?autoplay=1&playsinline=1&controls=1&rel=0&enablejsapi=1${playlist}${origin}"
      allow="autoplay; encrypted-media; picture-in-picture"
      referrerpolicy="strict-origin-when-cross-origin"
      allowfullscreen
    ></iframe>
    <p>Die Musik läuft im eingebetteten YouTube-Player. Mit „Musik stoppen“ wird sie vollständig beendet.</p>
  `;
  els.customMusicPlayer.querySelector("iframe")?.addEventListener("load", updateMusicVolume, { once: true });
  return true;
}

function youtubeVideoData(link) {
  if (!link) return { id: "", list: "" };
  const value = String(link).trim();
  try {
    const url = new URL(value);
    const host = url.hostname.toLowerCase().replace(/^www\./, "").replace(/^music\./, "");
    let id = "";
    if (host === "youtu.be") id = url.pathname.split("/").filter(Boolean)[0] || "";
    if (host.endsWith("youtube.com")) {
      id = url.searchParams.get("v") || "";
      if (!id) {
        const parts = url.pathname.split("/").filter(Boolean);
        if (["embed", "shorts", "live"].includes(parts[0])) id = parts[1] || "";
      }
    }
    return {
      id: /^[A-Za-z0-9_-]{6,}$/.test(id) ? id : "",
      list: url.searchParams.get("list") || ""
    };
  } catch {
    const match = value.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|shorts\/|live\/))([A-Za-z0-9_-]{6,})/i);
    return { id: match ? match[1] : "", list: "" };
  }
}

function youtubeId(link) {
  return youtubeVideoData(link).id;
}

function ensureAudio(event = null) {
  const AudioCtor = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtor) return null;

  const mayUnlock = hasTransientUserGesture(event);
  if (!audioContext) {
    if (!mayUnlock) return null;
    try {
      audioContext = new AudioCtor();
    } catch {
      return null;
    }
  }

  if (audioContext.state === "suspended" && mayUnlock) {
    audioContext.resume().catch(() => {});
  }
  return audioContext.state === "closed" ? null : audioContext;
}

function stopMenuMusic() {
  clearInterval(menuMusicTimer);
  menuMusicTimer = null;
  menuMusicNodes.forEach((node) => {
    try { node.stop?.(); } catch {}
    try { node.disconnect?.(); } catch {}
  });
  menuMusicNodes = [];
}

function stopAllMusic({ persist = true } = {}) {
  stopMenuMusic();
  clearCustomMusicPlayer();
  settings.musicEnabled = false;
  if (persist) saveSettings();
}

function updateMusicVolume() {
  const volume = Math.max(0, Math.min(100, Number(settings.musicVolume) || 0));
  const master = menuMusicNodes[0];
  if (master?.gain) master.gain.value = volume / 100 * 0.2;
  const youtubeFrame = els.customMusicPlayer?.querySelector("iframe");
  if (youtubeFrame?.contentWindow) {
    youtubeFrame.contentWindow.postMessage(JSON.stringify({ event: "command", func: "setVolume", args: [volume] }), "*");
  }
}

function playCasinoSound(kind = "click") {
  const ctx = ensureAudio();
  if (!ctx || ctx.state !== "running") return false;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  const volume = (Number(settings.effectVolume) || 0) / 100;
  const freq = kind === "win" ? 880 : kind === "spin" ? 440 : 260;
  osc.type = kind === "win" ? "triangle" : "sine";
  osc.frequency.setValueAtTime(freq, ctx.currentTime);
  osc.frequency.exponentialRampToValueAtTime(freq * (kind === "win" ? 1.8 : 0.7), ctx.currentTime + 0.18);
  gain.gain.setValueAtTime(0.001, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.12 * volume, ctx.currentTime + 0.02);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.25);
  osc.connect(gain);
  gain.connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + 0.28);
}

function triggerWinExplosion(amountCents) {
  if (amountCents < 100000 || settings.graphicsQuality === "minimum") return;
  playCasinoSound("win");
  const burst = document.createElement("div");
  burst.className = "win-explosion";
  burst.innerHTML = `<strong>${formatCents(amountCents)}</strong><span>MEGA GEWINN</span>`;
  document.body.appendChild(burst);
  setTimeout(() => burst.remove(), 1800);
}

function triggerJackpotFireworks(amountCents) {
  playCasinoSound("win");
  const burst = document.createElement("div");
  burst.className = "win-explosion fireworks";
  burst.innerHTML = `<strong>${formatCents(amountCents)}</strong><span>300 EURO FEUERWERK</span><i></i><i></i><i></i><i></i><i></i>`;
  document.body.appendChild(burst);
  setTimeout(() => burst.remove(), 2600);
}

function nowMs() {
  return Date.now();
}

function ensureSleepCooldownLimit() {
  if (!state?.cooldowns) return;
  const currentReadyAt = Number(state.cooldowns.sleep || 0);
  const latestAllowedReadyAt = nowMs() + actionRules.sleep.cooldown;
  // Auch bei bereits geöffneten oder sehr alten Spielständen darf niemals
  // mehr als der aktuelle Fünf-Minuten-Timer angezeigt werden.
  if (currentReadyAt > latestAllowedReadyAt) {
    state.cooldowns.sleep = latestAllowedReadyAt;
    state.sleepCooldownVersion = 3;
  }
}

function isSleepResetAction(action) {
  return actionRules?.[action]?.resetBySleep === true;
}

function normalizeLegacySleepResetCooldown(action) {
  if (!isSleepResetAction(action) || !state?.cooldowns) return;
  const marker = Number(state.cooldowns[action] || 0);
  // Alte Versionen speicherten hier einen Zeitstempel. Diese alten Wartezeiten
  // werden beim ersten Aufruf entfernt. Die neue Markierung 1 bedeutet:
  // bereits erledigt und erst nach dem nächsten Schlaf wieder verfügbar.
  if (marker > 1) delete state.cooldowns[action];
}

function readyAt(action) {
  if (action === "sleep") ensureSleepCooldownLimit();
  if (isSleepResetAction(action)) {
    normalizeLegacySleepResetCooldown(action);
    return Number(state.cooldowns?.[action] || 0) === 1 ? Number.MAX_SAFE_INTEGER : 0;
  }
  return state.cooldowns?.[action] || 0;
}

function isReady(action) {
  if (isSleepResetAction(action)) {
    normalizeLegacySleepResetCooldown(action);
    return Number(state.cooldowns?.[action] || 0) !== 1;
  }
  return nowMs() >= readyAt(action);
}

function setCooldown(action) {
  state.cooldowns ||= {};
  if (isSleepResetAction(action)) {
    state.cooldowns[action] = 1;
    return;
  }
  state.cooldowns[action] = nowMs() + actionRules[action].cooldown;
}

function waitText(action) {
  if (isSleepResetAction(action)) return isReady(action) ? "bereit" : "nach Schlafen";
  const left = Math.max(0, readyAt(action) - nowMs());
  if (left <= 0) return "bereit";
  const minutes = Math.ceil(left / minute);
  if (minutes >= 60) return `${Math.floor(minutes / 60)} Std. ${minutes % 60} Min.`;
  return `${minutes} Min.`;
}

function dailyMeta() {
  return `
    <div class="meta-strip">
      <span>Lernen ${waitText("learn")}</span>
      <span>Schlaf ${waitText("sleep")}</span>
      <span>Training ${waitText("train")}</span>
      <span>Lohn sofort</span>
    </div>
  `;
}

function gameCalendarDate() {
  return new Date(2026, 6, 9 + Math.max(0, Number(state?.day || 1) - 1));
}

function age() {
  if (!state?.birthDate) return 18;
  const birth = new Date(`${state.birthDate}T00:00:00`);
  const now = gameCalendarDate();
  let years = now.getFullYear() - birth.getFullYear();
  const hadBirthday = now.getMonth() > birth.getMonth() || (now.getMonth() === birth.getMonth() && now.getDate() >= birth.getDate());
  return hadBirthday ? years : years - 1;
}

function nextBirthdayInfo() {
  const now = gameCalendarDate();
  const birth = new Date(`${state?.birthDate || "2000-01-01"}T00:00:00`);
  let next = new Date(now.getFullYear(), birth.getMonth(), birth.getDate());
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if (next < today) next = new Date(now.getFullYear() + 1, birth.getMonth(), birth.getDate());
  const days = Math.max(0, Math.round((next - today) / 86400000));
  return {
    birth,
    now,
    next,
    days,
    dateText: birth.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit", year: "numeric" }),
    nextText: next.toLocaleDateString("de-DE", { day: "2-digit", month: "2-digit", year: "numeric" })
  };
}

function birthdayRewardForLevel(level = state?.level || 0) {
  const lv = Math.max(0, Number(level || 0));
  if (lv < 5) return { money: 1000, xp: 50, item: "Sandwich", amount: 2, label: "Ein kleines Geburtstagsset" };
  if (lv < 10) return { money: 5000, xp: 100, item: "Energy Drink", amount: 2, label: "Ein Geburtstagsset" };
  if (lv < 30) return { money: 25000, xp: 200, item: "Vitamine", amount: 3, label: "Ein wertvolles Geburtstagsset" };
  if (lv < 80) return { money: 100000, xp: 350, item: "Energy Drink", amount: 5, label: "Ein Premium-Geburtstagsset" };
  return { money: 500000, xp: 600, item: "Geburtstags-Trophäe", amount: 1, special: true, label: "Eine seltene Geburtstagstrophäe" };
}

function checkAnnualBirthdayGift() {
  if (!state?.birthDate) return false;
  state.birthdayGiftYears = Array.isArray(state.birthdayGiftYears) ? state.birthdayGiftYears : [];
  const info = nextBirthdayInfo();
  const isBirthday = info.now.getMonth() === info.birth.getMonth() && info.now.getDate() === info.birth.getDate();
  const year = info.now.getFullYear();
  if (!isBirthday || state.birthdayGiftYears.includes(year)) return false;
  const reward = birthdayRewardForLevel();
  if (window.LifeBuilderFinance?.creditIncome) window.LifeBuilderFinance.creditIncome(reward.money, "Geburtstagsgeschenk", { feed: false });
  else state.bank = Number(state.bank || 0) + reward.money;
  recordIncome("other", reward.money);
  if (reward.special) {
    state.items ||= [];
    state.items.push(`${reward.item} ${year}`);
  } else {
    const birthdayConsumables = {
      "Sandwich": { name: "Sandwich", id: "FOOD-SANDWICH", icon: "🍽️", kind: "food", effect: { hunger: 25 } },
      "Energy Drink": { name: "Energy Drink", id: "DRINK-ENERGY", icon: "⚡", kind: "drink", effect: { energy: 25, thirst: 5 } },
      "Vitamine": { name: "Vitamine", id: "MED-VITAMINS", icon: "💊", kind: "medicine", effect: { life: 10, energy: 8 } }
    };
    const item = birthdayConsumables[reward.item] || null;
    if (item && typeof addConsumable === "function") addConsumable(item, reward.amount);
    else {
      state.items ||= [];
      for (let i = 0; i < reward.amount; i += 1) state.items.push(reward.item);
    }
  }
  state.birthdayGiftYears.push(year);
  state.lastBirthdayGiftAt = Date.now();
  addXp(reward.xp, "Geburtstag");
  addFeed(`Geburtstagsgeschenk ${year}: ${euro.format(reward.money)}, ${reward.label} und ${reward.xp} EP erhalten.`);
  queuePurchaseConfirmation({ kind: "use", title: "Alles Gute zum Geburtstag!", name: `${euro.format(reward.money)} · ${reward.label}`, icon: "🎂" });
  save();
  return true;
}

function currentPlace() {
  return mapPlaces.find((place) => place.id === state.location) || mapPlaces[0];
}


const EMERGENCY_SHELTER_FREE_DAYS = 5;

const tenantRentalDistricts = [
  "Zentrum", "Nord", "Süd", "Ost", "West", "Altstadt", "Bahnhof", "Parkviertel", "Seeviertel", "Industriepark",
  "Gartenstadt", "Neustadt", "Am Markt", "Am Fluss", "Hafenviertel", "Hochfeld", "Sonnenhang", "Waldkante", "Campus", "Ring"
];

function buildTenantRentalOffers() {
  const smallPrices = [128, 211, 137, 149, 156, 164, 172, 181, 193, 204, 119, 132, 143, 151, 168, 176, 187, 198, 108, 159];
  const small = smallPrices.map((dailyRent, index) => {
    const rooms = dailyRent >= 165 ? 2 : 1;
    return {
      id: `tenant-small-${index + 1}`,
      tier: "small",
      tierName: "Kleine Mietwohnung",
      name: `${rooms === 1 ? "Einraum" : "Zweiraum"}-Wohnung ${String(index + 1).padStart(2, "0")}`,
      dailyRent,
      rooms,
      sqm: rooms === 1 ? 24 + (index % 8) * 2 : 41 + (index % 7) * 3,
      floors: 1,
      district: tenantRentalDistricts[index % tenantRentalDistricts.length],
      storageType: "Kellerbox"
    };
  });
  const medium = Array.from({ length: 30 }, (_, index) => {
    const dailyRent = 409 + Math.round(index * (589 / 29));
    const rooms = dailyRent < 610 ? 3 : dailyRent < 805 ? 4 : 5;
    return {
      id: `tenant-medium-${index + 1}`,
      tier: "medium",
      tierName: "Mittlere Mietwohnung",
      name: `${rooms}-Raum-Wohnung ${String(index + 1).padStart(2, "0")}`,
      dailyRent,
      rooms,
      sqm: 68 + rooms * 9 + (index % 6) * 3,
      floors: index > 22 ? 2 : 1,
      district: tenantRentalDistricts[(index + 5) % tenantRentalDistricts.length],
      storageType: index % 3 === 0 ? "Keller" : "Kellerbox"
    };
  });
  const large = Array.from({ length: 25 }, (_, index) => {
    const dailyRent = 2015 + Math.round(index * (1980 / 24));
    const rooms = Math.min(10, 6 + Math.floor(index / 5));
    return {
      id: `tenant-large-${index + 1}`,
      tier: "large",
      tierName: "Große Mietwohnung",
      name: `${rooms}-Raum-Premiumwohnung ${String(index + 1).padStart(2, "0")}`,
      dailyRent,
      rooms,
      sqm: 145 + rooms * 14 + (index % 5) * 8,
      floors: rooms >= 9 ? 3 : rooms >= 7 ? 2 : 1,
      district: tenantRentalDistricts[(index + 11) % tenantRentalDistricts.length],
      storageType: "Keller"
    };
  });
  return [...small, ...medium, ...large];
}

const tenantRentalOffers = buildTenantRentalOffers();

function tenantRentalOfferById(id) {
  return tenantRentalOffers.find((offer) => offer.id === id) || null;
}

function activeTenantRentalProperty() {
  const lease = state?.tenantLease;
  if (!lease || lease.active === false || !lease.property) return null;
  return { ...lease.property, isTenantRental: true, dailyRent: lease.dailyRent };
}

function isTenantRentalProperty(propertyOrId) {
  const property = typeof propertyOrId === "object" ? propertyOrId : null;
  const id = typeof propertyOrId === "string" ? propertyOrId : propertyOrId?.id;
  if (property?.isStarterHome || (id === "starter-home-rental" && state?.starterHome?.active)) return true;
  if (property?.isTenantRental) return true;
  return !!id && state?.tenantLease?.active !== false && state?.tenantLease?.property?.id === id;
}

function emergencyShelterDaysUsed() {
  if (!state) return 0;
  return Math.max(0, Number(state.day || 1) - Number(state.emergencyShelterStartedDay || 1));
}

function emergencyShelterDaysLeft() {
  return Math.max(0, EMERGENCY_SHELTER_FREE_DAYS - emergencyShelterDaysUsed());
}

function isEmergencyShelterAvailable() {
  return emergencyShelterDaysLeft() > 0;
}

function ownedResidentialProperties() {
  return (state?.properties || []).map((id) => findProperty(id)).filter((property) => property && propertyType(property) !== "garage");
}

function availableHomeProperties() {
  const tenant = activeTenantRentalProperty();
  const owned = ownedResidentialProperties().filter((property) => !state.rentedProperties?.[property.id]);
  if (tenant) return [tenant, ...owned];
  const starter = state?.starterHome?.active ? findProperty("starter-home-rental") : null;
  return starter ? [starter, ...owned] : owned;
}

function hasAccessibleHome() {
  return !!state && (availableHomeProperties().length > 0 || isEmergencyShelterAvailable());
}

function usesEmergencyShelter() {
  return !!state && availableHomeProperties().length === 0;
}

function currentAccessibleHomeProperty() {
  const tenant = activeTenantRentalProperty();
  if (tenant) return tenant;
  const available = availableHomeProperties();
  if (!available.length) return null;
  const selected = available.find((property) => property.id === state.activeHomePropertyId);
  return selected || available.find((property) => property.city === (state.worldLocation || state.homeCity)) || available.find((property) => property.city === state.homeCity) || available[0];
}

function isAtOwnHome() {
  return state?.location === "home" && (state.worldLocation || state.homeCity) === state.homeCity && hasAccessibleHome();
}

function isHomeDashboardAvailable() {
  // Sobald der Charakter physisch zuhause ist, müssen „Heute“ und „Arbeit“
  // zuverlässig verfügbar sein. Ein veraltetes homeDashboardActive=false darf
  // die beiden Hauptbereiche nicht mehr unsichtbar machen.
  return !!state
    && isAtOwnHome()
    && !state.localTravel
    && !state.worldTravel
    && !state.quickHomeTravel;
}

function isHotelDashboardAvailable() {
  return !!state
    && state.location === "hotel"
    && state.hotelStay?.active !== false
    && state.hotelStay?.city === (state.worldLocation || state.homeCity)
    && !state.localTravel
    && !state.worldTravel
    && !state.quickHomeTravel;
}

function isDailyDashboardAvailable() {
  return isHomeDashboardAvailable() || isHotelDashboardAvailable();
}

function canWorkAtCurrentPlace() {
  return isDailyDashboardAvailable();
}

function canSleepAtCurrentPlace() {
  return isHomeDashboardAvailable() || state?.location === "hotel";
}

function localPlaceName(place = currentPlace()) {
  if (!place) return "";
  if (place.id === "home" && state.worldLocation !== state.homeCity) return `Keine eigene Wohnung in ${state.worldLocation}`;
  return place.name;
}

function cityMarketLevel() {
  const city = state?.worldLocation || state?.homeCity || "Cottbus";
  return {
    Berlin: 3,
    München: 3,
    Hamburg: 3,
    "Frankfurt am Main": 3,
    Paris: 4,
    London: 4,
    "New York": 5,
    Dubai: 5,
    Tokyo: 5,
    Sydney: 5
  }[city] || 1;
}

const purchaseToastQueue = [];
let purchaseToastActive = false;

function purchaseSuccessKind(text = "") {
  const value = String(text);
  const lower = value.toLowerCase();
  const blocked = ["nicht gekauft", "nicht freigeschaltet", "kann nicht gekauft", "fehlerhaft", "brauchst du", "reicht nicht", "erst ab level", "noch nicht freigeschaltet"];
  if (blocked.some((entry) => lower.includes(entry))) return "";
  if (lower.includes("vollgetankt") || lower.includes("getankt:")) return "fuel";
  if (lower.includes("eingezahlt")) return "deposit";
  if (lower.includes("ausgezahlt") || lower.includes("eingelöst") || lower.includes("abgehoben")) return "withdraw";
  if (lower.includes("ersteigert")) return "auction";
  if (lower.includes("gebucht") || lower.includes("gestochen")) return "booking";
  if (lower.includes("gebaut") || lower.includes("ausgebaut")) return "build";
  if (lower.includes("gekauft") || lower.includes("erworben") || lower.includes("eingebaut") || lower.includes("freigeschaltet:")) return "purchase";
  return "";
}

function purchaseToastTitle(kind = "purchase") {
  return {
    purchase: "Kauf bestätigt",
    booking: "Buchung bestätigt",
    deposit: "Einzahlung bestätigt",
    withdraw: "Auszahlung bestätigt",
    sell: "Verkauf bestätigt",
    use: "Gegenstand benutzt",
    fuel: "Tankvorgang bestätigt",
    auction: "Auktion gewonnen",
    build: "Auftrag abgeschlossen"
  }[kind] || "Aktion bestätigt";
}

function purchaseToastIcon(kind = "purchase") {
  return { purchase: "🛍", booking: "✓", deposit: "↗", withdraw: "↙", sell: "💶", use: "🧰", fuel: "⛽", auction: "🏆", build: "🏗" }[kind] || "✓";
}

function normalizePurchaseToast(details = {}) {
  const kind = details.kind || purchaseSuccessKind(details.message || "") || "purchase";
  const quantity = Math.max(1, Math.floor(Number(details.quantity || 1)));
  return {
    kind,
    title: details.title || purchaseToastTitle(kind),
    icon: details.icon || purchaseToastIcon(kind),
    name: details.name || details.message || "Aktion erfolgreich",
    quantity,
    total: Number.isFinite(Number(details.total)) ? Number(details.total) : null,
    method: details.method || "",
    unit: details.unit || "",
    message: details.message || ""
  };
}

function queuePurchaseConfirmation(details = {}) {
  purchaseToastQueue.push(normalizePurchaseToast(details));
  if (!purchaseToastActive) showNextPurchaseConfirmation();
}

let purchaseToastHostObserver = null;

function purchaseToastLayer() {
  let layer = document.querySelector("[data-purchase-toast-layer]");
  if (!layer) {
    layer = document.createElement("div");
    layer.className = "purchase-toast-layer";
    layer.dataset.purchaseToastLayer = "1";
    document.body.appendChild(layer);
  }
  if (!purchaseToastHostObserver && typeof MutationObserver !== "undefined") {
    purchaseToastHostObserver = new MutationObserver(() => {
      if (layer.children.length) bringPurchaseToastToFront(layer);
    });
    purchaseToastHostObserver.observe(document.documentElement, {
      subtree: true,
      attributes: true,
      attributeFilter: ["open"]
    });
  }
  return layer;
}

function bringPurchaseToastToFront(layer) {
  if (!layer) return;
  const openDialogs = Array.from(document.querySelectorAll("dialog[open]"));
  const topDialog = openDialogs.at(-1);
  const target = topDialog || document.body;
  if (layer.parentElement !== target) target.appendChild(layer);
}

function syncGlobalToastStack() {
  const communicationLayer = document.querySelector("[data-communication-toast-layer]");
  const purchaseLayer = document.querySelector("[data-purchase-toast-layer]");
  const experienceLayer = document.querySelector("[data-experience-toast-layer]");
  const communicationHeight = communicationLayer?.querySelector(".communication-toast")
    ? Math.ceil(communicationLayer.getBoundingClientRect().height + 10)
    : 0;
  const purchaseHeight = purchaseLayer?.children.length
    ? Math.ceil(purchaseLayer.getBoundingClientRect().height + 10)
    : 0;
  document.documentElement.style.setProperty("--communication-toast-offset", `${communicationHeight}px`);
  document.documentElement.style.setProperty("--purchase-toast-offset", `${purchaseHeight}px`);
  if (purchaseLayer) bringPurchaseToastToFront(purchaseLayer);
  if (experienceLayer) {
    experienceLayer.classList.toggle("below-purchase-toast", !!purchaseLayer?.children.length);
    bringExperienceToastToFront(experienceLayer);
  }
  if (communicationLayer) bringCommunicationToastToFront(communicationLayer);
}

function hidePurchaseToastLayerWhenEmpty() {
  const layer = document.querySelector("[data-purchase-toast-layer]");
  if (!layer || layer.children.length) return;
  if (layer.parentElement !== document.body) document.body.appendChild(layer);
}

function showNextPurchaseConfirmation() {
  const details = purchaseToastQueue.shift();
  if (!details) {
    purchaseToastActive = false;
    hidePurchaseToastLayerWhenEmpty();
    return;
  }
  purchaseToastActive = true;
  const layer = purchaseToastLayer();
  const toast = document.createElement("div");
  toast.className = `purchase-toast is-${details.kind}`;
  const quantityText = details.unit ? `${details.quantity} ${details.unit}` : details.quantity > 1 ? `${details.quantity}×` : "";
  const totalText = details.total == null ? "" : euro.format(details.total);
  const methodText = details.method === "cash" ? "Bar bezahlt" : details.method === "card" ? "Mit Karte bezahlt" : details.method === "auto" ? "Bezahlt" : details.method;
  const meta = [quantityText, totalText, methodText].filter(Boolean).join(" · ");
  toast.innerHTML = `
    <div class="purchase-toast-burst" aria-hidden="true">${Array.from({ length: 10 }, (_, index) => `<i style="--i:${index}"></i>`).join("")}</div>
    <div class="purchase-toast-icon">${details.icon}</div>
    <div class="purchase-toast-copy">
      <small>${details.title}</small>
      <strong>${details.name}</strong>
      ${meta ? `<span>${meta}</span>` : details.message && details.message !== details.name ? `<span>${details.message}</span>` : ""}
    </div>
    <div class="purchase-toast-check">✓</div>
  `;
  layer.appendChild(toast);
  syncGlobalToastStack();
  requestAnimationFrame(() => {
    bringPurchaseToastToFront(layer);
    syncGlobalToastStack();
    toast.classList.add("show");
  });
  window.setTimeout(() => {
    toast.classList.remove("show");
    toast.classList.add("hide");
    window.setTimeout(() => {
      toast.remove();
      syncGlobalToastStack();
      showNextPurchaseConfirmation();
    }, 320);
  }, 2200);
}

function addFeed(text, options = {}) {
  state.feed.unshift(text);
  state.feed = state.feed.slice(0, 7);
  if (options.purchase) {
    queuePurchaseConfirmation({ ...options.purchase, message: text });
  } else {
    const kind = purchaseSuccessKind(text);
    if (kind) queuePurchaseConfirmation({ kind, name: text, message: text });
  }
}

function communicationToastLayer() {
  let layer = document.querySelector("[data-communication-toast-layer]");
  if (!layer) {
    layer = document.createElement("div");
    layer.className = "communication-toast-layer";
    layer.dataset.communicationToastLayer = "1";
    layer.setAttribute("popover", "manual");
    layer.setAttribute("aria-live", "assertive");
    layer.setAttribute("aria-atomic", "false");
    layer.innerHTML = `<div data-communication-outgoing-host></div><div data-communication-call-host></div><div data-communication-message-host></div>`;
    layer.addEventListener("click", (event) => {
      const answer = event.target.closest("[data-global-answer-call]");
      if (answer) {
        answerFirebaseCall(answer.dataset.globalAnswerCall)
          .catch((error) => addFeed(`Anruf konnte nicht angenommen werden: ${error.message || error}`));
        return;
      }
      const reject = event.target.closest("[data-global-reject-call]");
      if (reject) {
        rejectFirebaseCall(reject.dataset.globalRejectCall)
          .catch((error) => addFeed(`Anruf konnte nicht abgelehnt werden: ${error.message || error}`));
        return;
      }
      const endCall = event.target.closest("[data-global-end-call]");
      if (endCall) {
        endFirebaseCall().catch((error) => addFeed(`Anruf konnte nicht beendet werden: ${error.message || error}`));
        return;
      }
      const sms = event.target.closest("[data-global-open-sms]");
      if (sms) {
        state.phoneActiveContact = normalizePhoneNumber(sms.dataset.globalOpenSms);
        save();
        const phone = ownedPhoneItem();
        if (phone) openDeviceInterface(phone, "sms", false);
        else addFeed("Für SMS brauchst du zuerst ein Handy.");
        sms.closest(".communication-toast")?.remove();
        syncGlobalToastStack();
      }
      const dismiss = event.target.closest("[data-global-dismiss-notification]");
      if (dismiss) {
        dismiss.closest(".communication-toast")?.remove();
        syncGlobalToastStack();
      }
    });
    document.body.appendChild(layer);
  }
  bringCommunicationToastToFront(layer);
  return layer;
}

function communicationLayerHasContent(layer) {
  return !!layer?.querySelector(".communication-toast");
}

function bringCommunicationToastToFront(layer) {
  if (!layer) return;
  // Ein Popover liegt in der Browser-Top-Layer und bleibt dadurch auch über
  // geöffneten Spiel-/Handy-Dialogen sichtbar. Das frühere Verschieben in
  // Dialoge konnte den Banner durch deren Overflow/Transform abschneiden.
  if (layer.parentElement !== document.body) document.body.appendChild(layer);
  const shouldShow = communicationLayerHasContent(layer);
  if (typeof layer.showPopover === "function") {
    try {
      if (shouldShow && !layer.matches(":popover-open")) layer.showPopover();
      if (!shouldShow && layer.matches(":popover-open")) layer.hidePopover();
    } catch (error) {
      console.warn("Kommunikations-Popover konnte nicht umgeschaltet werden", error);
    }
  } else {
    layer.classList.toggle("is-visible", shouldShow);
  }
}

function syncOutgoingCallNotification(number = "", status = "", options = {}) {
  const layer = communicationToastLayer();
  const host = layer.querySelector("[data-communication-outgoing-host]");
  if (!host) return;
  clearTimeout(activePhoneOutgoingNoticeTimer);
  activePhoneOutgoingNoticeTimer = null;
  const normalized = normalizePhoneNumber(number || activePhoneCallPartner);
  if (!normalized || !status) {
    host.innerHTML = "";
    syncGlobalToastStack();
    return;
  }
  const active = options.active === true;
  host.innerHTML = `
    <article class="communication-toast communication-call-toast communication-outgoing-call show">
      <span class="communication-toast-icon">${active ? "◉" : "☎"}</span>
      <div class="communication-toast-copy">
        <small>${active ? "ANRUF AKTIV" : "AUSGEHENDER ANRUF"}</small>
        <strong>${escapeHtml(contactNameFor(normalized))}</strong>
        <span>${escapeHtml(status)}</span>
      </div>
      <div class="communication-toast-actions">
        <button type="button" class="reject" data-global-end-call>Auflegen</button>
      </div>
    </article>`;
  syncGlobalToastStack();
  if (options.autoClearMs) {
    activePhoneOutgoingNoticeTimer = window.setTimeout(() => syncOutgoingCallNotification("", ""), Number(options.autoClearMs));
  }
}

function finishOutgoingCallNotification(status = "") {
  if (activePhoneCallDirection !== "outgoing") return;
  if (status) syncOutgoingCallNotification(activePhoneCallPartner, status, { autoClearMs: 2800 });
  else syncOutgoingCallNotification("", "");
}

function syncIncomingCallNotifications(calls = []) {
  const layer = communicationToastLayer();
  const host = layer.querySelector("[data-communication-call-host]");
  const activeCalls = Array.isArray(calls) ? calls : [];
  host.innerHTML = activeCalls.map((call) => `
    <article class="communication-toast communication-call-toast" data-global-call-id="${escapeHtml(call.id)}">
      <span class="communication-toast-icon">☎</span>
      <div class="communication-toast-copy">
        <small>EINGEHENDER ANRUF</small>
        <strong>${escapeHtml(contactNameFor(call.caller))}</strong>
        <span>${escapeHtml(prettyPhoneNumber(call.caller))}</span>
      </div>
      <div class="communication-toast-actions">
        <button type="button" class="accept" data-global-answer-call="${escapeHtml(call.id)}">Annehmen</button>
        <button type="button" class="reject" data-global-reject-call="${escapeHtml(call.id)}">Ablehnen</button>
      </div>
    </article>
  `).join("");
  if (activeCalls.length) startPhoneRingtone();
  else stopPhoneRingtone();
  syncGlobalToastStack();
}

function showIncomingSmsNotification(message = {}) {
  const from = normalizePhoneNumber(message.from);
  if (!from) return;
  const layer = communicationToastLayer();
  const host = layer.querySelector("[data-communication-message-host]");
  const node = document.createElement("article");
  node.className = "communication-toast communication-sms-toast";
  node.dataset.globalSmsId = String(message.id || `sms-${Date.now()}`);
  node.innerHTML = `
    <span class="communication-toast-icon">✉</span>
    <div class="communication-toast-copy">
      <small>NEUE SMS</small>
      <strong>${escapeHtml(contactNameFor(from))}</strong>
      <span>${escapeHtml(String(message.text || "Neue Nachricht").slice(0, 100))}</span>
    </div>
    <div class="communication-toast-actions compact">
      <button type="button" class="accept" data-global-open-sms="${escapeHtml(from)}">Nachricht</button>
      <button type="button" class="neutral" data-global-dismiss-notification>×</button>
    </div>`;
  host.appendChild(node);
  playPhoneSmsTone();
  requestAnimationFrame(() => {
    node.classList.add("show");
    syncGlobalToastStack();
  });
  window.setTimeout(() => {
    if (!node.isConnected) return;
    node.classList.add("hide");
    window.setTimeout(() => {
      node.remove();
      syncGlobalToastStack();
    }, 260);
  }, 6500);
}

function normalizedMoneyAmount(value) {
  const amount = Number(value);
  return Number.isFinite(amount) && amount >= 0 ? Math.round(amount * 100) / 100 : NaN;
}

function canAfford(price) {
  if (!state) return false;
  normalizeMoneyBalances(state);
  const amount = normalizedMoneyAmount(price);
  return Number.isFinite(amount) && availablePlayerFunds(state) + 0.0001 >= amount;
}

function pay(price, preferCash = false, options = {}) {
  const amount = normalizedMoneyAmount(price);
  if (!Number.isFinite(amount)) {
    console.warn("Ungültiger Zahlungsbetrag", price, options);
    return false;
  }
  if (amount === 0) return true;
  const method = options.method || (preferCash ? "cash" : "auto");
  if (!canAffordWithMethod(amount, method)) return false;
  if (!debitPlayer(amount, method)) return false;
  allocateOutgoingPayment(amount, options.target || "treasury", options.taxRate ?? 0.19);
  if (options.awardXp !== false) addXp(Math.max(1, Math.min(20, Math.round(amount / 250))));
  normalizeMoneyBalances(state);
  return true;
}

function earn(amount) {
  payoutFromTreasury(amount);
}

function recordIncome(category, amount) {
  if (!state || !amount || amount <= 0) return;
  state.earnings ||= {};
  state.earnings[category] = (state.earnings[category] || 0) + Math.round(amount * 100) / 100;
}

function canAffordWithMethod(price, method = "auto") {
  if (!state) return false;
  normalizeMoneyBalances(state);
  const amount = normalizedMoneyAmount(price);
  if (!Number.isFinite(amount)) return false;
  if (method === "cash") return state.cash + 0.0001 >= amount;
  if (method === "card") return state.bank - amount + 0.0001 >= bankOverdraftFloor(state);
  return canAfford(amount);
}

function debitPlayer(price, method = "auto") {
  if (!state) return false;
  normalizeMoneyBalances(state);
  const amount = normalizedMoneyAmount(price);
  if (!Number.isFinite(amount) || !canAffordWithMethod(amount, method)) return false;
  const floor = bankOverdraftFloor(state);
  if (method === "cash") {
    state.cash = Math.max(0, state.cash - amount);
  } else if (method === "card") {
    state.bank = Math.max(floor, state.bank - amount);
  } else {
    let remaining = amount;
    const positiveBank = Math.min(remaining, Math.max(0, state.bank));
    state.bank -= positiveBank;
    remaining -= positiveBank;
    const cashPart = Math.min(remaining, Math.max(0, state.cash));
    state.cash -= cashPart;
    remaining -= cashPart;
    if (remaining > 0) state.bank = Math.max(floor, state.bank - remaining);
  }
  normalizeMoneyBalances(state);
  return true;
}

window.LifeBuilderMoneyAudit = {
  snapshot: () => moneyAuditSnapshot(state),
  validate: () => {
    const before = state ? JSON.stringify(moneyAuditSnapshot(state)) : "{}";
    normalizeMoneyBalances(state);
    const after = state ? JSON.stringify(moneyAuditSnapshot(state)) : "{}";
    return { ok: true, changed: before !== after, balances: moneyAuditSnapshot(state) };
  }
};

function allocateOutgoingPayment(amount, target = "treasury", taxRate = 0.19) {
  const tax = Math.max(0, Math.round(amount * taxRate * 100) / 100);
  const net = Math.max(0, amount - tax);
  state.taxAccount = (state.taxAccount || 0) + tax;
  if (target === "casino") {
    state.casinoAccount = (state.casinoAccount || 0) + net;
    state.casinoDailyProfit = (state.casinoDailyProfit || 0) + net;
  } else {
    state.publicTreasury = (state.publicTreasury || 0) + net;
  }
}

function shopTaxRate(item, marketKey = activeShopMarketKey) {
  if (typeof item?.taxRate === "number") return item.taxRate;
  if (marketKey === "snacks" || marketKey === "groceries") return 0.07;
  if (marketKey === "beverages" || marketKey === "pharmacy") return 0.19;
  if (isVehicleShopItem(item)) return 0.19;
  return 0.19;
}

function payoutFromTreasury(amount) {
  state.publicTreasury = Math.max(0, (state.publicTreasury || 0) - amount);
  state.bank += amount;
}

function payoutFromCasino(cents) {
  const amount = (cents || 0) / 100;
  state.casinoAccount = Math.max(0, (state.casinoAccount || 0) - amount);
  state.casinoDailyProfit = (state.casinoDailyProfit || 0) - amount;
  addXp(Math.max(2, Math.min(80, Math.round(amount / 150))));
  addWallet(cents);
}

function ensureCasinoHouseBankroll(minAmount = 100000000) {
  state.casinoAccount ||= 0;
  if (state.casinoAccount > 0) return false;
  const transfer = Math.min(minAmount, Math.max(0, state.publicTreasury || 0));
  if (transfer <= 0) return false;
  state.publicTreasury -= transfer;
  state.casinoAccount += transfer;
  addFeed(`Staatskasse investiert ${euro.format(transfer)} ins Casino-Konto.`);
  return true;
}

function settleCasinoDailyTax() {
  const profit = state.casinoDailyProfit || 0;
  if (profit <= 0) {
    state.casinoDailyProfit = 0;
    return;
  }
  const tax = Math.round(profit * 0.1 * 100) / 100;
  state.casinoAccount = Math.max(0, (state.casinoAccount || 0) - tax);
  state.taxAccount = (state.taxAccount || 0) + tax;
  state.casinoDailyProfit = 0;
}

function improveSkill(name, amount = 1) {
  state.skills[name] = Math.min(10, (state.skills[name] || 1) + amount);
}

function xpNeeded(level = state.level || 0) {
  return Math.min(1000000, Math.max(100, (level + 1) * 100));
}

const experienceToastQueue = [];
let experienceToastActive = false;
let experienceToastHostObserver = null;

function experienceToastLayer() {
  let layer = document.querySelector("[data-experience-toast-layer]");
  if (!layer) {
    layer = document.createElement("div");
    layer.className = "game-xp-toast-layer";
    layer.dataset.experienceToastLayer = "1";
    document.body.appendChild(layer);
  }
  if (!experienceToastHostObserver && typeof MutationObserver !== "undefined") {
    experienceToastHostObserver = new MutationObserver(() => {
      if (layer.children.length) bringExperienceToastToFront(layer);
    });
    experienceToastHostObserver.observe(document.documentElement, {
      subtree: true,
      attributes: true,
      attributeFilter: ["open"]
    });
  }
  return layer;
}

function bringExperienceToastToFront(layer) {
  if (!layer) return;
  const openDialogs = Array.from(document.querySelectorAll("dialog[open]"));
  const target = openDialogs.at(-1) || document.body;
  if (layer.parentElement !== target) target.appendChild(layer);
}

function queueExperienceToast(amount, reason = "Erfahrung erhalten", levelText = "") {
  const earned = Math.max(0, Math.round(Number(amount) || 0));
  if (!earned || typeof document === "undefined") return;
  experienceToastQueue.push({ earned, reason: reason || "Erfahrung erhalten", levelText });
  if (!experienceToastActive) showNextExperienceToast();
}

function showNextExperienceToast() {
  const entry = experienceToastQueue.shift();
  if (!entry) {
    experienceToastActive = false;
    const emptyLayer = document.querySelector("[data-experience-toast-layer]");
    if (emptyLayer && !emptyLayer.children.length && emptyLayer.parentElement !== document.body) document.body.appendChild(emptyLayer);
    return;
  }
  experienceToastActive = true;
  const layer = experienceToastLayer();
  bringExperienceToastToFront(layer);
  const toast = document.createElement("div");
  toast.className = "game-xp-toast";
  toast.innerHTML = `
    <span class="game-xp-toast-glow" aria-hidden="true"></span>
    <span class="game-xp-toast-badge">EP</span>
    <span class="game-xp-toast-copy">
      <strong>+${entry.earned} EP</strong>
      <small>${escapeHtml(entry.reason)}</small>
      ${entry.levelText ? `<em>${escapeHtml(entry.levelText)}</em>` : ""}
    </span>
  `;
  layer.appendChild(toast);
  syncGlobalToastStack();
  requestAnimationFrame(() => {
    syncGlobalToastStack();
    toast.classList.add("show");
  });
  window.setTimeout(() => {
    toast.classList.remove("show");
    toast.classList.add("hide");
    window.setTimeout(() => {
      toast.remove();
      syncGlobalToastStack();
      showNextExperienceToast();
    }, 300);
  }, 1850);
}

function showGameXpToast(amount, reason = "Game") {
  queueExperienceToast(amount, reason);
}

function addXp(amount, reason = "", options = {}) {
  if (!state || !amount) return 0;
  const earned = Math.max(0, Math.round(Number(amount) || 0));
  if (!earned) return 0;
  const { toast = true, toastReason = reason } = options;
  state.level ||= 0;
  state.xp ||= 0;
  const levelBefore = state.level;
  state.xp += earned;
  while (state.level < 100 && state.xp >= xpNeeded(state.level)) {
    state.xp -= xpNeeded(state.level);
    state.level += 1;
    state.skillPoints = (state.skillPoints || 0) + 1;
    addFeed(`Level ${state.level} erreicht. +1 Skillpunkt.`);
  }
  const levelText = state.level > levelBefore ? `Level ${state.level} erreicht · +1 Skillpunkt` : "";
  if (toast) queueExperienceToast(earned, toastReason || reason || "Erfahrung erhalten", levelText);
  return earned;
}

function awardSmallXp(reason, amount = 5) {
  return addXp(amount, reason);
}

function awardGameXp(amount, reason = "Game", options = {}) {
  const earned = Math.max(0, Math.floor(Number(amount) || 0));
  if (!earned) return 0;
  const { toast = true, feed = true } = options;
  recordGameMoodProgress(earned, reason);
  return addXp(earned, feed ? reason : "", { toast, toastReason: reason });
}


// V248: Gemeinsame Hauptcharakter-EP für alle acht Top Games.
// Die jeweiligen Spiele vergeben weiterhin ihre eigenen internen Belohnungen.
// Zusätzlich erhält der übergeordnete JK.Games-Hauptcharakter echte EP.
// Event-Keys verhindern doppelte Gutschriften desselben Ergebnisses; ein
// verstecktes Tageslimit gibt es nicht mehr, damit aktives Spielen immer zählt.
function awardTopGameMainXp(gameId, baseAmount, reason = "Top Games", options = {}) {
  if (!state) return 0;
  const cleanGameId = String(gameId || "topgames").trim().toLowerCase().replace(/[^a-z0-9_-]/g, "-") || "topgames";
  const base = Math.max(0, Math.min(250, Math.floor(Number(baseAmount) || 0)));
  if (!base) return 0;
  const day = Math.max(1, Number(state.day || 1));
  const characterLevel = Math.max(0, Math.min(100, Number(state.level || 0)));
  const levelMultiplier = 1 + Math.min(0.4, characterLevel * 0.005);
  const earned = Math.max(1, Math.round(base * levelMultiplier));
  const ledger = state.topGamesMainXp && typeof state.topGamesMainXp === "object" ? state.topGamesMainXp : {};
  if (Number(ledger.day || 0) !== day) {
    ledger.day = day;
    ledger.total = 0;
    ledger.byGame = {};
    ledger.recentKeys = [];
  }
  ledger.byGame ||= {};
  ledger.recentKeys = Array.isArray(ledger.recentKeys) ? ledger.recentKeys.slice(-120) : [];
  const eventKey = String(options.eventKey || "").slice(0, 140);
  if (eventKey && ledger.recentKeys.includes(eventKey)) return 0;
  ledger.total = Math.max(0, Number(ledger.total || 0)) + earned;
  ledger.byGame[cleanGameId] = Math.max(0, Number(ledger.byGame[cleanGameId] || 0)) + earned;
  if (eventKey) ledger.recentKeys.push(eventKey);
  state.topGamesMainXp = ledger;
  const result = awardGameXp(earned, `${reason} · Hauptcharakter`, { toast: options.toast !== false, feed: options.feed === true });
  save();
  return result;
}

window.JKGamesAwardMainGameXp = awardTopGameMainXp;
window.JKGamesTopGameXpStatus = () => {
  const ledger = state?.topGamesMainXp || {};
  return {
    day: Number(state?.day || 1),
    earned: Math.max(0, Number(ledger.total || 0)),
    cap: null,
    unlimited: true,
    level: Math.max(0, Math.min(100, Number(state?.level || 0))),
    byGame: { ...(ledger.byGame || {}) }
  };
};

function awardGameWinMoney(amount, reason = "Game") {
  const prize = Math.max(0, Math.round(Number(amount) || 0));
  if (!prize) return 0;
  payoutFromTreasury(prize);
  recordIncome("other", prize);
  normalizeMoneyBalances(state);
  addFeed(`${reason}: ${euro.format(prize)} Siegprämie ausgezahlt.`);
  return prize;
}

function meetsNeed(need) {
  if (!need) return true;
  for (let i = 0; i < need.length; i += 2) {
    if ((state.skills[need[i]] || 0) < need[i + 1]) return false;
  }
  return true;
}

function moodStatusLabel(value = state?.mood ?? 100) {
  const mood = Number(value || 0);
  if (mood >= 85) return "Ausgeglichen";
  if (mood >= 65) return "Gut gelaunt";
  if (mood >= 45) return "Angeschlagen";
  if (mood >= 25) return "Niedergeschlagen";
  return "Depressive Phase";
}

function moodImpactProfile(value = state?.mood ?? 100) {
  const mood = Number(value || 0);
  if (mood >= 75) return { needs: 1, recovery: 1, healthDay: 0, hungerMinute: .018, thirstMinute: .024, energyMinute: .008, healthMinute: 0 };
  if (mood >= 55) return { needs: 1.08, recovery: .94, healthDay: 0, hungerMinute: .024, thirstMinute: .032, energyMinute: .018, healthMinute: 0 };
  if (mood >= 35) return { needs: 1.22, recovery: .82, healthDay: 1, hungerMinute: .04, thirstMinute: .052, energyMinute: .05, healthMinute: .025 };
  if (mood >= 15) return { needs: 1.45, recovery: .68, healthDay: 3, hungerMinute: .07, thirstMinute: .09, energyMinute: .095, healthMinute: .08 };
  return { needs: 1.72, recovery: .52, healthDay: 6, hungerMinute: .11, thirstMinute: .14, energyMinute: .16, healthMinute: .16 };
}

function improveMood(amount = 1, reason = "", options = {}) {
  if (!state || !amount) return 0;
  const before = Number(state.mood ?? 78);
  const gain = Math.max(0, Number(amount) || 0);
  state.mood = clamp(before + gain);
  if (state.mood > before) state.moodPositiveDay = state.day || 1;
  if (reason && options.feed !== false && Math.floor(state.mood) > Math.floor(before)) addFeed(`Stimmung +${Math.max(1, Math.round(state.mood - before))}: ${reason}.`);
  return state.mood - before;
}

function reduceMood(amount = 1, reason = "") {
  if (!state || !amount) return 0;
  const before = Number(state.mood ?? 78);
  state.mood = clamp(before - Math.max(0, Number(amount) || 0));
  if (reason && Math.floor(state.mood) < Math.floor(before)) addFeed(`Stimmung gesunken: ${reason}.`);
  return before - state.mood;
}

function recordGameMoodProgress(xp = 0, reason = "Game") {
  if (!state || xp <= 0) return;
  const day = state.day || 1;
  if (state.moodGameGainDay !== day) {
    state.moodGameGainDay = day;
    state.moodGameGainToday = 0;
    state.moodGameXpBuffer = 0;
  }
  state.moodGameXpBuffer = Number(state.moodGameXpBuffer || 0) + Number(xp || 0);
  const available = Math.max(0, 8 - Number(state.moodGameGainToday || 0));
  const points = Math.min(available, Math.floor(state.moodGameXpBuffer / 20));
  if (points <= 0) return;
  state.moodGameXpBuffer -= points * 20;
  state.moodGameGainToday += points;
  improveMood(points, `${reason} hat Spaß gemacht`, { feed: false });
}

function settleMoodAfterSleep(completedDay = state?.day || 1) {
  if (!state) return;
  const activeDay = Number(state.moodPositiveDay || 0) === Number(completedDay || 0);
  reduceMood(activeDay ? .5 : 1.5, "ein neuer Alltagstag beginnt");
  state.moodGameGainDay = Number(completedDay || 0) + 1;
  state.moodGameGainToday = 0;
  state.moodGameXpBuffer = 0;
}

function nextDay(reason, options = {}) {
  const completedDay = state.day || 1;
  settleMoodAfterSleep(completedDay);
  try { window.LifeBuilderExpansion?.advancePetDay?.(completedDay); } catch (error) { console.warn("Haustier-Tageswechsel", error); }
  state.day += 1;
  settleTenantRentAfterSleep();
  settleFinderAfterSleep();
  const moodImpact = moodImpactProfile();
  state.hunger = clamp(state.hunger - 11 * moodImpact.needs);
  state.thirst = clamp(state.thirst - 14 * moodImpact.needs);
  state.energy = clamp(state.energy + 32 * moodImpact.recovery);
  updateHealthForNewDay();
  agePropertyCleanliness();
  state.workedDay = null;
  awardSmallXp("Neuer Tag", 8);
  settleDailyTaxesAfterSleep();
  settleDailyDebtCostsAfterSleep();
  if (options.collectRentalIncome) {
    const rentalIncome = collectRentalIncome();
    if (rentalIncome > 0) {
      payoutFromTreasury(rentalIncome);
      recordIncome("rent", rentalIncome);
      addTaxLiability(Math.round(rentalIncome * 0.12), "Mietsteuer");
      addFeed(`Mieteinnahmen beim Schlafen erhalten: ${euro.format(rentalIncome)}.`);
    }
  }
  if (state.hunger < 20 || state.thirst < 20) state.energy = clamp(state.energy - 18);
  settleBlackBusinessStaffCosts();
  settleBlackBusinessProtectionAfterSleep();
  if (reason) addFeed(reason);
  save();
  render();
}

function agePropertyCleanliness() {
  Object.values(state.propertyRooms || {}).forEach((rooms) => {
    Object.values(rooms || {}).forEach((room) => {
      if (!room?.cleaned) return;
      room.cleanedAt ||= state.day || 1;
      if ((state.day || 1) - room.cleanedAt >= 5) room.cleaned = false;
    });
  });
}

function resetDayAfterSleep() {
  state.workedDay = null;
  state.benefitClaimedDay = null;
  state.highlowDailyCents = 0;
  state.businessOfferCount = 0;
  state.businessOfferDay = Number(state.day || 1) + 1;
  state.businessOfferCooldownUntil = 0;
  state.cooldowns ||= {};
  ["learn", "train", "game", "casino"].forEach((action) => delete state.cooldowns[action]);
}

function sleepAndAdvanceDay(reason = "Du hast geschlafen und bist erholt.") {
  setCooldown("sleep");
  resetDayAfterSleep();
  settleCasinoDailyTax();
  state.publicTreasury = (state.publicTreasury || 0) + 100000000;
  nextDay(reason, { collectRentalIncome: true });
}

function updateHealthForNewDay() {
  state.health ??= 100;
  state.illness ||= "healthy";
  const beforeHealth = state.health;
  const hunger = Number(state.hunger ?? 100);
  const thirst = Number(state.thirst ?? 100);
  if (state.illness === "severe") {
    state.health = clamp(state.health - 12);
  } else if (state.illness === "sick") {
    state.health = clamp(state.health - 5);
  } else {
    state.health = clamp(state.health + 3);
    const roll = Math.random();
    if (roll < 0.01) {
      state.illness = "severe";
      state.health = clamp(state.health - 18);
      addFeed("Du bist schwer krank geworden. Gehe auf der lokalen Karte ins Krankenhaus.");
    } else if (roll < 0.06) {
      state.illness = "sick";
      state.health = clamp(state.health - 8);
      addFeed("Du fühlst dich krank. Arzneimittel oder Vitamine helfen.");
    }
  }
  const moodImpact = moodImpactProfile();
  if (moodImpact.healthDay > 0) state.health = clamp(state.health - moodImpact.healthDay);
  if (hunger <= 0 || thirst <= 0) {
    state.health = clamp(state.health - 8);
    addFeed("Hunger oder Durst ist leer. Deine Gesundheit sinkt jetzt stark, bis du etwas isst oder trinkst.");
  } else if (hunger <= 20 || thirst <= 20) {
    if (state.health > 90) state.health = Math.max(90, clamp(state.health - 3));
  } else if (hunger <= 50 || thirst <= 50) {
    if (state.health > 95) state.health = Math.max(95, clamp(state.health - 1));
  }
  if (state.health <= 25 && state.illness !== "severe") state.illness = "sick";
  notifyHealthDrop(beforeHealth, state.health, "Tageswechsel");
}

function applyRealtimeNeedsHealth() {
  if (!state) return;
  // V110: Charakterwerte sinken ausschließlich beim Tageswechsel durch Schlafen.
  // Der Zeitanker bleibt nur aus Kompatibilitätsgründen erhalten, damit ältere
  // Spielstände keine nachträglichen Echtzeit-Abzüge erhalten.
  state.lastNeedsHealthAt = Date.now();
}

function notifyHealthDrop(before, after, source = "Leben") {
  const from = Math.floor(Number(before ?? 100));
  const to = Math.floor(Number(after ?? 100));
  if (to >= from) return;
  const alerts = [];
  for (let level = from - 1; level >= to; level -= 1) {
    if (level <= 50 || level % 10 === 0) alerts.push(level);
  }
  alerts.forEach((level) => {
    const urgent = level <= 50 ? "Warnung" : "Hinweis";
    const action = level <= 50
      ? "Iss, trink oder nutze Arzneimittel, bevor es kritisch wird."
      : "Achte auf Essen, Trinken und Gesundheit.";
    addFeed(`${urgent}: Leben ist auf ${level}% gefallen (${source}). ${action}`);
  });
}

function healthStatusText() {
  const health = Math.round(state?.health ?? 100);
  const illness = state?.illness || "healthy";
  if (illness === "severe") return `Schwer krank · Leben ${health}%. Krankenhausbehandlung dringend nötig.`;
  if (illness === "sick") return `Krank · Leben ${health}%. Arznei hilft, Krankenhaus heilt sicher.`;
  return `Gesund · Leben ${health}%. Behandlung ist aktuell nicht nötig.`;
}

function hospitalTreatment() {
  const cost = state.illness === "severe" ? 180 : state.illness === "sick" ? 65 : 30;
  if (!pay(cost)) return addFeed(`Für die Behandlung brauchst du ${euro.format(cost)}.`);
  state.health = 100;
  state.illness = "healthy";
  addFeed(`Krankenhausbehandlung abgeschlossen. Gesundheit wieder 100%. Kosten: ${euro.format(cost)}.`);
  save();
  render();
}

let basePanelsInitialized = false;

function setTextIfChanged(node, value) {
  if (!node) return;
  const next = String(value ?? "");
  if (node.textContent !== next) node.textContent = next;
}

function setHtmlIfChanged(node, html) {
  if (!node) return;
  if (node.__lifeBuilderHtml === html && node.innerHTML === html) return;
  node.innerHTML = html;
  node.__lifeBuilderHtml = html;
}

function setValueIfChanged(node, value) {
  if (!node) return;
  const next = Number(value ?? 0);
  if (Number(node.value) !== next) node.value = next;
}

function renderActiveTabContent(tabName = activeTabId() || "overview") {
  if (!state) return;
  switch (tabName) {
    case "work":
      renderJobs();
      break;
    case "bank":
      renderBank();
      break;
    case "shop":
      renderShop();
      break;
    case "world":
      renderMap();
      break;
    case "games":
      renderGames();
      break;
    case "casino":
      renderCasino();
      break;
    case "realestate":
      renderRealEstate();
      break;
    case "character":
      renderCharacter();
      break;
    case "barber":
      renderBarber();
      break;
    case "tattoo":
      renderTattoo();
      break;
    case "overview":
    default:
      renderDailyActions();
      renderFeed();
      break;
  }
}

function render() {
  const preservePagePosition = window.matchMedia?.("(max-width: 600px)")?.matches;
  const savedPageScrollX = preservePagePosition ? window.scrollX : 0;
  const savedPageScrollY = preservePagePosition ? window.scrollY : 0;
  const restorePagePosition = () => {
    if (!preservePagePosition) return;
    requestAnimationFrame(() => window.scrollTo(savedPageScrollX, savedPageScrollY));
  };
  applyRealtimeNeedsHealth();
  completeQuickHomeTravelIfReady();
  completeWorldTravelIfReady();
  completeLocalTravelIfReady();
  if (isLoadingGame) {
    els.setup.classList.remove("hidden");
    els.game.classList.add("hidden");
    setSetupView("loading");
    restorePagePosition();
    return;
  }
  if (!state) {
    els.setup.classList.remove("hidden");
    els.game.classList.add("hidden");
    setSetupView("start");
    restorePagePosition();
    return;
  }

  if (els.setup.classList.contains("settings-overlay")) {
    els.setup.classList.remove("hidden");
  } else {
    els.setup.classList.add("hidden");
  }
  initSharedSystemAccountsSync();
  ensurePhoneBackgroundRealtime().catch((error) => console.warn("Phone background realtime unavailable", error));
  els.game.classList.remove("hidden");
  checkAnnualBirthdayGift();
  updateHeaderStatusUi(true);
  setTextIfChanged(els.bankName, state.bankName);
  setTextIfChanged(els.accountIban, fakeIban());
  setTextIfChanged(els.creditInfo, `Kreditrahmen: ${euro.format(creditLimit())}`);
  if (!basePanelsInitialized) {
    renderCharacter();
    basePanelsInitialized = true;
  }
  const renderedTab = activeTabId() || "overview";
  renderActiveTabContent(renderedTab);
  lastLiveTabName = renderedTab;
  lastLiveTabRefreshAt = Date.now();
  document.dispatchEvent(new CustomEvent("lifebuilder:rendered", { detail: { tab: renderedTab } }));
  if (!state.introDone && !els.dialog.open && !els.setup.classList.contains("settings-overlay")) {
    setTimeout(() => showIntroStep(0), 80);
  } else if (state.introDone && beginnerPhoneTutorialActive()) {
    scheduleBeginnerPhoneTutorial(120);
  }
  restorePagePosition();
}

let lastPortraitHeaderHtml = "";
let lastDashboardVisibility = null;
let lastDashboardLevel = null;

function compactDashboardMoney(value) {
  const amount = Number(value || 0);
  const absolute = Math.abs(amount);
  if (absolute < 10000) return euro.format(amount);
  const units = [
    [1_000_000_000_000, "Bio."],
    [1_000_000_000, "Mrd."],
    [1_000_000, "M"],
    [1_000, "K"]
  ];
  const [unit, suffix] = units.find(([threshold]) => absolute >= threshold) || [1, ""];
  const scaled = amount / unit;
  const digits = Math.abs(scaled) >= 100 ? 0 : Math.abs(scaled) >= 10 ? 1 : 1;
  return `${scaled.toLocaleString("de-DE", { minimumFractionDigits: 0, maximumFractionDigits: digits })}${suffix} €`;
}

function bankAccountIsAvailable(target = state) {
  return !!target && target.onlineBanking === true && target.bankAvailable !== false;
}

function bankAccountDashboardText(target = state) {
  return bankAccountIsAvailable(target) ? compactDashboardMoney(target.bank) : "Nicht verfügbar";
}

function updateHeaderStatusUi(force = false) {
  if (!state) return;
  setTextIfChanged(els.playerName, `${state.firstName} ${state.lastName}`);
  setTextIfChanged(els.dayLabel, `Tag ${state.day}`);
  const portrait = document.querySelector(".portrait");
  const portraitHtml = portraitHeaderHtml();
  if (portrait && (force || portraitHtml !== lastPortraitHeaderHtml)) {
    setHtmlIfChanged(portrait, portraitHtml);
    lastPortraitHeaderHtml = portraitHtml;
    els.ageBadge = document.getElementById("ageBadge");
  }
  setTextIfChanged(els.cash, compactDashboardMoney(state.cash));
  setTextIfChanged(els.bank, bankAccountDashboardText(state));
  if (els.cash) els.cash.title = `Bargeld: ${euro.format(state.cash)}`;
  if (els.bank) els.bank.title = bankAccountIsAvailable(state)
    ? `Kontostand: ${euro.format(state.bank)}`
    : `Konto noch nicht eröffnet · Smartphone kaufen und Online-Banking bei ${state.bankName || "deiner Bank"} beantragen`;
  setTextIfChanged(els.debt, euro.format(state.debt));
  setTextIfChanged(els.job, state.job);
  setValueIfChanged(els.hunger, state.hunger);
  setValueIfChanged(els.thirst, state.thirst);
  setValueIfChanged(els.energy, state.energy);
  setValueIfChanged(els.mood, state.mood);
  updatePhoneShortcut();
  if (force || lastDashboardLevel !== state.level) {
    updateDashboardLevelLocks();
    lastDashboardLevel = state.level;
  }
  const dashboardVisible = isDailyDashboardAvailable();
  // Günstige, aber wichtige Selbstheilung: Die Tab-Sichtbarkeit wird bei jedem
  // Renderdurchlauf synchronisiert. So bleiben Heute & Arbeit auch nach Dialogen,
  // Reisen, Hotelwechseln oder mobilen DOM-Neuaufbauten garantiert korrekt.
  updateHomeDashboardVisibility();
  lastDashboardVisibility = dashboardVisible;
}

