function inventoryInlineActionsHtml(entry) {
  if (!entry) return "";
  const actions = [];
  if (entry.canUse) {
    actions.push(`<button class="primary-button" type="button" draggable="false" data-inventory-inline-use="${escapeHtml(entry.id)}">${entry.useLabel || "Benutzen"}</button>`);
  }
  if (entry.kind === "vehicle") {
    actions.push(`<button class="mini-button" type="button" draggable="false" data-inventory-inline-vehicle-sell="${escapeHtml(entry.name)}">Sofort verkaufen</button>`);
    actions.push(`<button class="mini-button" type="button" draggable="false" data-inventory-inline-vehicle-list="${escapeHtml(entry.name)}">Anbieten</button>`);
  } else if (entry.canSell) {
    actions.push(`<button class="mini-button danger" type="button" draggable="false" data-inventory-inline-sell="${escapeHtml(entry.id)}" title="${euro.format(inventorySellValue(entry.name))}">Verkaufen</button>`);
  }
  if (!actions.length) actions.push(`<span class="inventory-slot-only">Nur Besitz</span>`);
  return `<div class="inventory-slot-actions" data-inventory-slot-actions hidden>${actions.join("")}</div>`;
}

function inventoryDetailHtml(entry) {
  if (!entry) return `<div class="inventory-selected-empty"><span>📦</span><b>Kein Gegenstand ausgewählt</b><small>Tippe einen Inventarplatz an. Auf dem PC kannst du per Rechtsklick verkaufen, auf dem Handy per langem Drücken sortieren.</small></div>`;
  const value = inventorySellValue(entry.name);
  const action = entry.canUse ? `<button class="primary-button" data-inventory-detail-use="${escapeHtml(entry.id)}">${entry.useLabel || "Benutzen"}</button>` : "";
  let sale = "";
  if (entry.kind === "vehicle") {
    sale = `<button class="mini-button" data-vehicle-sell="${escapeHtml(entry.name)}">Sofort ${euro.format(quickVehicleSaleValue(entry.name))}</button><button class="mini-button" data-vehicle-list="${escapeHtml(entry.name)}">Anbieten</button>`;
  } else if (entry.canSell) {
    sale = `<button class="mini-button danger" data-inventory-detail-sell="${escapeHtml(entry.id)}">Verkaufen ${euro.format(value)}</button>`;
  } else if (entry.protected) {
    sale = `<button class="mini-button" disabled>Dauergerät · nicht verkäuflich</button>`;
  }
  return `<div class="inventory-selected-card"><div class="inventory-selected-icon">${entry.icon}</div><h3>${escapeHtml(entry.name)}${entry.count > 1 ? ` · ${entry.count}x` : ""}</h3><p>${escapeHtml(entry.text || "")}${itemIdBadge(entry.name)}</p><div class="inventory-selected-actions">${action}${sale || `<button class="mini-button" disabled>Nur Besitz</button>`}</div></div>`;
}

function inventoryWorkbenchHtml() {
  const entries = inventoryWorkbenchEntries();
  if (inventoryUiSelected && !entries.some((entry) => entry.id === inventoryUiSelected)) inventoryUiSelected = "";
  const capacity = Math.max(inventoryCapacity(), entries.length);
  const slotLayout = inventorySlotLayout(entries, capacity);
  const activeBackpack = [...shopMarketCatalog.backpacks].reverse().find((entry) => Number(state.backpackSlots || 0) >= Number(entry.backpackSlots || 0));
  return `
    <div class="inventory-game-layout">
      <aside class="inventory-character-column">
        <div class="inventory-avatar-drop" data-inventory-dropzone tabindex="0">
          <span class="inventory-drop-label">Zum Benutzen auf den Charakter ziehen</span>
          ${avatarHtml("large")}
          <b>${escapeHtml(state.firstName || "Charakter")}</b>
          <small>${activeBackpack ? `${escapeHtml(activeBackpack.name)} · +${activeBackpack.backpackSlots} Plätze` : "Kein Rucksack · 8 Plätze"}</small>
        </div>
      </aside>
      <section class="inventory-storage-column">
        ${inventoryNeedsStatusHtml("grid")}
        <div class="inventory-toolbar-modern">
          <div><strong>Inventar ${inventoryUsed()}/${capacity}</strong><small>${entries.length} Stapel · freie Plätze ${Math.max(0, capacity - inventoryUsed())}</small></div>
          <label><span>🔎</span><input type="search" data-inventory-search value="${escapeHtml(inventoryUiSearch)}" placeholder="Suchen: Energy, Wasser, Getränke, Medizin …" autocomplete="off" autocapitalize="none" spellcheck="false"></label>
        </div>
        <p class="inventory-sort-hint"><span>PC: frei platzieren · beim Ziehen Mausrad für Menge · Rechtsklick verkauft</span><span>Handy: antippen für Aktionen · lange drücken, frei ziehen oder auf Charakter ablegen</span></p>
        <div class="inventory-slot-grid" data-inventory-slot-grid>
          ${slotLayout.map((entry, index) => entry
            ? `<div class="inventory-slot occupied" role="button" tabindex="0" draggable="true" data-inventory-entry="${escapeHtml(entry.id)}" data-inventory-position="${index}" data-inventory-search-text="${escapeHtml(inventoryEntrySearchText(entry))}" title="${escapeHtml(entry.name)}"><span>${entry.icon}</span><b>${escapeHtml(entry.name)}</b>${entry.count > 1 ? `<em>${entry.count}x</em>` : ""}${itemIdBadge(entry.name)}${inventoryInlineActionsHtml(entry)}</div>`
            : `<div class="inventory-slot empty" data-inventory-position="${index}" title="Freier Inventarplatz"><i>${index + 1}</i></div>`).join("")}
        </div>
        <p class="inventory-search-empty" data-inventory-search-empty hidden>Keine passenden Gegenstände gefunden.</p>
      </section>
    </div>`;
}

