function achievementMetric(entry) {
  let current = 0;
  let target = 1;
  let unit = "";
  const finderMatches = Number(state.finder?.totalMatches || state.finder?.matches?.length || 0);
  const specialCount = Object.keys(state.specialCollection?.discovered || {}).filter((id) => state.specialCollection.discovered[id]).length;
  switch (entry?.id) {
    case "mobile": current = vehicleCount(); break;
    case "collector": current = vehicleCount(); target = 2; break;
    case "property": current = (state.properties || []).length; break;
    case "landlord": current = Object.keys(state.rentedProperties || {}).length; break;
    case "wardrobe": current = (state.wardrobe || []).length; target = 5; break;
    case "tattoo": current = (state.appearance?.tattoos || []).length; break;
    case "casino-wallet": current = walletCents() / 100; target = 100; unit = "€"; break;
    case "casino-tier": current = Number(state.casinoLevel || 0); break;
    case "casino-highroller": current = Number(state.casinoLevel || 0); target = 2; break;
    case "casino-win-1k": current = walletCents() / 100; target = 1000; unit = "€"; break;
    case "war-win": current = Number(state.war?.wins || 0); break;
    case "kingdom-win": current = Number(state.kingdom?.wins || 0); break;
    case "racer-win": current = Number(state.racer?.wins || 0); break;
    case "snake-record": current = Number(state.snake?.record || 0); target = 30; unit = "Punkte"; break;
    case "racer-master": current = Number(state.racer?.wins || 0); target = 3; break;
    case "iconman-1k": current = Number(state.iconman?.record || 0); target = 1000; unit = "Punkte"; break;
    case "business-level": current = Number(state.businessLevel || 1); target = 3; break;
    case "five-shifts": current = Math.max(Number(state.totalWorkDays || 0), Number(state.workDaysThisMonth || 0)); target = 5; unit = "Tage"; break;
    case "salary-day": current = Number(state.salaryPayouts || 0); break;
    case "portfolio": current = (state.portfolio || []).length; break;
    case "portfolio-5": current = (state.portfolio || []).length; target = 5; break;
    case "level-10": current = Number(state.level || 0); target = 10; unit = "Level"; break;
    case "level-25": current = Number(state.level || 0); target = 25; unit = "Level"; break;
    case "backpack": current = Number(state.backpackSlots || 0); break;
    case "inventory-full": current = inventoryUsed(); target = 8; unit = "Plätze"; break;
    case "finder-first-like": current = Math.max((state.finder?.liked || []).length, (state.finder?.favorites || []).length); break;
    case "finder-first-match": current = finderMatches; break;
    case "finder-four-matches": current = finderMatches; target = 4; unit = "Matches"; break;
    case "finder-partner-care": current = finderRelationshipActionCount(); break;
    case "finder-partner-care-5": current = finderRelationshipActionCount(); target = 5; unit = "Aktivitäten"; break;
    case "bank-10k": current = Number(state.bank || 0) + Number(state.cash || 0); target = 10000; unit = "€"; break;
    case "bank-100k": current = Number(state.bank || 0) + Number(state.cash || 0); target = 100000; unit = "€"; break;
    case "bank-1m": current = Number(state.bank || 0) + Number(state.cash || 0); target = 1000000; unit = "€"; break;
    case "health-full": current = Number(state.health || 0); target = 100; unit = "%"; break;
    case "phone-note": current = phoneNotesArray().length; break;
    case "garage-cap-10": current = vehicleCapacity(); target = 10; unit = "Plätze"; break;
    case "snake-easy-20": current = Number(state.snake?.records?.easy || state.snake?.record || 0); target = 20; unit = "Punkte"; break;
    case "snake-hard-10": current = Number(state.snake?.records?.hard || 0); target = 10; unit = "Punkte"; break;
    case "icon-level-5": current = Number(state.iconman?.level || 1); target = 5; unit = "Level"; break;
    case "black-market-record": current = (state.criminalRecord || []).length; break;
    case "pet-first": current = (state.pets || []).length; break;
    case "pet-care-25": current = Number(state.petStats?.careActions || 0); target = 25; unit = "Pflegeaktionen"; break;
    case "pet-level-10": current = Math.max(0, ...(state.pets || []).map((pet) => Number(pet.level || 1))); target = 10; unit = "Level"; break;
    case "auction-buy": current = Number(state.auctionHouse?.stats?.bought || 0); break;
    case "auction-sell": current = Number(state.auctionHouse?.stats?.sold || 0); break;
    case "special-10": current = specialCount; target = 10; unit = "Items"; break;
    case "special-100": current = specialCount; target = 100; unit = "Items"; break;
    case "special-500": current = specialCount; target = 500; unit = "Items"; break;
    case "special-1000": current = specialCount; target = 1000; unit = "Items"; break;
    default: {
      try { current = entry?.done?.() ? 1 : 0; } catch { current = 0; }
    }
  }
  current = Math.max(0, Number(current || 0));
  target = Math.max(1, Number(target || 1));
  const remaining = Math.max(0, target - current);
  const percent = Math.max(0, Math.min(100, Math.round(current / target * 100)));
  const numberText = (value) => Number.isInteger(value) ? value.toLocaleString("de-DE") : value.toLocaleString("de-DE", { maximumFractionDigits: 2 });
  const valueText = unit === "€"
    ? `${euro.format(current)} / ${euro.format(target)}`
    : `${numberText(current)} / ${numberText(target)}${unit ? ` ${unit}` : ""}`;
  const remainingText = remaining <= 0
    ? "Ziel erreicht"
    : unit === "€"
      ? `Noch ${euro.format(remaining)} erforderlich`
      : `Noch ${numberText(remaining)}${unit ? ` ${unit}` : ""} erforderlich`;
  return { current, target, percent, valueText, remainingText };
}

function achievementsHtml() {
  const achievements = achievementDefinitions();
  state.claimedAchievements ||= [];
  const ordered = orderedAchievementEntries(achievements);
  const claimedCount = ordered.filter((item) => item.claimed).length;
  const completedCount = ordered.filter((item) => item.claimed || item.ready).length;
  const completion = achievements.length ? Math.round(completedCount / achievements.length * 100) : 0;
  return `
    <section class="achievement-dashboard-v18">
      <div class="profile-info-card achievement">
        <div><small>ERFOLGSFORTSCHRITT</small><strong>${completedCount} von ${achievements.length} erfüllt</strong><b>${completion}%</b></div>
        <div class="profile-info-bar achievement"><i style="width:${completion}%"></i></div>
        <p>${claimedCount} Belohnungen abgeholt · ${Math.max(0, completedCount - claimedCount)} bereit</p>
      </div>
      <button class="achievement-info-button-v18" type="button" data-achievement-info aria-label="Erfolgsinformationen öffnen" title="Fortschritt und fehlende Ziele anzeigen">i</button>
    </section>
    <div class="achievement-list-clean">${ordered.map(({ entry, index, ready, claimed }) => {
    const status = claimed ? "claimed" : ready ? "ready" : "open";
    const label = claimed ? "Abgeholt" : ready ? "+1 Punkt abholen" : "Offen";
    const progress = achievementMetric(entry);
    return `
      <article class="achievement-card-clean ${status}">
        <div class="achievement-copy-clean">
          <h3>${claimed ? "✓ " : ready ? "! " : ""}${escapeHtml(entry.name)}</h3>
          <p>${escapeHtml(entry.text)} <strong>Belohnung: 1 Skillpunkt.</strong></p>
          <div class="achievement-progress-clean"><span><b>Fortschritt</b><em>${escapeHtml(progress.valueText)}</em></span><i><u style="width:${progress.percent}%"></u></i><small>${escapeHtml(progress.remainingText)}</small></div>
        </div>
        <button type="button" data-kind="achievement" data-index="${index}" ${!ready ? "disabled" : ""}>${label}</button>
      </article>`;
  }).join("")}</div>`;
}

function openAchievementInfoDialog() {
  const achievements = achievementDefinitions();
  const ordered = orderedAchievementEntries(achievements);
  const claimedCount = ordered.filter((item) => item.claimed).length;
  const readyCount = ordered.filter((item) => item.ready).length;
  const completedCount = claimedCount + readyCount;
  const nextGoals = ordered.filter((item) => !item.claimed && !item.ready).slice(0, 8);
  clearDialogDynamic();
  els.dialogTitle.textContent = "Erfolge · Fortschritt";
  els.dialogText.textContent = "Hier siehst du, was bereits erledigt ist und wie viel bis zu den nächsten Erfolgen fehlt.";
  const panel = document.createElement("div");
  panel.className = "profile-info-scroll achievement-info-panel-v18";
  panel.innerHTML = `
    <section class="profile-info-card achievement"><div><small>GESAMT</small><strong>${completedCount} von ${achievements.length} erfüllt</strong><b>${readyCount} bereit</b></div><div class="profile-info-bar achievement"><i style="width:${achievements.length ? Math.round(completedCount / achievements.length * 100) : 0}%"></i></div></section>
    <section class="profile-tip-list"><h3>Nächste Ziele</h3>${nextGoals.map(({ entry }) => {
      const progress = achievementMetric(entry);
      return `<article><span>${progress.percent}%</span><div><b>${escapeHtml(entry.name)}</b><small>${escapeHtml(progress.valueText)} · ${escapeHtml(progress.remainingText)}</small></div></article>`;
    }).join("") || `<article><span>✓</span><div><b>Alles geschafft</b><small>Aktuell sind keine offenen Erfolge vorhanden.</small></div></article>`}</section>
    <p class="device-hint">Gold markierte Erfolge sind erfüllt. Hole sie ab, um jeweils einen Skillpunkt zu erhalten.</p>`;
  setDialogBack(() => openCharacterHub("achievements"), "Erfolge");
  els.dialog.append(panel);
  if (!els.dialog.open) els.dialog.showModal();
}

const THE_REAL_GALAXY_SKIN = "The Real Galaxy Skin";

function isJkExclusiveSkinName(name) {
  const raw = String(name || "").trim();
  return raw.toLowerCase() === THE_REAL_GALAXY_SKIN.toLowerCase()
    || /^JK Exclusive (Premium|Legend|Universe|Galaxy) Skin #\d+$/i.test(raw);
}

function jkExclusiveSkinInfo(name) {
  const raw = String(name || "").trim();
  if (raw.toLowerCase() === THE_REAL_GALAXY_SKIN.toLowerCase()) {
    return { name: THE_REAL_GALAXY_SKIN, tier: "realgalaxy", label: "The Real Galaxy", number: 7777, sellValue: 15000000, special: true };
  }
  const match = raw.match(/^JK Exclusive (Premium|Legend|Universe|Galaxy) Skin #(\d+)$/i);
  if (!match) return null;
  const tier = match[1].toLowerCase();
  const number = Math.max(1, Math.floor(Number(match[2]) || 1));
  const labels = { premium: "Premium", legend: "Legendär", universe: "Universe", galaxy: "Galaxy" };
  const sellValues = { premium: 125000, legend: 300000, universe: 900000, galaxy: 2500000 };
  return { name: raw, tier, label: labels[tier] || match[1], number, sellValue: sellValues[tier] || 125000 };
}

