function hotelRoomOptions(offer) {
  const cheap = ["zero", "one"].includes(offer.id);
  return [
    { id: "standard", name: "Standardzimmer", multiplier: 1, energy: 0, health: 0, hunger: 0, thirst: 0, text: cheap ? "Billigste Variante. Schlaf ja, Komfort nein." : "Normale Buchung ohne Extras." },
    { id: "breakfast", name: "Mit Frühstück", multiplier: 1.18, energy: 4, health: 1, hunger: 18, thirst: 8, text: "Frühstück und Getränke am Morgen." },
    { id: "quiet", name: "Ruhiges Zimmer", multiplier: 1.35, energy: 10, health: 3, hunger: 3, thirst: 3, text: "Bessere Lage, weniger Lärm, stärkere Erholung." },
    { id: "service", name: "Service-Paket", multiplier: 1.75, energy: 16, health: 6, hunger: 10, thirst: 10, text: "Sauberes Zimmer, Zimmerservice und bessere Betreuung." }
  ];
}

function openHotelRoomOptions(offer) {
  if (!offer) return;
  clearDialogDynamic();
  els.dialogTitle.textContent = offer.name;
  els.dialogText.textContent = "Wähle, was für ein Zimmer du möchtest. Billige Zimmer können Hunger, Durst oder Gesundheit verschlechtern.";
  const list = document.createElement("div");
  list.className = "market-list";
  const options = hotelRoomOptions(offer);
  list.innerHTML = options.map((option, index) => {
    const price = Math.round(offer.price * option.multiplier);
    const health = (offer.health || 0) + option.health;
    const hunger = (offer.hunger || 0) + option.hunger;
    const thirst = (offer.thirst || 0) + option.thirst;
    const energy = Math.min(100, (offer.energy || 0) + option.energy);
    return card(
      option.name,
      `${option.text} Energie bis ${energy} · Leben ${health >= 0 ? "+" : ""}${health} · Hunger ${hunger >= 0 ? "+" : ""}${hunger} · Durst ${thirst >= 0 ? "+" : ""}${thirst}. Preis pro Nacht: ${euro.format(price)}.`,
      "Buchen",
      index,
      !canAfford(price),
      "hotel-room"
    );
  }).join("");
  setDialogBack(openHotelOffersDialog);
  els.dialog.append(list);
  list.querySelectorAll('button[data-kind="hotel-room"]').forEach((button) => {
    button.addEventListener("click", () => bookHotelNight(offer, options[Number(button.dataset.index)]));
  });
  if (!els.dialog.open) els.dialog.showModal();
}

function bookHotelNight(offer, option = hotelRoomOptions(offer)[0]) {
  if (!offer) return;
  if (state.location !== "hotel") return openSleepRouteChoice();
  const price = Math.round(offer.price * (option.multiplier || 1));
  if (!pay(price, false, { target: "treasury", taxRate: 0.19 })) return addFeed(`Für ${offer.name} brauchst du ${euro.format(price)}.`);
  state.energy = clamp(Math.max(state.energy || 0, Math.min(100, (offer.energy || 0) + (option.energy || 0))));
  state.health = clamp((state.health ?? 100) + (offer.health || 0) + (option.health || 0));
  state.hunger = clamp((state.hunger ?? 100) + (offer.hunger || 0) + (option.hunger || 0));
  state.thirst = clamp((state.thirst ?? 100) + (offer.thirst || 0) + (option.thirst || 0));
  state.hotelStay = {
    active: true,
    city: state.worldLocation || state.homeCity,
    hotelId: offer.id,
    hotelName: offer.name,
    roomId: option.id,
    roomName: option.name,
    bookedAt: Date.now(),
    paidPrice: price
  };
  state.phoneBattery = 100;
  const hotelMoodBonus = Math.max(2, Math.min(14, 2 + hotelOffers.findIndex((entry) => entry.id === offer.id) * 2 + Math.round(((option.multiplier || 1) - 1) * 5)));
  improveMood(hotelMoodBonus, `${offer.name} und ${option.name} waren erholsam`, { feed: false });
  state.homeDashboardActive = false;
  addFeed(`${offer.name} · ${option.name} gebucht: ${euro.format(price)} bezahlt. Handy auf 100 % geladen, Stimmung +${hotelMoodBonus}. Heute und Arbeit sind im Hotel jetzt verfügbar.`);
  els.dialog.close();
  sleepAndAdvanceDay(`Du hast im ${offer.name} (${option.name}) geschlafen.`);
  switchMainTab("overview");
  updateHomeDashboardVisibility();
}

