function buyLocalItem(item) {
  state.items ||= [];
  state.consumables ||= {};
  state.cash = Number.isFinite(Number(state.cash)) ? Number(state.cash) : 0;
  state.bank = Number.isFinite(Number(state.bank)) ? Number(state.bank) : 0;
  const progression = shopProgressionStatus(item, item.localMarketKey || "");
  if (progression.locked) return showPurchaseFailure(progression.text || `${item.name} ist gerade gesperrt.`);
  if ((item.effect || isStorableShopItem(item)) && inventoryUsed() >= inventoryCapacity()) {
    return showPurchaseFailure(`Inventar voll: ${inventoryUsed()}/${inventoryCapacity()}. Kaufe zuerst einen größeren Rucksack oder verkaufe einen Gegenstand.`);
  }
  const taxRate = item.effect && /snack|chips|schoko|sandwich|croissant|salat|futter|essen|einkauf/i.test(`${item.name} ${item.text || ""}`) ? 0.07 : 0.19;
  if (!pay(item.price, false, { taxRate })) return showPurchaseFailure(`Für ${item.name} brauchst du ${euro.format(item.price)}. Verfügbar einschließlich Dispo: ${euro.format(availablePlayerFunds(state))}.`);
  if (item.effect) addConsumable(item, 1);
  if (item.item) state.items.push(item.item);
  addXp(3, "Vor-Ort-Kauf");
  addFeed(`${item.name} gekauft.`, { purchase: { name: item.name, total: item.price, method: "auto" } });
  save();
  render();
}

function bankCreditTierRowsHtml() {
  const tiers = [
    ["0–17 %", 2000],
    ["18–21 %", 5000],
    ["22–30 %", 20000],
    ["31–44 %", 50000],
    ["45–59 %", 150000],
    ["60–79 %", 300000],
    ["80–100 %", 500000]
  ];
  return tiers.map(([rating, limit]) => `<div class="credit-tier ${creditLimit() === limit ? "active" : ""}"><span>${rating}</span><strong>bis ${euro.format(limit)}</strong></div>`).join("");
}

function openBankBranchDialog() {
  clearDialogDynamic();
  const available = branchCreditAvailable();
  const free = freeCreditLimit();
  els.dialogTitle.textContent = `${state.bankName || "Bank"} · Filiale`;
  els.dialogText.textContent = "Der mögliche Kredit ist bonitätsabhängig. Eine bessere Bonität erhöht den Gesamtrahmen und senkt den Zinssatz. Sinkt deine Bonität bei offenen Schulden in eine schlechtere Stufe, erhöht die Bank den Zinssatz und bucht den Unterschied als Risikozuschlag auf die Restschuld.";
  const panel = document.createElement("div");
  panel.className = "bank-branch-panel";
  panel.innerHTML = `
    <div class="bank-branch-summary">
      <article><span>Bonität</span><strong>${Math.round(state.credit || 0)}%</strong><small>${creditRatingLabel()}</small></article>
      <article><span>Gesamtrahmen</span><strong>${euro.format(creditLimit())}</strong><small>laut aktueller Bonität</small></article>
      <article><span>Noch frei</span><strong>${euro.format(free)}</strong><small>abzüglich Schulden</small></article>
      <article><span>Sofort in Filiale</span><strong>${euro.format(available)}</strong><small>ohne Termin, maximal 8.000 €</small></article>
      <article><span>Zinssatz</span><strong>${loanInterestRate()}%</strong><small>auf den aufgenommenen Betrag</small></article>
    </div>
    <section class="credit-tier-box">
      <h3>Ungefähre Kreditrahmen nach Bonität</h3>
      ${bankCreditTierRowsHtml()}
    </section>
    <label class="field-label">Gewünschter Filialkredit
      <input type="number" min="1" max="${Math.max(0, available)}" step="100" value="${Math.max(0, available)}" data-branch-loan-amount ${available <= 0 ? "disabled" : ""}>
    </label>
    <button class="primary-button" data-take-branch-loan ${available <= 0 ? "disabled" : ""}>Kredit anfragen</button>
    ${free > 8000 ? `<p class="device-hint">Für mehr als ${euro.format(8000)} musst du über die Bankansicht einen Termin buchen. Dein gesamter freier Rahmen liegt bei ${euro.format(free)}.</p>` : ""}
  `;
  setDialogBack(() => {
    clearDialogDynamic();
    els.dialog.close();
  }, "Bankfiliale");
  els.dialog.append(panel);
  panel.querySelector("[data-take-branch-loan]")?.addEventListener("click", () => {
    const amount = Math.round(Number(panel.querySelector("[data-branch-loan-amount]")?.value || 0));
    if (requestBranchLoan(amount)) openBankBranchDialog();
  });
  if (!els.dialog.open) els.dialog.showModal();
}

function requestBranchLoan(requestedAmount = null) {
  const available = branchCreditAvailable();
  const amount = requestedAmount == null
    ? Math.round(Number(prompt(`Filial-Kredit bis ${euro.format(available)}:`, String(available))))
    : Math.round(Number(requestedAmount));
  if (!amount || amount <= 0) return false;
  if (amount > 8000) {
    addFeed("In der Bankfiliale gehen ohne Termin maximal 8.000 €.");
    return false;
  }
  if (amount > available) {
    addFeed(`Mit deiner aktuellen Bonität sind in der Filiale ungefähr ${euro.format(available)} verfügbar.`);
    return false;
  }
  grantLoan(amount);
  return true;
}

