function finsterAllPosts() {
  // Nur echte Online-Beiträge. Keine automatisch erzeugten KI-/Bot-Posts mehr im Feed.
  return [...finsterPostsCache].sort((a, b) => Number(b.createdAtMs || 0) - Number(a.createdAtMs || 0));
}

function finsterProfileByUid(uid) {
  if (!uid) return null;
  return finsterUsersCache.find((entry) => entry.uid === uid) || null;
}

function finsterTimeText(timestamp) {
  const diff = Math.max(0, Date.now() - Number(timestamp || Date.now()));
  if (diff < 60000) return "gerade eben";
  if (diff < hour) return `vor ${Math.floor(diff / minute)} Min.`;
  if (diff < 24 * hour) return `vor ${Math.floor(diff / hour)} Std.`;
  return `vor ${Math.floor(diff / (24 * hour))} Tagen`;
}

function finsterAvatarHtml(profile, size = "normal") {
  const name = profile?.displayName || profile?.handle || "F";
  const initials = name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase();
  const hue = profile?.avatarHue ?? Math.abs(stringSeed(profile?.uid || name)) % 360;
  return `<span class="finster-avatar ${size}" style="--avatar-hue:${hue}">${escapeHtml(initials)}</span>`;
}


const FINSTER_IMAGE_PLACEHOLDER = `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="900" viewBox="0 0 900 900"><rect width="900" height="900" fill="#101a16"/><circle cx="450" cy="390" r="112" fill="#294438"/><path d="M170 710l190-210 128 132 105-105 137 183z" fill="#497664"/><text x="450" y="805" text-anchor="middle" fill="#9ec7b4" font-family="Arial,sans-serif" font-size="44">Bild wird geladen</text></svg>`)}`;

function finsterImageHtml(post, alt = "Finster.KL-Beitrag") {
  const imageUrl = String(post?.imageUrl || "").trim();
  const storagePath = String(post?.storagePath || "").trim();
  return `<img src="${escapeHtml(imageUrl || FINSTER_IMAGE_PLACEHOLDER)}" data-finster-image-id="${escapeHtml(post?.id || "")}" data-finster-storage-path="${escapeHtml(storagePath)}" loading="eager" decoding="async" alt="${escapeHtml(alt)}">`;
}

async function recoverFinsterImage(img) {
  if (!img || img.dataset.finsterRecovering === "1") return;
  const attempts = Number(img.dataset.finsterAttempts || 0);
  if (attempts >= 2) {
    img.dataset.finsterBroken = "1";
    img.src = FINSTER_IMAGE_PLACEHOLDER;
    return;
  }
  img.dataset.finsterAttempts = String(attempts + 1);
  img.dataset.finsterRecovering = "1";
  try {
    const storagePath = String(img.dataset.finsterStoragePath || "").trim();
    if (storagePath) {
      const fb = await loadFirebasePhoneRuntime();
      const freshUrl = await fb.getDownloadURL(fb.ref(fb.storage, storagePath));
      if (freshUrl) {
        img.src = freshUrl;
        img.dataset.finsterRecovering = "0";
        img.dataset.finsterBroken = "0";
        return;
      }
    }
    const current = String(img.currentSrc || img.src || "");
    if (current && !current.startsWith("data:")) {
      const retryUrl = new URL(current, window.location.href);
      retryUrl.searchParams.set("lb_retry", String(Date.now()));
      img.src = retryUrl.toString();
      img.dataset.finsterRecovering = "0";
      return;
    }
    throw new Error("Kein Bildpfad vorhanden");
  } catch (error) {
    console.warn("Finster-Bild konnte nicht wiederhergestellt werden", error);
    img.dataset.finsterRecovering = "0";
    if (Number(img.dataset.finsterAttempts || 0) >= 2) {
      img.dataset.finsterBroken = "1";
      img.src = FINSTER_IMAGE_PLACEHOLDER;
    }
  }
}

function bindFinsterImages(root) {
  root?.querySelectorAll?.("img[data-finster-image-id]").forEach((img) => {
    if (img.dataset.finsterBound !== "1") {
      img.dataset.finsterBound = "1";
      img.addEventListener("error", () => recoverFinsterImage(img));
      img.addEventListener("load", () => {
        if (img.naturalWidth > 1) {
          img.dataset.finsterBroken = "0";
          img.dataset.finsterRecovering = "0";
        }
      });
    }
    if (img.complete && img.naturalWidth <= 1) recoverFinsterImage(img);
  });
}

function scheduleFinsterReconnect(delay = finsterReconnectDelay) {
  clearTimeout(finsterRetryTimer);
  if (navigator.onLine === false) delay = Math.max(delay, 8000);
  finsterRetryTimer = setTimeout(() => {
    finsterRetryTimer = null;
    if (document.hidden || navigator.onLine === false) {
      scheduleFinsterReconnect(Math.min(30000, Math.max(8000, delay * 1.5)));
      return;
    }
    window.LifeBuilderFirebaseCore?.scheduleReconnect?.(250);
    ensureFinsterRealtime().catch((error) => console.warn("Finster reconnect", error));
  }, Math.max(1000, Number(delay || 3500)));
  finsterReconnectDelay = Math.min(30000, Math.round(Math.max(3500, Number(delay || 3500)) * 1.65));
}

async function ensureFinsterRealtime() {
  if (finsterRuntimeStarting) return finsterRuntimeStarting;
  finsterRealtimeState = finsterPostsUnsubscribe || finsterUsersUnsubscribe || finsterMessagesUnsubscribe ? "ready" : "loading";
  finsterRuntimeStarting = (async () => {
    const fb = await onlineFirebaseTimeout(loadFirebasePhoneRuntime(), 9000, "Finster.KL-Anmeldung");
    const uid = fb.auth.currentUser?.uid;
    if (!uid) throw new Error("Online-Anmeldung fehlt.");
    if (finsterRuntimeUid && finsterRuntimeUid !== uid) stopFinsterRealtime();
    finsterRuntimeUid = uid;

    const listenerFailed = (kind, error) => {
      const message = String(error?.message || error || "Unbekannter Online-Fehler");
      finsterRealtimeState = "error";
      finsterRealtimeError = `${kind} konnten nicht geladen werden: ${message}`;
      console.warn(`Finster ${kind}`, error);
      if (kind === "Beiträge") {
        try { finsterPostsUnsubscribe?.(); } catch {}
        finsterPostsUnsubscribe = null;
      } else if (kind === "Profile") {
        try { finsterUsersUnsubscribe?.(); } catch {}
        finsterUsersUnsubscribe = null;
      } else {
        try { finsterMessagesUnsubscribe?.(); } catch {}
        finsterMessagesUnsubscribe = null;
      }
      refreshFinsterIfVisible();
      scheduleFinsterReconnect(/permission|berechtigung/i.test(message) ? 12000 : finsterReconnectDelay);
    };

    if (!finsterPostsUnsubscribe) {
      const queryPosts = fb.query(fb.collection(fb.db, "finsterPosts"), fb.orderBy("createdAtMs", "desc"), fb.limit(40));
      finsterPostsUnsubscribe = fb.onSnapshot(queryPosts, (snapshot) => {
        if (fb.auth.currentUser?.uid !== uid) return;
        const next = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data(), ai: false }));
        const signature = next.map((entry) => `${entry.id}:${entry.createdAtMs || 0}:${entry.likeCount || 0}:${entry.commentCount || 0}:${entry.imageUrl || ""}`).join("|");
        if (signature !== finsterPostsSignature) {
          finsterPostsSignature = signature;
          finsterPostsCache = next;
          refreshFinsterIfVisible();
        }
        finsterRealtimeState = "ready";
        finsterRealtimeError = "";
        finsterReconnectDelay = 3500;
      }, (error) => listenerFailed("Beiträge", error));
    }
    if (!finsterUsersUnsubscribe) {
      const queryUsers = fb.query(fb.collection(fb.db, "finsterUsers"), fb.limit(100));
      finsterUsersUnsubscribe = fb.onSnapshot(queryUsers, (snapshot) => {
        if (fb.auth.currentUser?.uid !== uid) return;
        const next = snapshot.docs.map((doc) => ({ uid: doc.id, ...doc.data(), ai: false }));
        const signature = next.map((entry) => `${entry.uid}:${entry.updatedAtMs || 0}:${entry.handle || ""}:${entry.displayName || ""}`).join("|");
        const changed = signature !== finsterUsersSignature;
        if (changed) {
          finsterUsersSignature = signature;
          finsterUsersCache = next;
        }
        const mine = next.find((entry) => entry.uid === uid);
        if (mine) {
          const finster = ensureFinsterState();
          const localChanged = !finster.accountCreated || finster.handle !== (mine.handle || finster.handle) || finster.displayName !== (mine.displayName || finster.displayName) || finster.bio !== (mine.bio || finster.bio);
          finster.accountCreated = true;
          finster.handle = mine.handle || finster.handle;
          finster.displayName = mine.displayName || finster.displayName;
          finster.bio = mine.bio || finster.bio;
          if (localChanged) window.LifeBuilderSaveControl?.applyRemote?.(() => save());
        }
        if (changed) refreshFinsterIfVisible();
        finsterRealtimeState = "ready";
        finsterRealtimeError = "";
        finsterReconnectDelay = 3500;
      }, (error) => listenerFailed("Profile", error));
    }
    if (!finsterMessagesUnsubscribe) {
      const queryMessages = fb.query(fb.collection(fb.db, "finsterMessages"), fb.where("participantUids", "array-contains", uid), fb.limit(120));
      finsterMessagesUnsubscribe = fb.onSnapshot(queryMessages, (snapshot) => {
        if (fb.auth.currentUser?.uid !== uid) return;
        const next = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })).sort((a, b) => Number(a.createdAtMs || 0) - Number(b.createdAtMs || 0));
        const signature = next.map((entry) => `${entry.id}:${entry.createdAtMs || 0}`).join("|");
        if (signature !== finsterMessagesSignature) {
          finsterMessagesSignature = signature;
          finsterMessagesCache = next;
          refreshFinsterIfVisible();
        }
        finsterRealtimeState = "ready";
        finsterRealtimeError = "";
        finsterReconnectDelay = 3500;
      }, (error) => listenerFailed("Nachrichten", error));
    }
    clearTimeout(finsterRetryTimer);
    finsterRetryTimer = null;
    return fb;
  })().catch((error) => {
    finsterRealtimeState = "error";
    finsterRealtimeError = `Finster.KL konnte nicht verbunden werden: ${error.message || error}`;
    scheduleFinsterReconnect(finsterReconnectDelay);
    throw error;
  }).finally(() => { finsterRuntimeStarting = null; });
  return finsterRuntimeStarting;
}

function stopFinsterRealtime() {
  [finsterPostsUnsubscribe, finsterUsersUnsubscribe, finsterMessagesUnsubscribe].forEach((unsubscribe) => {
    if (typeof unsubscribe === "function") {
      try { unsubscribe(); } catch {}
    }
  });
  finsterPostsUnsubscribe = null;
  finsterUsersUnsubscribe = null;
  finsterMessagesUnsubscribe = null;
  finsterRuntimeUid = "";
  finsterRuntimeStarting = null;
  finsterPostsSignature = "";
  finsterUsersSignature = "";
  finsterMessagesSignature = "";
  clearTimeout(finsterRetryTimer);
  finsterRetryTimer = null;
  clearTimeout(finsterRefreshTimer);
  finsterRefreshTimer = null;
  finsterRealtimeState = "idle";
  finsterReconnectDelay = 3500;
}

function refreshFinsterIfVisible() {
  if (finsterRefreshTimer) return;
  finsterRefreshTimer = setTimeout(() => {
    finsterRefreshTimer = null;
    if (!els.dialog?.open || !els.dialog.querySelector(".finster-app")) return;
    const item = ownedPhoneItem();
    if (!item) return;
    const active = document.activeElement;
    const draftInput = els.dialog.querySelector("[data-finster-message-input]");
    const draft = draftInput?.value || "";
    const selectionStart = draftInput?.selectionStart ?? draft.length;
    const selectionEnd = draftInput?.selectionEnd ?? draft.length;
    const shouldRestoreFocus = active === draftInput;
    const thread = els.dialog.querySelector("[data-finster-chat-thread]");
    const distanceFromBottom = thread ? Math.max(0, thread.scrollHeight - thread.scrollTop - thread.clientHeight) : 0;
    refreshDeviceApp("finster", item);
    requestAnimationFrame(() => {
      const restoredInput = els.dialog?.querySelector?.("[data-finster-message-input]");
      if (restoredInput && draft) restoredInput.value = draft;
      if (restoredInput && shouldRestoreFocus) {
        restoredInput.focus({ preventScroll: true });
        restoredInput.setSelectionRange?.(selectionStart, selectionEnd);
      }
      const restoredThread = els.dialog?.querySelector?.("[data-finster-chat-thread]");
      if (restoredThread) restoredThread.scrollTop = Math.max(0, restoredThread.scrollHeight - restoredThread.clientHeight - distanceFromBottom);
    });
  }, 140);
}

function finsterAccountCreateHtml() {
  const finster = ensureFinsterState();
  return `<div class="finster-onboarding">
    <div class="finster-brand"><span>f</span><div><h3>Finster.KL</h3><p>Teile Bilder, entdecke Beiträge und schreibe mit anderen JK.Games-Spielern.</p></div></div>
    <label>Benutzername<input data-finster-handle maxlength="24" value="${escapeHtml(finster.handle)}" placeholder="z. B. julian.kl"></label>
    <label>Anzeigename<input data-finster-display-name maxlength="40" value="${escapeHtml(finster.displayName || state.firstName || "")}" placeholder="Dein Name"></label>
    <label>Profiltext<textarea data-finster-bio maxlength="180" placeholder="Erzähl kurz etwas über dich...">${escapeHtml(finster.bio)}</textarea></label>
    <button class="primary-button" data-finster-create-account>Finster-Konto erstellen</button>
    <small>Das Konto wird mit deinem JK.Games-Spielerprofil verbunden. Benutzername und Beiträge sind für andere angemeldete Spieler sichtbar.</small>
  </div>`;
}

function finsterNavHtml(view) {
  return `<nav class="finster-nav">
    ${[["feed","⌂","Feed"],["explore","⌕","Entdecken"],["create","＋","Posten"],["messages","✉","Nachrichten"],["profile","●","Profil"]].map(([id, icon, label]) => `<button class="${view === id ? "active" : ""}" data-finster-view="${id}"><span>${icon}</span><small>${label}</small></button>`).join("")}
  </nav>`;
}

function finsterPostCardHtml(post) {
  const finster = ensureFinsterState();
  const liked = finster.likedPostIds.includes(post.id);
  const profile = finsterProfileByUid(post.ownerUid) || post;
  const localLikes = post.ai ? Number(finster.aiLikes[post.id] || 0) : 0;
  const localComments = post.ai ? (finster.aiComments[post.id] || []).length : 0;
  return `<article class="finster-post" data-finster-post-card="${post.id}">
    <header>
      <button data-finster-open-user="${post.ownerUid}">${finsterAvatarHtml(profile, "small")}</button>
      <div><strong>@${escapeHtml(post.handle || profile.handle || "finster")}</strong><small>${escapeHtml(profile.city || "JK.Games")} · ${finsterTimeText(post.createdAtMs)}</small></div>
      ${post.ownerUid === finsterCurrentUid() ? `<button class="finster-more" data-finster-delete-post="${post.id}" title="Beitrag löschen">•••</button>` : ""}
    </header>
    <button class="finster-image-button" data-finster-open-post="${post.id}">${finsterImageHtml(post, `Beitrag von ${post.displayName || post.handle || "Finster"}`)}</button>
    <div class="finster-post-actions">
      <button class="${liked ? "liked" : ""}" data-finster-like="${post.id}">${liked ? "♥" : "♡"}</button>
      <button data-finster-open-post="${post.id}">◯</button>
      <button data-finster-message-user="${post.ownerUid}" ${post.ownerUid === finsterCurrentUid() ? "disabled" : ""}>➤</button>
    </div>
    <strong class="finster-like-count">${Number(post.likeCount || 0) + localLikes} Likes</strong>
    <p><b>@${escapeHtml(post.handle || profile.handle || "finster")}</b> ${escapeHtml(censorFinsterText(post.caption || "", 1000))}</p>
    <button class="finster-comments-link" data-finster-open-post="${post.id}">${Number(post.commentCount || 0) + localComments} Kommentare ansehen</button>
  </article>`;
}

function finsterFeedHtml() {
  const posts = finsterAllPosts();
  let empty = `<div class="finster-empty"><b>Noch keine Beiträge</b><p>Erstelle den ersten Post.</p></div>`;
  if (finsterRealtimeState === "loading" || finsterRealtimeState === "idle") {
    empty = `<div class="finster-empty finster-loading"><b>Beiträge werden geladen …</b><p>Online-Verbindung wird aufgebaut.</p></div>`;
  } else if (finsterRealtimeState === "error") {
    empty = `<div class="finster-empty finster-error"><b>Online-Verbindung unterbrochen</b><p>${escapeHtml(finsterRealtimeError || "Finster.KL konnte nicht verbunden werden.")}</p><button class="mini-button gold" data-finster-reconnect>Erneut verbinden</button></div>`;
  }
  return `<section class="finster-feed">${posts.length ? posts.map(finsterPostCardHtml).join("") : empty}</section>`;
}

function finsterExploreHtml() {
  const own = finsterCurrentUid();
  const profiles = finsterUsersCache.filter((profile) => profile.uid !== own);
  return `<section class="finster-explore"><div class="finster-search"><span>⌕</span><input data-finster-search placeholder="Accounts oder Orte suchen"></div><div class="finster-user-grid" data-finster-user-grid>${profiles.map((profile) => `<article data-finster-user-card="${escapeHtml(`${profile.handle} ${profile.displayName} ${profile.city || ""}`.toLowerCase())}">${finsterAvatarHtml(profile)}<div><strong>${escapeHtml(profile.displayName)}</strong><small>@${escapeHtml(profile.handle)} · ${escapeHtml(profile.city || "JK.Games")}</small><p>${escapeHtml(profile.bio || "Finster.KL-Profil")}</p></div><button class="mini-button" data-finster-open-user="${profile.uid}">Profil</button></article>`).join("")}</div></section>`;
}

function finsterCreateHtml() {
  return `<section class="finster-create">
    <div class="finster-upload-preview" data-finster-upload-preview>${finsterUploadPreviewUrl ? `<img src="${finsterUploadPreviewUrl}" alt="Vorschau">` : `<span>▧</span><p>Wähle ein Bild bis 8 MB.</p>`}</div>
    <label class="finster-file-button">Bild auswählen<input type="file" data-finster-file accept="image/jpeg,image/png,image/webp,image/gif"></label>
    <textarea data-finster-caption maxlength="1000" placeholder="Schreibe eine Bildunterschrift..."></textarea>
    <button class="primary-button" data-finster-publish ${finsterUploadFile ? "" : "disabled"}>Beitrag veröffentlichen</button>
    <small data-finster-upload-status>JPG, PNG, WEBP oder GIF. Das Bild wird online gespeichert.</small>
  </section>`;
}

function finsterCommentsFor(postId) {
  if (postId.startsWith("ai-post-")) return ensureFinsterState().aiComments[postId] || [];
  return finsterCommentsCache.get(postId) || [];
}

function finsterPostDetailHtml(postId) {
  const post = finsterAllPosts().find((entry) => entry.id === postId);
  if (!post) return `<div class="finster-empty"><b>Beitrag nicht gefunden</b><button class="mini-button" data-finster-view="feed">Zurück zum Feed</button></div>`;
  const comments = finsterCommentsFor(postId);
  return `<section class="finster-post-detail"><button class="mini-button" data-finster-view="feed">← Feed</button>${finsterPostCardHtml(post)}<div class="finster-comment-list">${comments.length ? comments.map((comment) => `<article>${finsterAvatarHtml(comment, "tiny")}<p><b>@${escapeHtml(comment.handle || "spieler")}</b> ${escapeHtml(censorFinsterText(comment.text || "", 500))}<small>${finsterTimeText(comment.createdAtMs)}</small></p></article>`).join("") : `<p>Noch keine Kommentare.</p>`}</div><div class="finster-comment-compose"><input data-finster-comment-input maxlength="500" placeholder="Kommentar schreiben..."><button data-finster-comment-send="${postId}">Senden</button></div></section>`;
}

function finsterUserProfileHtml(uid) {
  const profile = finsterProfileByUid(uid);
  if (!profile) return `<div class="finster-empty"><b>Profil nicht gefunden</b></div>`;
  const finster = ensureFinsterState();
  const following = finster.following.includes(uid);
  const posts = finsterAllPosts().filter((post) => post.ownerUid === uid);
  return `<section class="finster-profile-view"><button class="mini-button" data-finster-view="explore">← Zurück</button><header>${finsterAvatarHtml(profile, "large")}<div><h3>${escapeHtml(profile.displayName)}</h3><strong>@${escapeHtml(profile.handle)}</strong><small>${escapeHtml(profile.city || "JK.Games")}</small></div></header><p>${escapeHtml(profile.bio || "Noch kein Profiltext.")}</p><div class="finster-profile-actions">${uid !== finsterCurrentUid() ? `<button class="mini-button ${following ? "active" : "gold"}" data-finster-follow="${uid}">${following ? "Gefolgt" : "Folgen"}</button><button class="mini-button" data-finster-message-user="${uid}">Nachricht</button>` : ""}</div><div class="finster-profile-grid">${posts.map((post) => `<button data-finster-open-post="${post.id}">${finsterImageHtml(post, "Beitrag")}</button>`).join("") || `<p>Noch keine Beiträge.</p>`}</div></section>`;
}

function finsterConversationMessages(uid) {
  const own = finsterCurrentUid();
  if (uid.startsWith("ai-finster-")) return ensureFinsterState().aiMessages[uid] || [];
  return finsterMessagesCache.filter((message) => message.participantUids?.includes(own) && message.participantUids?.includes(uid));
}

function finsterMessagesHtml() {
  const finster = ensureFinsterState();
  const activeUid = finster.activeConversationUid;
  const own = finsterCurrentUid();
  const realPartners = [...new Set(finsterMessagesCache.flatMap((message) => message.participantUids || []).filter((uid) => uid && uid !== own))].map(finsterProfileByUid).filter(Boolean);
  const partners = realPartners;
  if (activeUid) {
    const profile = finsterProfileByUid(activeUid);
    const messages = finsterConversationMessages(activeUid);
    const sending = finsterMessageSendingTo === activeUid;
    const status = finsterMessageStatus || finsterRealtimeError;
    return `<section class="finster-chat"><header><button type="button" data-finster-close-chat>←</button>${finsterAvatarHtml(profile, "small")}<div><strong>${escapeHtml(profile?.displayName || "Chat")}</strong><small>@${escapeHtml(profile?.handle || "finster")}</small></div></header><div class="finster-chat-thread" data-finster-chat-thread>${messages.map((message) => `<p class="${message.senderUid === own || message.from === "me" ? "mine" : "theirs"}"><span>${escapeHtml(censorFinsterText(message.text || "", 800))}</span><small>${finsterTimeText(message.createdAtMs || message.at)}</small></p>`).join("") || `<p class="system"><span>Noch keine Nachrichten. Schreib Hallo.</span></p>`}</div>${status ? `<p class="finster-chat-status ${/fehl|nicht|error|permission|berechtigung/i.test(status) ? "error" : ""}" data-finster-message-status>${escapeHtml(status)}</p>` : ""}<form class="finster-chat-compose" data-finster-message-form data-recipient-uid="${escapeHtml(activeUid)}"><textarea data-finster-message-input maxlength="800" enterkeyhint="send" placeholder="Nachricht..." ${sending ? "disabled" : ""}>${escapeHtml(finsterMessageDrafts.get(activeUid) || "")}</textarea><button type="submit" data-finster-send-message="${activeUid}" ${sending ? "disabled" : ""}>${sending ? "Sendet…" : "Senden"}</button></form></section>`;
  }
  return `<section class="finster-inbox"><h3>Nachrichten</h3>${partners.map((profile) => `<button data-finster-message-user="${profile.uid}">${finsterAvatarHtml(profile, "small")}<div><strong>${escapeHtml(profile.displayName)}</strong><small>@${escapeHtml(profile.handle)}</small></div><span>›</span></button>`).join("") || `<div class="finster-empty"><p>Noch keine Chats. Öffne ein Profil und schreibe eine Nachricht.</p></div>`}</section>`;
}

function finsterOwnProfileHtml() {
  const finster = ensureFinsterState();
  const ownUid = finsterCurrentUid();
  const own = finsterProfileByUid(ownUid) || { uid: ownUid, handle: finster.handle, displayName: finster.displayName, bio: finster.bio, city: state.worldLocation || state.homeCity };
  const posts = finsterAllPosts().filter((post) => post.ownerUid === ownUid);
  return `<section class="finster-own-profile"><header>${finsterAvatarHtml(own, "large")}<div><h3>${escapeHtml(own.displayName || "Finster-Profil")}</h3><strong>@${escapeHtml(own.handle || "profil")}</strong></div></header><div class="finster-own-stats"><span><b>${posts.length}</b> Beiträge</span><span><b>${finster.following.length}</b> Gefolgt</span><span><b>${finster.likedPostIds.length}</b> Likes</span></div><p>${escapeHtml(own.bio || "Noch kein Profiltext.")}</p><button class="mini-button" data-finster-edit-profile>Profil bearbeiten</button><div class="finster-profile-grid">${posts.map((post) => `<button data-finster-open-post="${post.id}">${finsterImageHtml(post, "Eigener Beitrag")}</button>`).join("") || `<p>Du hast noch nichts gepostet.</p>`}</div></section>`;
}


function finstaConnectionOnline() {
  return navigator.onLine !== false && (!!firebasePhoneRuntime?.auth?.currentUser || !!window.LifeBuilderOnline?.getUser?.());
}

function finsterAppHtml() {
  const finster = ensureFinsterState();
  if (!finster.accountCreated) return `<div class="finster-app">${finsterAccountCreateHtml()}</div>`;
  let body = finsterFeedHtml();
  if (finster.view === "explore") body = finsterExploreHtml();
  if (finster.view === "create") body = finsterCreateHtml();
  if (finster.view === "messages") body = finsterMessagesHtml();
  if (finster.view === "profile") body = finsterOwnProfileHtml();
  if (finster.view === "post") body = finsterPostDetailHtml(finster.selectedPostId);
  if (finster.view === "user") body = finsterUserProfileHtml(finster.selectedUserUid);
  const online = finstaConnectionOnline() && finsterRealtimeState !== "error";
  const statusText = finsterRealtimeState === "loading" ? "Lädt …" : online ? "Online" : "Offline";
  return `<div class="finster-app"><div class="finster-topbar"><b>Finster.KL</b><span class="${online ? "online" : "offline"}">${statusText}</span></div><div class="finster-content">${body}</div>${finsterNavHtml(["post","user"].includes(finster.view) ? "" : finster.view)}</div>`;
}

async function createFinsterAccount(shell, item) {
  const handle = String(shell.querySelector("[data-finster-handle]")?.value || "").trim().toLowerCase().replace(/[^a-z0-9._-]/g, "").slice(0, 24);
  const displayName = censorFinsterText(shell.querySelector("[data-finster-display-name]")?.value || "", 40);
  const bio = censorFinsterText(shell.querySelector("[data-finster-bio]")?.value || "", 180);
  if (handle.length < 3) return addFeed("Der Finster-Benutzername braucht mindestens drei Zeichen.");
  if (!displayName) return addFeed("Bitte einen Anzeigenamen eingeben.");
  try {
    const fb = await ensureFinsterRealtime();
    const uid = fb.auth.currentUser.uid;
    const handleRef = fb.doc(fb.db, "finsterHandles", handle);
    const userRef = fb.doc(fb.db, "finsterUsers", uid);
    await fb.runTransaction(fb.db, async (transaction) => {
      const [handleDoc, userDoc] = await Promise.all([
        transaction.get(handleRef),
        transaction.get(userRef)
      ]);
      if (handleDoc.exists() && handleDoc.data().uid !== uid) throw new Error("Dieser Benutzername ist schon vergeben.");
      if (userDoc.exists() && userDoc.data()?.handle && userDoc.data().handle !== handle) {
        throw new Error("Dein Finster-Benutzername ist bereits fest vergeben.");
      }
      const now = Date.now();
      if (!handleDoc.exists()) transaction.set(handleRef, { uid, handle, createdAtMs: now });
      transaction.set(userRef, {
        uid,
        handle,
        displayName,
        bio,
        city: state.worldLocation || state.homeCity,
        avatarHue: Math.abs(stringSeed(uid)) % 360,
        createdAtMs: Number(userDoc.data()?.createdAtMs || now),
        updatedAtMs: now
      });
    });
    const finster = ensureFinsterState();
    Object.assign(finster, { handle, displayName, bio, accountCreated: true, view: "feed" });
    save();
    addFeed(`Finster.KL-Konto @${handle} erstellt.`);
    refreshDeviceApp("finster", item);
  } catch (error) {
    addFeed(`Finster-Konto konnte nicht erstellt werden: ${error.message || error}`);
  }
}

function selectFinsterFile(file, shell) {
  if (!file) return;
  if (!/^image\/(jpeg|png|webp|gif)$/.test(file.type) || file.size > 8 * 1024 * 1024) return addFeed("Bitte ein Bild im Format JPG, PNG, WEBP oder GIF bis 8 MB wählen.");
  if (finsterUploadPreviewUrl) URL.revokeObjectURL(finsterUploadPreviewUrl);
  finsterUploadFile = file;
  finsterUploadPreviewUrl = URL.createObjectURL(file);
  const preview = shell.querySelector("[data-finster-upload-preview]");
  if (preview) preview.innerHTML = `<img src="${finsterUploadPreviewUrl}" alt="Vorschau">`;
  const publish = shell.querySelector("[data-finster-publish]");
  if (publish) publish.disabled = false;
}

async function publishFinsterPost(shell, item) {
  const file = finsterUploadFile;
  const caption = censorFinsterText(shell.querySelector("[data-finster-caption]")?.value || "", 1000);
  const status = shell.querySelector("[data-finster-upload-status]");
  if (!file) return addFeed("Wähle zuerst ein Bild.");
  try {
    const fb = await ensureFinsterRealtime();
    const uid = fb.auth.currentUser.uid;
    const finster = ensureFinsterState();
    const postRef = fb.doc(fb.collection(fb.db, "finsterPosts"));
    const safeExt = (file.name.split(".").pop() || "jpg").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 5) || "jpg";
    const storageRef = fb.ref(fb.storage, `finster/${uid}/${postRef.id}.${safeExt}`);
    if (status) status.textContent = "Upload startet...";
    const task = fb.uploadBytesResumable(storageRef, file, { contentType: file.type, customMetadata: { ownerUid: uid, postId: postRef.id } });
    await new Promise((resolve, reject) => task.on("state_changed", (snapshot) => {
      if (status) status.textContent = `Upload ${Math.round(snapshot.bytesTransferred / snapshot.totalBytes * 100)} %`;
    }, reject, resolve));
    const imageUrl = await fb.getDownloadURL(storageRef);
    await fb.setDoc(postRef, {
      ownerUid: uid,
      handle: finster.handle,
      displayName: finster.displayName,
      caption,
      imageUrl,
      storagePath: storageRef.fullPath,
      createdAtMs: Date.now(),
      likeCount: 0,
      commentCount: 0,
      lastLikeUid: "",
      lastCommentId: ""
    });
    finsterUploadFile = null;
    if (finsterUploadPreviewUrl) URL.revokeObjectURL(finsterUploadPreviewUrl);
    finsterUploadPreviewUrl = "";
    finster.view = "feed";
    save();
    addFeed("Finster.KL-Beitrag veröffentlicht.");
    queuePurchaseConfirmation({ kind: "use", title: "Veröffentlicht", name: "Finster.KL-Beitrag", icon: "▧" });
    refreshDeviceApp("finster", item);
  } catch (error) {
    if (status) status.textContent = `Fehler: ${error.message || error}`;
    addFeed(`Beitrag konnte nicht veröffentlicht werden: ${error.message || error}`);
  }
}

function finsterRememberScroll() {
  const content = els.dialog?.querySelector?.(".finster-content");
  if (!content) return null;
  return {
    top: content.scrollTop,
    postId: [...content.querySelectorAll("[data-finster-post-card]")]
      .find((card) => card.getBoundingClientRect().bottom > content.getBoundingClientRect().top + 4)?.dataset.finsterPostCard || ""
  };
}

function finsterRestoreScroll(snapshot) {
  if (!snapshot) return;
  requestAnimationFrame(() => {
    const content = els.dialog?.querySelector?.(".finster-content");
    if (!content) return;
    const card = snapshot.postId ? content.querySelector(`[data-finster-post-card="${CSS.escape(snapshot.postId)}"]`) : null;
    if (card) {
      const contentTop = content.getBoundingClientRect().top;
      const cardTop = card.getBoundingClientRect().top;
      content.scrollTop += cardTop - contentTop;
    } else {
      content.scrollTop = snapshot.top;
    }
  });
}

async function toggleFinsterLike(postId, item) {
  const scrollSnapshot = finsterRememberScroll();
  const finster = ensureFinsterState();
  const post = finsterAllPosts().find((entry) => entry.id === postId);
  if (!post) return;
  const liked = finster.likedPostIds.includes(postId);
  if (post.ai) {
    finster.aiLikes[postId] = Math.max(0, Number(finster.aiLikes[postId] || 0) + (liked ? -1 : 1));
  } else {
    try {
      const fb = await ensureFinsterRealtime();
      const uid = fb.auth.currentUser.uid;
      const postRef = fb.doc(fb.db, "finsterPosts", postId);
      const likeRef = fb.doc(fb.db, "finsterPosts", postId, "likes", uid);
      await fb.runTransaction(fb.db, async (transaction) => {
        const [postDoc, likeDoc] = await Promise.all([transaction.get(postRef), transaction.get(likeRef)]);
        if (!postDoc.exists()) throw new Error("Beitrag existiert nicht mehr.");
        const count = Math.max(0, Number(postDoc.data().likeCount || 0));
        if (likeDoc.exists()) {
          transaction.delete(likeRef);
          transaction.update(postRef, { likeCount: Math.max(0, count - 1), lastLikeUid: uid });
        } else {
          transaction.set(likeRef, { ownerUid: uid, createdAtMs: Date.now() });
          transaction.update(postRef, { likeCount: count + 1, lastLikeUid: uid });
        }
      });
    } catch (error) {
      return addFeed(`Like fehlgeschlagen: ${error.message || error}`);
    }
  }
  finster.likedPostIds = liked ? finster.likedPostIds.filter((id) => id !== postId) : [...finster.likedPostIds, postId];
  save();
  refreshDeviceApp("finster", item);
  finsterRestoreScroll(scrollSnapshot);
}

async function loadFinsterComments(postId, item) {
  const finster = ensureFinsterState();
  finster.selectedPostId = postId;
  finster.view = "post";
  if (!postId.startsWith("ai-post-")) {
    try {
      const fb = await ensureFinsterRealtime();
      const queryComments = fb.query(fb.collection(fb.db, "finsterPosts", postId, "comments"), fb.orderBy("createdAtMs", "asc"), fb.limit(100));
      const snapshot = await fb.getDocs(queryComments);
      finsterCommentsCache.set(postId, snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
    } catch (error) {
      console.warn("Finster comments", error);
    }
  }
  save();
  refreshDeviceApp("finster", item);
}

async function sendFinsterComment(postId, textValue, item) {
  const clean = censorFinsterText(textValue, 500);
  if (!clean) return;
  const finster = ensureFinsterState();
  if (postId.startsWith("ai-post-")) {
    finster.aiComments[postId] ||= [];
    finster.aiComments[postId].push({ ownerUid: "me", handle: finster.handle, displayName: finster.displayName, text: clean, createdAtMs: Date.now() });
  } else {
    try {
      const fb = await ensureFinsterRealtime();
      const uid = fb.auth.currentUser.uid;
      const postRef = fb.doc(fb.db, "finsterPosts", postId);
      const commentRef = fb.doc(fb.collection(postRef, "comments"));
      const commentData = {
        ownerUid: uid,
        handle: finster.handle,
        displayName: finster.displayName,
        text: clean,
        createdAtMs: Date.now()
      };
      await fb.runTransaction(fb.db, async (transaction) => {
        const postDoc = await transaction.get(postRef);
        if (!postDoc.exists()) throw new Error("Beitrag existiert nicht mehr.");
        transaction.set(commentRef, commentData);
        transaction.update(postRef, {
          commentCount: Math.max(0, Number(postDoc.data().commentCount || 0)) + 1,
          lastCommentId: commentRef.id
        });
      });
      const cached = finsterCommentsCache.get(postId) || [];
      cached.push({ id: commentRef.id, ...commentData });
      finsterCommentsCache.set(postId, cached);
    } catch (error) {
      return addFeed(`Kommentar fehlgeschlagen: ${error.message || error}`);
    }
  }
  save();
  refreshDeviceApp("finster", item);
}

async function deleteFinsterPost(postId, item) {
  const post = finsterPostsCache.find((entry) => entry.id === postId);
  if (!post || post.ownerUid !== finsterCurrentUid()) return;
  try {
    const fb = await ensureFinsterRealtime();
    await fb.deleteDoc(fb.doc(fb.db, "finsterPosts", postId));
    if (post.storagePath) await fb.deleteObject(fb.ref(fb.storage, post.storagePath)).catch(() => {});
    addFeed("Finster.KL-Beitrag gelöscht.");
    refreshDeviceApp("finster", item);
  } catch (error) {
    addFeed(`Beitrag konnte nicht gelöscht werden: ${error.message || error}`);
  }
}

function finsterAiReply(profile, text) {
  const lower = String(text || "").toLowerCase();
  if (/hallo|hey|hi|moin/.test(lower)) return `Hey 😊 Schön, dass du schreibst. Wie läuft dein Tag?`;
  if (/bild|foto|post/.test(lower)) return `Danke! Das Bild ist in ${profile.city} entstanden. Ich hatte richtig Glück mit dem Licht.`;
  if (/wie geht|alles gut/.test(lower)) return "Ganz gut, etwas viel los, aber ich freue mich über die Nachricht.";
  if (/treffen|kaffee/.test(lower)) return "Erst mal ein bisschen schreiben, aber ein Kaffee klingt grundsätzlich gut.";
  return ["Klingt interessant. Erzähl mehr.", "Das sehe ich ähnlich 😊", "Was begeistert dich daran am meisten?", "Guter Punkt. Darüber habe ich noch nicht so nachgedacht."][Math.abs(stringSeed(`${profile.uid}:${text}`)) % 4];
}

async function sendFinsterMessage(uid, textValue, item) {
  const clean = censorFinsterText(textValue, 800);
  if (!clean || !uid || finsterMessageSendingTo) return;
  const profile = finsterProfileByUid(uid);
  const finster = ensureFinsterState();
  const input = els.dialog?.querySelector?.("[data-finster-message-input]");
  finsterMessageDrafts.set(uid, clean);
  finsterMessageSendingTo = uid;
  finsterMessageStatus = "Nachricht wird gesendet …";
  finsterRealtimeError = "";
  if (input) input.disabled = true;
  const sendButton = els.dialog?.querySelector?.("[data-finster-send-message]");
  if (sendButton) { sendButton.disabled = true; sendButton.textContent = "Sendet…"; }
  const statusNode = els.dialog?.querySelector?.("[data-finster-message-status]");
  if (statusNode) { statusNode.textContent = finsterMessageStatus; statusNode.classList.remove("error"); }

  try {
    const fb = await ensureFinsterRealtime();
    const own = fb.auth.currentUser?.uid;
    if (!own) throw new Error("Online-Anmeldung fehlt. Bitte JK.Games neu anmelden.");
    if (uid === own) throw new Error("Du kannst dir nicht selbst schreiben.");
    if (!profile) {
      const recipientDoc = await fb.getDoc(fb.doc(fb.db, "finsterUsers", uid));
      if (!recipientDoc.exists()) throw new Error("Das Empfängerprofil existiert nicht mehr.");
    }
    const participantUids = [own, uid].sort();
    const conversationId = participantUids.join("__");
    const createdAtMs = Date.now();
    const messageRef = fb.doc(fb.collection(fb.db, "finsterMessages"));
    await fb.setDoc(messageRef, {
      senderUid: own,
      recipientUid: uid,
      participantUids,
      conversationId,
      text: clean,
      createdAtMs
    });
    if (!finsterMessagesCache.some((message) => message.id === messageRef.id)) {
      finsterMessagesCache.push({ id: messageRef.id, senderUid: own, recipientUid: uid, participantUids, conversationId, text: clean, createdAtMs });
      finsterMessagesCache.sort((a, b) => Number(a.createdAtMs || 0) - Number(b.createdAtMs || 0));
    }
    finsterMessageDrafts.delete(uid);
    if (input) input.value = "";
    finsterMessageStatus = "Nachricht gesendet.";
    save();
  } catch (error) {
    const raw = String(error?.code || error?.message || error || "Unbekannter Fehler");
    const hint = /permission-denied|insufficient permissions|missing or insufficient permissions/i.test(raw)
      ? "Die V86-Regel für Finster.KL-Nachrichten fehlt noch in der Firestore-Datenbank gamekl."
      : raw;
    finsterMessageStatus = `Senden fehlgeschlagen: ${hint}`;
    finsterMessageDrafts.set(uid, clean);
    if (input) input.value = clean;
    addFeed(finsterMessageStatus);
  } finally {
    finsterMessageSendingTo = "";
    refreshDeviceApp("finster", item);
  }
}

async function updateFinsterProfile(shell, item) {
  const finster = ensureFinsterState();
  const displayName = censorFinsterText(prompt("Anzeigename", finster.displayName || state.firstName || "") || "", 40);
  if (!displayName) return;
  const bio = censorFinsterText(prompt("Profiltext", finster.bio || "") ?? finster.bio, 180);
  try {
    const fb = await ensureFinsterRealtime();
    const uid = fb.auth.currentUser.uid;
    const mine = finsterProfileByUid(uid) || {};
    await fb.setDoc(fb.doc(fb.db, "finsterUsers", uid), {
      uid,
      handle: finster.handle || mine.handle,
      displayName,
      bio,
      city: state.worldLocation || state.homeCity,
      avatarHue: Number(mine.avatarHue ?? Math.abs(stringSeed(uid)) % 360),
      createdAtMs: Number(mine.createdAtMs || Date.now()),
      updatedAtMs: Date.now()
    });
    finster.displayName = displayName;
    finster.bio = bio;
    save();
    refreshDeviceApp("finster", item);
  } catch (error) {
    addFeed(`Profil konnte nicht gespeichert werden: ${error.message || error}`);
  }
}

function bindFinsterDeviceActions(shell, item) {
  const finsterHostScreen = shell?.closest?.(".device-screen") || shell?.querySelector?.(".device-screen");
  if (finsterHostScreen) {
    finsterHostScreen.classList.add("finster-host-screen");
    finsterHostScreen.scrollTop = 0;
  }
  const finsterContent = shell?.querySelector?.(".finster-content");
  if (finsterContent && !finsterContent.dataset.finsterScrollBound) {
    finsterContent.dataset.finsterScrollBound = "1";
    const markInteraction = () => {
      window.__lifeBuilderFinsterInteractionUntil = Date.now() + 1300;
    };
    ["scroll", "touchstart", "touchmove", "pointerdown", "wheel"].forEach((type) => {
      finsterContent.addEventListener(type, markInteraction, { passive: true });
    });
  }
  ensureFinsterRealtime().catch((error) => addFeed(`Finster.KL Online: ${error.message || error}`));
  bindFinsterImages(shell);
  shell.querySelector("[data-finster-reconnect]")?.addEventListener("click", async () => {
    finsterRealtimeError = "";
    finsterRealtimeState = "loading";
    stopFinsterRealtime();
    await window.LifeBuilderFirebaseCore?.reconnect?.().catch(() => {});
    ensureFinsterRealtime().catch((error) => addFeed(`Finster.KL Verbindung: ${error.message || error}`));
    refreshDeviceApp("finster", item);
  });
  shell.querySelector("[data-finster-create-account]")?.addEventListener("click", () => createFinsterAccount(shell, item));
  shell.querySelectorAll("[data-finster-view]").forEach((button) => button.addEventListener("click", () => {
    const finster = ensureFinsterState();
    finster.view = button.dataset.finsterView || "feed";
    finster.selectedPostId = "";
    finster.selectedUserUid = "";
    if (finster.view !== "messages") finster.activeConversationUid = "";
    save();
    refreshDeviceApp("finster", item);
  }));
  shell.querySelector("[data-finster-file]")?.addEventListener("change", (event) => selectFinsterFile(event.target.files?.[0], shell));
  shell.querySelector("[data-finster-publish]")?.addEventListener("click", () => publishFinsterPost(shell, item));
  shell.querySelectorAll("[data-finster-like]").forEach((button) => button.addEventListener("click", () => toggleFinsterLike(button.dataset.finsterLike, item)));
  shell.querySelectorAll("[data-finster-open-post]").forEach((button) => button.addEventListener("click", () => loadFinsterComments(button.dataset.finsterOpenPost, item)));
  shell.querySelectorAll("[data-finster-open-user]").forEach((button) => button.addEventListener("click", () => {
    const finster = ensureFinsterState();
    finster.selectedUserUid = button.dataset.finsterOpenUser;
    finster.view = "user";
    save();
    refreshDeviceApp("finster", item);
  }));
  shell.querySelectorAll("[data-finster-message-user]").forEach((button) => button.addEventListener("click", () => {
    const finster = ensureFinsterState();
    finster.activeConversationUid = button.dataset.finsterMessageUser;
    finsterMessageStatus = "";
    finsterRealtimeError = "";
    finster.view = "messages";
    save();
    refreshDeviceApp("finster", item);
  }));
  shell.querySelector("[data-finster-close-chat]")?.addEventListener("click", () => {
    ensureFinsterState().activeConversationUid = "";
    save();
    refreshDeviceApp("finster", item);
  });
  shell.querySelectorAll("[data-finster-follow]").forEach((button) => button.addEventListener("click", () => {
    const finster = ensureFinsterState();
    const uid = button.dataset.finsterFollow;
    finster.following = finster.following.includes(uid) ? finster.following.filter((id) => id !== uid) : [...finster.following, uid];
    save();
    refreshDeviceApp("finster", item);
  }));
  shell.querySelector("[data-finster-comment-send]")?.addEventListener("click", (event) => sendFinsterComment(event.currentTarget.dataset.finsterCommentSend, shell.querySelector("[data-finster-comment-input]")?.value, item));
  shell.querySelector("[data-finster-comment-input]")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      shell.querySelector("[data-finster-comment-send]")?.click();
    }
  });
  shell.querySelector("[data-finster-message-form]")?.addEventListener("submit", (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    sendFinsterMessage(form.dataset.recipientUid, form.querySelector("[data-finster-message-input]")?.value, item);
  });
  shell.querySelector("[data-finster-message-input]")?.addEventListener("input", (event) => {
    const uid = event.currentTarget.form?.dataset.recipientUid || "";
    if (uid) finsterMessageDrafts.set(uid, event.currentTarget.value);
  });
  shell.querySelector("[data-finster-message-input]")?.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      event.currentTarget.form?.requestSubmit?.();
    }
  });
  shell.querySelectorAll("[data-finster-delete-post]").forEach((button) => button.addEventListener("click", () => deleteFinsterPost(button.dataset.finsterDeletePost, item)));
  shell.querySelector("[data-finster-edit-profile]")?.addEventListener("click", () => updateFinsterProfile(shell, item));
  shell.querySelector("[data-finster-search]")?.addEventListener("input", (event) => {
    const query = event.currentTarget.value.trim().toLowerCase();
    shell.querySelectorAll("[data-finster-user-card]").forEach((card) => card.hidden = query && !card.dataset.finsterUserCard.includes(query));
  });
  const thread = shell.querySelector("[data-finster-chat-thread]");
  if (thread) requestAnimationFrame(() => { thread.scrollTop = thread.scrollHeight; });
}

