function businessMapNodeDistance(a, b) {
  return Math.hypot((a.x - b.x) * 12.54, (a.y - b.y) * 12.54);
}

function nearestBusinessMapNode(position) {
  return Object.entries(businessMapGraph).reduce((best, [id, node]) => {
    const distance = businessMapNodeDistance(position, node);
    return !best || distance < best.distance ? { id, distance } : best;
  }, null)?.id || "entry";
}

function nearestBusinessMapRoadTarget(position) {
  let best = null;
  const visited = new Set();
  Object.entries(businessMapGraph).forEach(([startId, start]) => {
    (start.links || []).forEach((endId) => {
      const edgeKey = [startId, endId].sort().join(":");
      if (visited.has(edgeKey) || !businessMapGraph[endId]) return;
      visited.add(edgeKey);
      const end = businessMapGraph[endId];
      const dx = end.x - start.x;
      const dy = end.y - start.y;
      const lengthSquared = dx * dx + dy * dy || 1;
      const t = clamp(((position.x - start.x) * dx + (position.y - start.y) * dy) / lengthSquared, 0, 1);
      const point = { x: start.x + dx * t, y: start.y + dy * t };
      const distance = businessMapNodeDistance(position, point);
      if (!best || distance < best.distance) best = { startId, endId, point, distance };
    });
  });
  return best || { startId: "entry", endId: "southHub", point: businessMapGraph.entry, distance: 0 };
}

function businessMapPathDistance(path = []) {
  return path.slice(1).reduce((sum, nodeId, index) => {
    const previous = businessMapGraph[path[index]];
    const current = businessMapGraph[nodeId];
    return sum + (previous && current ? businessMapNodeDistance(previous, current) : 0);
  }, 0);
}

function businessMapRoutePlanFromPosition(position, targetNodeId) {
  const nearestNodeId = nearestBusinessMapNode(position);
  const nearestNode = businessMapGraph[nearestNodeId];
  if (nearestNode && businessMapNodeDistance(position, nearestNode) < 2) {
    const route = businessMapShortestPath(nearestNodeId, targetNodeId);
    return { firstPoint: null, route, cost: businessMapPathDistance(route) };
  }
  const road = nearestBusinessMapRoadTarget(position);
  const candidates = [road.startId, road.endId].map((nodeId) => {
    const route = businessMapShortestPath(nodeId, targetNodeId);
    return {
      firstPoint: businessMapGraph[nodeId],
      route,
      cost: businessMapNodeDistance(position, businessMapGraph[nodeId]) + businessMapPathDistance(route)
    };
  });
  return candidates.sort((a, b) => a.cost - b.cost)[0];
}

function businessMapShortestPath(startId, endId) {
  if (startId === endId) return [startId];
  const distances = Object.fromEntries(Object.keys(businessMapGraph).map((id) => [id, Infinity]));
  const previous = {};
  const unvisited = new Set(Object.keys(businessMapGraph));
  distances[startId] = 0;
  while (unvisited.size) {
    let current = null;
    unvisited.forEach((id) => { if (current == null || distances[id] < distances[current]) current = id; });
    if (current == null || distances[current] === Infinity) break;
    unvisited.delete(current);
    if (current === endId) break;
    const node = businessMapGraph[current];
    (node.links || []).forEach((next) => {
      if (!unvisited.has(next)) return;
      const candidate = distances[current] + businessMapNodeDistance(node, businessMapGraph[next]);
      if (candidate < distances[next]) {
        distances[next] = candidate;
        previous[next] = current;
      }
    });
  }
  const path = [];
  let cursor = endId;
  while (cursor) {
    path.unshift(cursor);
    if (cursor === startId) break;
    cursor = previous[cursor];
  }
  return path[0] === startId ? path : [startId, endId];
}

function currentBusinessMapPosition() {
  const avatar = businessMapOverlay?.querySelector("[data-business-map-avatar]");
  const map = businessMapOverlay?.querySelector("[data-business-map-stage]");
  if (!avatar || !map) return state.blackBusiness?.mapPosition || businessMapGraph.entry;
  const mapRect = map.getBoundingClientRect();
  const avatarRect = avatar.getBoundingClientRect();
  if (!mapRect.width || !mapRect.height) return state.blackBusiness?.mapPosition || businessMapGraph.entry;
  return {
    x: ((avatarRect.left + avatarRect.width / 2 - mapRect.left) / mapRect.width) * 100,
    y: ((avatarRect.top + avatarRect.height / 2 - mapRect.top) / mapRect.height) * 100
  };
}

