function businessSleepCooldownStatus(target, lastDayMap) {
  const lastDay = Number(lastDayMap?.[target.id] || 0);
  const currentDay = Number(state.day || 1);
  const days = Math.max(1, Number(target.cooldownDays || 1));
  if (!lastDay) return { ready: true, remaining: 0, text: days === 1 ? "Einmal pro Spieltag" : `Nach Nutzung ${days} Schlaf-Tage Pause` };
  const elapsed = Math.max(0, currentDay - lastDay);
  const remaining = Math.max(0, days - elapsed);
  if (remaining <= 0) return { ready: true, remaining: 0, text: "Wieder verfügbar" };
  return { ready: false, remaining, text: remaining === 1 ? "Noch 1× schlafen" : `Noch ${remaining}× schlafen` };
}

function heistCooldownStatus(target) {
  const black = state.blackBusiness ||= createBlackBusinessState();
  black.heistLastDay ||= {};
  return businessSleepCooldownStatus(target, black.heistLastDay);
}

function courierCooldownStatus(target) {
  const black = state.blackBusiness ||= createBlackBusinessState();
  black.courierLastDay ||= {};
  return businessSleepCooldownStatus(target, black.courierLastDay);
}

