function findProperty(id) {
  if (id === "starter-home-rental" && state?.starterHome?.active) {
    const meta = state.propertyMeta?.[id];
    return {
      id: "starter-home-rental",
      name: state.starterHome.type || "Einraumwohnung",
      city: state.starterHome.city || state.homeCity || "Essen",
      district: "Startviertel",
      rooms: 1,
      roomNames: Array.isArray(state.starterHome.rooms) ? state.starterHome.rooms : ["Wohn-/Schlafraum", "Küche", "Bad"],
      sqm: 31,
      floors: 1,
      storageType: "Kellerbox",
      dailyRent: Math.max(0, Number(state.starterHome.dailyRent || 0)),
      isTenantRental: true,
      isStarterHome: true,
      rentalTier: "small",
      eur: 95000,
      ...(meta || {})
    };
  }
  const tenant = activeTenantRentalProperty();
  if (tenant?.id === id) {
    const meta = state.propertyMeta?.[id];
    return { ...tenant, ...(meta || {}), isTenantRental: true, dailyRent: state.tenantLease?.dailyRent || tenant.dailyRent || 0 };
  }
  const base = [...realEstateItems, ...(state.customProperties || [])].find((entry) => entry.id === id);
  const meta = state.propertyMeta?.[id];
  return base ? { ...base, ...(meta || {}) } : null;
}

function isWorkshopTuningItem(item) {
  return /tuning/i.test(item?.name || "");
}

function vehicleValue(item) {
  const shop = shopItems.find((entry) => entry.item === item);
  const base = shop?.price || {
    "Auto": 8900,
    "Neuwagen": 21900,
    "Gebrauchtwagen Kompakt ohne TÜV": 500,
    "Gebrauchtwagen Kombi": 7400,
    "Gebrauchtwagen SUV": 11800,
    "Gebrauchtwagen Sport": 27900,
    "Neuwagen Elektro": 32900,
    "Elektro Limousine": 48900,
    "Elektro SUV": 62900,
    "Elektro Sportwagen": 119000,
    "Neuwagen Limousine": 45900,
    "Neuwagen Sport": 68900,
    "Luxuswagen Supercar": 249000,
    "Motorboot": 42000,
    "Luxus-Yacht": 1800000
  }[item] || 500;
  const tuned = state.vehicleMeta?.[item]?.valueBonus || 0;
  return base + tuned;
}

function openVehicleTuningSelection(item) {
  const vehicles = state.items.filter((entry) => vehicleItems().includes(entry));
  if (!vehicles.length) return addFeed("Du brauchst zuerst ein Fahrzeug, Boot oder eine Yacht.");
  clearDialogDynamic();
  els.dialogTitle.textContent = item.name;
  els.dialogText.textContent = "Wähle aus, welches Fahrzeug, Boot oder welche Yacht du tunen möchtest.";
  const list = document.createElement("div");
  list.className = "market-list";
  list.innerHTML = vehicles.map((vehicle, index) => card(vehicle, `Aktueller Wert: ${euro.format(vehicleValue(vehicle))}. Tuning erhöht den Wert und verbessert Handwerk.`, "Tunen", index, false, "vehicle-tune")).join("");
  const close = document.createElement("button");
  close.className = "mini-button";
  close.textContent = "Abbrechen";
  close.onclick = () => els.dialog.close();
  els.dialog.append(list, close);
  list.querySelectorAll('button[data-kind="vehicle-tune"]').forEach((button) => {
    button.addEventListener("click", () => openShopPaymentDialog({ ...item, tuningTarget: vehicles[Number(button.dataset.index)], needItem: "" }));
  });
  if (!els.dialog.open) els.dialog.showModal();
}

function applyVehicleTuning(vehicle, cost) {
  state.vehicleMeta ||= {};
  const meta = state.vehicleMeta[vehicle] || { tuning: 0, valueBonus: 0 };
  meta.tuning = (meta.tuning || 0) + 1;
  meta.valueBonus = (meta.valueBonus || 0) + Math.round(cost * (0.55 + Math.min(0.25, meta.tuning * 0.03)));
  state.vehicleMeta[vehicle] = meta;
  addFeed(`${vehicle}: Tuning Stufe ${meta.tuning}, Wertbonus ${euro.format(meta.valueBonus)}.`);
}


function quickVehicleSaleValue(item) {
  const factor = 0.34 + ((item.length * 13) % 18) / 100;
  return Math.max(50, Math.round(vehicleValue(item) * factor));
}

function sellVehicleNow(item) {
  const index = state.items.indexOf(item);
  if (index < 0) return;
  const amount = quickVehicleSaleValue(item);
  state.items.splice(index, 1);
  payoutFromTreasury(amount);
  recordIncome("vehicles", amount);
  addFeed(`${item} sofort verkauft: ${euro.format(amount)} erhalten.`, { purchase: { kind: "sell", title: "Fahrzeug verkauft", name: item, total: amount, method: "Konto", icon: "🚗" } });
  save();
  render();
}

function listVehicleForSale(item) {
  const index = state.items.indexOf(item);
  if (index < 0) return;
  state.vehicleSaleOffers ||= [];
  if (state.vehicleSaleOffers.some((offer) => offer.item === item)) return addFeed(`${item} ist bereits inseriert.`);
  const value = vehicleValue(item);
  const ask = Math.round(value * (0.68 + Math.random() * 0.32));
  const chance = Math.max(0.18, Math.min(0.72, 1.05 - ask / value));
  if (Math.random() < chance) {
    state.items.splice(index, 1);
    payoutFromTreasury(ask);
    recordIncome("vehicles", ask);
    addFeed(`${item} inseriert und verkauft: ${euro.format(ask)} erhalten.`, { purchase: { kind: "sell", title: "Fahrzeug verkauft", name: item, total: ask, method: "Konto", icon: "🚗" } });
  } else {
    state.vehicleSaleOffers.push({ item, ask, chance });
    addFeed(`${item} wurde für ${euro.format(ask)} angeboten. Noch kein Käufer gefunden.`);
  }
  save();
  render();
}

function retryVehicleOffer(item) {
  state.vehicleSaleOffers ||= [];
  const offerIndex = state.vehicleSaleOffers.findIndex((offer) => offer.item === item);
  const itemIndex = state.items.indexOf(item);
  if (offerIndex < 0) return;
  if (itemIndex < 0) {
    state.vehicleSaleOffers.splice(offerIndex, 1);
    save();
    render();
    return;
  }
  const offer = state.vehicleSaleOffers[offerIndex];
  if (Math.random() < offer.chance) {
    state.items.splice(itemIndex, 1);
    payoutFromTreasury(offer.ask);
    recordIncome("vehicles", offer.ask);
    state.vehicleSaleOffers.splice(offerIndex, 1);
    addFeed(`${item} wurde über dein Inserat verkauft: ${euro.format(offer.ask)} erhalten.`, { purchase: { kind: "sell", title: "Fahrzeug verkauft", name: item, total: offer.ask, method: "Konto", icon: "🚗" } });
  } else {
    offer.chance = Math.min(0.85, offer.chance + 0.08);
    addFeed(`Noch kein Käufer für ${item}. Die Chance steigt beim nächsten Versuch.`);
  }
  save();
  render();
}

