function pendingAchievementCount() {
  if (!state) return 0;
  state.claimedAchievements ||= [];
  return achievementDefinitions().reduce((count, entry) => {
    if (state.claimedAchievements.includes(entry.id)) return count;
    try {
      return count + (entry.done() ? 1 : 0);
    } catch {
      return count;
    }
  }, 0);
}

function claimAchievement(entry) {
  if (!entry?.done()) return;
  state.claimedAchievements ||= [];
  if (state.claimedAchievements.includes(entry.id)) return;
  const content = els.dialog?.querySelector(".character-hub-content");
  const scrollTop = content?.scrollTop || 0;
  state.claimedAchievements.push(entry.id);
  state.skillPoints = (state.skillPoints || 0) + 1;
  improveMood(4, `Erfolg „${entry.name}“ abgeholt`, { feed: false });
  addFeed(`Erfolg geholt: ${entry.name}. +1 Skillpunkt und +4 Stimmung.`);
  save();
  updateHeaderStatusUi(true);
  if (els.dialog?.open && els.dialog.querySelector(".character-hub")) {
    openCharacterHub("achievements");
    requestAnimationFrame(() => {
      const nextContent = els.dialog?.querySelector(".character-hub-content");
      if (nextContent) nextContent.scrollTop = scrollTop;
    });
  } else {
    render();
  }
}

