function casinoMapDistance(a, b) {
  return Math.hypot((Number(a?.x) || 0) - (Number(b?.x) || 0), (Number(a?.y) || 0) - (Number(b?.y) || 0));
}

function casinoMapShortestPath(startId, endId) {
  if (!casinoMapGraph[startId] || !casinoMapGraph[endId]) return [];
  const distances = Object.fromEntries(Object.keys(casinoMapGraph).map((id) => [id, Infinity]));
  const previous = {};
  const unvisited = new Set(Object.keys(casinoMapGraph));
  distances[startId] = 0;
  while (unvisited.size) {
    let current = null;
    unvisited.forEach((id) => {
      if (current == null || distances[id] < distances[current]) current = id;
    });
    if (current == null || !Number.isFinite(distances[current])) break;
    unvisited.delete(current);
    if (current === endId) break;
    const node = casinoMapGraph[current];
    (node.links || []).forEach((next) => {
      if (!unvisited.has(next) || !casinoMapGraph[next]) return;
      const candidate = distances[current] + casinoMapDistance(node, casinoMapGraph[next]);
      if (candidate < distances[next]) {
        distances[next] = candidate;
        previous[next] = current;
      }
    });
  }
  const path = [];
  let cursor = endId;
  while (cursor) {
    path.unshift(cursor);
    if (cursor === startId) break;
    cursor = previous[cursor];
  }
  return path[0] === startId ? path : [];
}

function casinoMapNearestNode(position) {
  return Object.entries(casinoMapGraph).reduce((best, [id, node]) => {
    const distance = casinoMapDistance(position, node);
    return !best || distance < best.distance ? { id, node, distance } : best;
  }, null);
}

function casinoMapPointOnSegment(position, start, end) {
  const dx = end.x - start.x;
  const dy = end.y - start.y;
  const lengthSq = dx * dx + dy * dy || 1;
  const t = Math.max(0, Math.min(1, ((position.x - start.x) * dx + (position.y - start.y) * dy) / lengthSq));
  return { x: start.x + dx * t, y: start.y + dy * t, t };
}

function casinoMapNearestRoadPoint(position) {
  const visited = new Set();
  let best = null;
  Object.entries(casinoMapGraph).forEach(([startId, start]) => {
    (start.links || []).forEach((endId) => {
      const edgeKey = [startId, endId].sort().join(":");
      if (visited.has(edgeKey) || !casinoMapGraph[endId]) return;
      visited.add(edgeKey);
      const end = casinoMapGraph[endId];
      const point = casinoMapPointOnSegment(position, start, end);
      const distance = casinoMapDistance(position, point);
      if (!best || distance < best.distance) best = { startId, endId, point, distance };
    });
  });
  return best || { startId: "parking", endId: "parkingExit", point: casinoMapGraph.parking, distance: 0 };
}

function casinoMapRouteFromPosition(position, targetNodeId) {
  const nearestRoad = casinoMapNearestRoadPoint(position);
  const candidates = [nearestRoad.startId, nearestRoad.endId].map((endpointId) => {
    const route = casinoMapShortestPath(endpointId, targetNodeId);
    const points = [position];
    if (casinoMapDistance(position, nearestRoad.point) > .2) points.push(nearestRoad.point);
    if (casinoMapDistance(nearestRoad.point, casinoMapGraph[endpointId]) > .2) points.push(casinoMapGraph[endpointId]);
    route.slice(1).forEach((id) => points.push(casinoMapGraph[id]));
    return { endpointId, route, points, distance: casinoPolylineDistance(points) };
  }).filter((entry) => entry.route.length);
  candidates.sort((a, b) => a.distance - b.distance);
  return candidates[0] || { points: [position, casinoMapGraph[targetNodeId]], distance: casinoMapDistance(position, casinoMapGraph[targetNodeId]) };
}

function casinoPolylineDistance(points = []) {
  return points.reduce((sum, point, index) => index ? sum + casinoMapDistance(points[index - 1], point) : 0, 0);
}

function casinoPointAlongPolyline(points = [], travelled = 0) {
  if (!points.length) return casinoMapGraph.parking;
  if (points.length === 1) return points[0];
  let remaining = Math.max(0, travelled);
  for (let index = 1; index < points.length; index += 1) {
    const start = points[index - 1];
    const end = points[index];
    const length = casinoMapDistance(start, end);
    if (remaining <= length || index === points.length - 1) {
      const t = length ? Math.max(0, Math.min(1, remaining / length)) : 1;
      return { x: start.x + (end.x - start.x) * t, y: start.y + (end.y - start.y) * t };
    }
    remaining -= length;
  }
  return points.at(-1);
}

function currentCasinoMapPosition(now = Date.now()) {
  const walk = state.casinoWalk;
  if (!walk?.points?.length || now >= walk.arriveAt) return state.casinoMapPosition || casinoMapGraph.parking;
  const duration = Math.max(1, walk.arriveAt - walk.startedAt);
  const progress = Math.max(0, Math.min(1, (now - walk.startedAt) / duration));
  return casinoPointAlongPolyline(walk.points, (walk.distance || casinoPolylineDistance(walk.points)) * progress);
}

function casinoMapTravelTime(distance) {
  return Math.max(650, Math.min(10500, Math.round(distance * 105)));
}

function startCasinoMapWalk(points, options = {}) {
  const cleanPoints = (points || []).filter(Boolean).map((point) => ({ x: Number(point.x) || 0, y: Number(point.y) || 0 }));
  if (cleanPoints.length < 2) return;
  const distance = casinoPolylineDistance(cleanPoints);
  const startedAt = Date.now();
  state.casinoWalk = {
    points: cleanPoints,
    distance,
    startedAt,
    arriveAt: startedAt + casinoMapTravelTime(distance),
    targetArea: options.targetArea || "",
    targetNode: options.targetNode || ""
  };
  state.casinoArea = "";
  state.casinoMessage = "";
  save();
  render();
}

function openCasinoAreaAtCurrentPosition(area, node = "") {
  state.casinoWalk = null;
  state.casinoArea = area;
  state.casinoLastArea = area;
  if (node && casinoMapGraph[node]) state.casinoMapPosition = { ...casinoMapGraph[node], node };
  const view = casinoAreaToView(area);
  if (view) state.casinoView = view;
  if (!activeCasinoChips().includes(state.casinoChipCents)) state.casinoChipCents = activeCasinoChips()[0];
  state.casinoMessage = "";
  save();
  render();
}

function walkToCasinoArea(area) {
  const building = casinoMapBuildings.find((entry) => entry.id === area);
  if (!building || !casinoMapGraph[building.node]) return;
  const current = currentCasinoMapPosition();
  const route = casinoMapRouteFromPosition(current, building.node);
  if (!route.points?.length || route.distance < 0.45 || casinoMapDistance(current, casinoMapGraph[building.node]) < 0.45) {
    openCasinoAreaAtCurrentPosition(area, building.node);
    return;
  }
  startCasinoMapWalk(route.points, { targetArea: area, targetNode: building.node });
}

function walkToCasinoRoad(position) {
  const road = casinoMapNearestRoadPoint(position);
  const current = currentCasinoMapPosition();
  const candidates = [road.startId, road.endId].map((endpointId) => {
    const route = casinoMapRouteFromPosition(current, endpointId);
    const points = [...route.points];
    if (casinoMapDistance(points.at(-1), road.point) > .2) points.push(road.point);
    return { points, distance: casinoPolylineDistance(points) };
  });
  candidates.sort((a, b) => a.distance - b.distance);
  startCasinoMapWalk(candidates[0].points, { targetArea: "", targetNode: "" });
}

