function bindCasinoEvents() {
  const mapStage = els.casinoList.querySelector("[data-casino-map-stage]");
  const mapViewport = els.casinoList.querySelector("[data-casino-map-viewport]");
  let panStart = null;
  let panMoved = false;

  mapViewport?.addEventListener("pointerdown", (event) => {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    const current = casinoCurrentMapPan(mapViewport);
    panStart = {
      x: event.clientX,
      y: event.clientY,
      panX: current.x,
      panY: current.y,
      pointerId: event.pointerId
    };
    panMoved = false;
    mapViewport.classList.add("is-panning");
  });
  mapViewport?.addEventListener("pointermove", (event) => {
    if (!panStart || event.pointerId !== panStart.pointerId) return;
    const dx = event.clientX - panStart.x;
    const dy = event.clientY - panStart.y;
    if (!panMoved && Math.hypot(dx, dy) > 7) {
      panMoved = true;
      mapViewport.dataset.casinoMapDragging = "true";
      mapViewport.setPointerCapture?.(event.pointerId);
    }
    if (!panMoved) return;
    applyCasinoMapPan(mapViewport, panStart.panX + dx, panStart.panY + dy);
    event.preventDefault();
  }, { passive: false });
  const finishPan = (event) => {
    if (panStart && event?.pointerId != null && event.pointerId !== panStart.pointerId) return;
    if (panStart && event?.pointerId != null && mapViewport?.hasPointerCapture?.(event.pointerId)) {
      mapViewport.releasePointerCapture(event.pointerId);
    }
    panStart = null;
    mapViewport?.classList.remove("is-panning");
    if (panMoved) setTimeout(() => {
      if (mapViewport) delete mapViewport.dataset.casinoMapDragging;
    }, 40);
    else if (mapViewport) delete mapViewport.dataset.casinoMapDragging;
  };
  mapViewport?.addEventListener("pointerup", finishPan);
  mapViewport?.addEventListener("pointercancel", finishPan);
  mapViewport?.addEventListener("pointerleave", (event) => {
    if (event.pointerType === "mouse" && panStart) finishPan(event);
  });

  if (mapViewport && !("PointerEvent" in window)) {
    let touchStart = null;
    mapViewport.addEventListener("touchstart", (event) => {
      const touch = event.touches[0];
      if (!touch) return;
      const current = casinoCurrentMapPan(mapViewport);
      touchStart = { x: touch.clientX, y: touch.clientY, panX: current.x, panY: current.y };
      panMoved = false;
      mapViewport.classList.add("is-panning");
    }, { passive: true });
    mapViewport.addEventListener("touchmove", (event) => {
      const touch = event.touches[0];
      if (!touch || !touchStart) return;
      const dx = touch.clientX - touchStart.x;
      const dy = touch.clientY - touchStart.y;
      if (!panMoved && Math.hypot(dx, dy) > 7) {
        panMoved = true;
        mapViewport.dataset.casinoMapDragging = "true";
      }
      if (!panMoved) return;
      applyCasinoMapPan(mapViewport, touchStart.panX + dx, touchStart.panY + dy);
      event.preventDefault();
    }, { passive: false });
    const finishTouchPan = () => {
      touchStart = null;
      mapViewport.classList.remove("is-panning");
      if (panMoved) setTimeout(() => delete mapViewport.dataset.casinoMapDragging, 40);
      else delete mapViewport.dataset.casinoMapDragging;
    };
    mapViewport.addEventListener("touchend", finishTouchPan, { passive: true });
    mapViewport.addEventListener("touchcancel", finishTouchPan, { passive: true });
  }

  mapStage?.addEventListener("click", (event) => {
    if (mapViewport?.dataset.casinoMapDragging === "true") return;
    if (event.target.closest("[data-casino-area]")) return;
    const rect = mapStage.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const position = {
      x: ((event.clientX - rect.left) / rect.width) * 100,
      y: ((event.clientY - rect.top) / rect.height) * 100
    };
    walkToCasinoRoad(position);
  });

  els.casinoList.querySelectorAll("[data-casino-area]").forEach((button) => button.addEventListener("click", (event) => {
    if (mapViewport?.dataset.casinoMapDragging === "true") return;
    event.stopPropagation();
    walkToCasinoArea(button.dataset.casinoArea);
  }));

  const casinoModalBackdrop = els.casinoList.querySelector("[data-casino-modal-backdrop]");
  casinoModalBackdrop?.addEventListener("click", (event) => {
    if (event.target !== casinoModalBackdrop) return;
    state.casinoLastArea = state.casinoArea || state.casinoLastArea || "";
    state.casinoArea = "";
    state.casinoMessage = "";
    save();
    render();
  });

  bindCasinoPanelEvents(els.casinoList);
}

