      <div class="casino-kpi-row"><span><small>Gesamteinsatz</small><b>${formatCents(total)}</b></span><span><small>Letzte Zahl</small><b>${state.roulette.lastNumber ?? "–"}</b></span><span><small>Letzte Auszahlung</small><b>${formatCents(state.roulette.lastPayout||0)}</b></span></div>
