      <div class="casino-kpi-row"><span><small>Drehungen</small><b>${stats.spins||0}</b></span><span><small>Gewinne</small><b>${stats.wins||0}</b></span><span><small>Größter Gewinn</small><b>${formatCents(stats.biggestWin||0)}</b></span></div>
