function riskPositionLabel(gamble) {
  const ladder = gamble.side === "top" ? riskLadderTop : riskLadderMain;
  return ladder[gamble.rung]?.label || "Leiter";
}

function makeEmptyReels(count = 5, symbols = ["🍒", "🍋", "🍇"]) {
  return Array.from({ length: count }, (_, reel) => [
    symbols[reel % symbols.length],
    symbols[(reel + 1) % symbols.length],
    symbols[(reel + 2) % symbols.length]
  ]);
}

function spinSlot(power) {
  const game = slotGames.find((entry) => entry.id === state.slots.selected) || slotGames[0];
  const bet = power ? state.casinoChipCents * 5 : state.casinoChipCents;
  const free = state.slots.freeSpins > 0 && !power;
  if (state.slots.spinning) return;
  if (state.slots.gamble?.amount > 0 && !state.slots.autoSpin) return casinoMessage("Nimm den Gewinn oder spiele erst das Risiko-Spiel.");
  if (!free && !takeWallet(bet)) return casinoMessage("Nicht genug Casino-Guthaben für diesen Dreh. Zahle Geld ein oder wähle einen kleineren Chip.");
  state.casinoMessage = "";
  playCasinoSound("spin");
  if (free) state.slots.freeSpins -= 1;
  state.slots.spinning = true;
  state.slots.gamble = null;
  state.slots.winCells = [];
  state.slots.message = "Walzen drehen...";
  state.slots.reels = Array.from({ length: game.reels }, (_, reel) => spinPreviewReel(game, reel));
  const finalReels = makeFinalSlotReels(game, power || free, free);
  state.slots.pending = { reels: finalReels, bet, gameId: game.id, free };
  state.slots.finishAt = Date.now() + 900 + game.reels * 180;
  save();
  refreshCasinoPanelStable();
  clearTimeout(slotSpinTimer);
  slotSpinTimer = setTimeout(finishSlotSpin, Math.max(40, state.slots.finishAt - Date.now()));
}

function finishSlotSpin() {
  clearTimeout(slotSpinTimer);
  slotSpinTimer = null;
  if (!state?.slots?.spinning || !state.slots.pending) return;
  const game = slotGames.find((entry) => entry.id === state.slots.pending.gameId) || slotGames[0];
  const reels = state.slots.pending.reels;
  const bet = state.slots.pending.bet;
  state.slots.reels = reels;
  const result = scoreSlot(game, reels, bet, { free: !!state.slots.pending.free });
  state.slots.lastWin = result.win;
  state.slots.stats ||= { spins: 0, wins: 0, biggestWin: 0 };
  state.slots.stats.spins += 1;
  if (result.win > 0) state.slots.stats.wins += 1;
  state.slots.stats.biggestWin = Math.max(state.slots.stats.biggestWin || 0, result.win || 0);
  state.slots.message = result.message;
  state.slots.winCells = result.winCells || [];
  if (result.freeSpins) state.slots.freeSpins += result.freeSpins;
  if (result.win) {
    payoutFromCasino(result.win);
    state.slots.gamble = createSlotGamble(result.win);
    triggerWinExplosion(result.win);
  }
  state.slots.spinning = false;
  state.slots.pending = null;
  state.slots.finishAt = null;
  addFeed(`${game.name}: ${result.message} Gewinn ${formatCents(result.win)}.`);
  save();
  refreshCasinoPanelStable();
  scheduleAutoSpin();
}

function spinPreviewReel(game, reel) {
  return Array.from({ length: 3 }, (_, row) => game.symbols[(reel + row + Math.floor(Math.random() * game.symbols.length)) % game.symbols.length]);
}

function makeFinalSlotReels(game, boosted = false, free = false) {
  const reels = Array.from({ length: game.reels }, () => {
    const col = [];
    let scatterPlaced = false;
    for (let row = 0; row < 3; row += 1) {
      let symbol = pickSlotSymbol(game, boosted);
      if (game.scatterMaxPerReel && symbol === game.scatter && scatterPlaced) {
        const safeSymbols = weightedSlotSymbols(game, boosted).filter((entry) => entry !== game.scatter);
        symbol = safeSymbols[Math.floor(Math.random() * safeSymbols.length)];
      }
      if (symbol === game.scatter) scatterPlaced = true;
      col.push(symbol);
    }
    return col;
  });
  return applySlotFeatureReels(game, reels, free);
}

function applySlotFeatureReels(game, reels, free = false) {
  if (game.id !== "horus" || !free) return reels;
  return reels.map((col) => {
    if (!col.includes(game.wild)) return col;
    return [game.wild, game.wild, game.wild];
  });
}

function toggleAutoSpin() {
  state.slots.autoSpin = !state.slots.autoSpin;
  if (!state.slots.autoSpin) {
    clearTimeout(autoSpinTimer);
    autoSpinTimer = null;
    state.slots.message = "Autodrehen gestoppt.";
    save();
    refreshCasinoPanelStable();
    return;
  }
  state.slots.gamble = null;
  state.slots.message = "Autodrehen aktiv.";
  save();
  refreshCasinoPanelStable();
  scheduleAutoSpin(250);
}

function scheduleAutoSpin(delay = 850) {
  clearTimeout(autoSpinTimer);
  autoSpinTimer = null;
  if (!state?.slots?.autoSpin || state.slots.spinning) return;
  const game = slotGames.find((entry) => entry.id === state.slots.selected) || slotGames[0];
  const bet = state.slots.freeSpins > 0 ? 0 : state.casinoChipCents;
  if (walletCents() < bet) {
    state.slots.autoSpin = false;
    state.slots.message = "Autodrehen beendet: nicht genug Guthaben.";
    save();
    refreshCasinoPanelStable();
    return;
  }
  state.slots.gamble = null;
  autoSpinTimer = setTimeout(() => spinSlot(false), delay);
}

function collectSlotGamble() {
  if (!state.slots.gamble) return;
  state.slots.message = `Gewinn genommen: ${formatCents(state.slots.gamble.amount)}.`;
  state.slots.gamble = null;
  save();
  refreshCasinoPanelStable();
}

function createSlotGamble(amount) {
  const topIndex = closestRiskIndex(riskLadderTop, amount);
  if (amount >= 10000 && topIndex >= 0) {
    return { amount, side: "top", rung: topIndex, mode: "choice", cards: [] };
  }
  return { amount, side: "main", rung: closestRiskIndex(riskLadderMain, amount), mode: "choice", cards: [] };
}

function setSlotRiskMode(mode) {
  if (!state.slots.gamble) return;
  state.slots.gamble.mode = mode === "cards" ? "cards" : "ladder";
  state.slots.message = mode === "cards" ? "Kartenrisiko gestartet." : "Leiterrisiko gestartet.";
  save();
  refreshCasinoPanelStable();
}

function closestRiskIndex(ladder, amount) {
  let best = 0;
  ladder.forEach((step, index) => {
    if (step.cents != null && step.cents <= amount) best = index;
  });
  return best;
}

function gambleSlotLadder() {
  const gamble = state.slots.gamble;
  if (!gamble?.amount) return;
  if (!takeWallet(gamble.amount)) return casinoMessage("Risiko-Spiel nicht möglich: Gewinn liegt nicht mehr im Casino-Wallet.");
  const result = nextLadderRisk(gamble);
  if (result.amount > 0) payoutFromCasino(result.amount);
  const finished = result.amount <= 0 || result.amount >= 30000 || result.finish;
  state.slots.gamble = finished ? null : { amount: result.amount, side: result.side, rung: result.rung, mode: "ladder", cards: gamble.cards || [] };
  state.slots.message = result.message;
  if (result.amount >= 30000) triggerJackpotFireworks(result.amount);
  save();
  refreshCasinoPanelStable();
}

function nextLadderRisk(gamble) {
  if (gamble.side === "top") return nextTopLadderRisk(gamble);
  const rung = Number(gamble.rung || 0);
  if (rung >= 14) {
    return { amount: 14000, side: "top", rung: 1, message: "Leiter rüber: 140 € auf der großen Leiter." };
  }
  const goUp = Math.random() < 0.38;
  let nextRung;
  if (rung === 5) {
    nextRung = goUp ? 8 : 0;
  } else if (rung === 6) {
    nextRung = goUp ? 8 : 0;
  } else if (rung === 0) {
    nextRung = goUp ? 1 : 0;
  } else {
    nextRung = goUp ? Math.min(14, rung + 1) : Math.max(0, rung - 1);
    if (nextRung === 6) nextRung = goUp ? 8 : 5;
  }
  const step = riskLadderMain[nextRung];
  const amount = step.cents || 0;
  return {
    amount,
    side: "main",
    rung: nextRung,
    message: amount > 0 ? `Leiter ${goUp ? "hoch" : "runter"} auf ${step.label}.` : "Leiter fällt auf 0 €. Gewinn verloren."
  };
}

function nextTopLadderRisk(gamble) {
  const rung = Number(gamble.rung || 1);
  const goUp = Math.random() < 0.35;
  const nextRung = goUp ? Math.min(riskLadderTop.length - 1, rung + 1) : Math.max(0, rung - 1);
  const step = riskLadderTop[nextRung];
  return {
    amount: step.cents,
    side: "top",
    rung: nextRung,
    finish: step.cents <= 10000 || step.cents >= 30000,
    message: step.cents <= 10000 ? "Große Leiter fällt auf 100 €. Sicherheitsfeld erreicht, Risiko-Spiel beendet." : step.cents >= 30000 ? "300 € erreicht. Silvester-Gewinn!" : `Große Leiter ${goUp ? "hoch" : "runter"} auf ${step.label}.`
  };
}

function gambleSlotCard(choice) {
  const gamble = state.slots.gamble;
  if (!gamble?.amount) return;
  if (!takeWallet(gamble.amount)) return casinoMessage("Risiko-Spiel nicht möglich: Gewinn liegt nicht mehr im Casino-Wallet.");
  const result = Math.random() < 0.5 ? "red" : "black";
  const card = drawRiskCard(result);
  if (choice !== result || Math.random() < 0.18) {
    state.slots.message = `Karte war ${card.label}. Falsch gewählt, Gewinn verloren.`;
    state.slots.gamble = null;
    save();
    refreshCasinoPanelStable();
    return;
  }
  const nextAmount = Math.min(gamble.amount * 2, 30000);
  payoutFromCasino(nextAmount);
  const nextGamble = createSlotGamble(nextAmount);
  nextGamble.mode = nextAmount >= 30000 ? "choice" : "cards";
  nextGamble.cards = [...(gamble.cards || []), card];
  state.slots.gamble = nextAmount >= 30000 ? null : nextGamble;
  state.slots.message = nextAmount >= 30000 ? `Richtig: ${card.label}. 300 € erreicht.` : `Richtig: ${card.label}. Gewinn verdoppelt auf ${formatCents(nextAmount)}.`;
  if (nextAmount >= 30000) triggerJackpotFireworks(nextAmount);
  save();
  refreshCasinoPanelStable();
}

function drawRiskCard(color) {
  const redCards = ["♥ A", "♦ K", "♥ 10", "♦ 7", "♥ Q"];
  const blackCards = ["♠ A", "♣ K", "♠ 10", "♣ 7", "♠ Q"];
  const pool = color === "red" ? redCards : blackCards;
  return { color, label: pool[Math.floor(Math.random() * pool.length)] };
}

function pickSlotSymbol(game, boosted) {
  const symbols = weightedSlotSymbols(game, boosted);
  if (boosted && game.wild && Math.random() < 0.08) return game.wild;
  return symbols[Math.floor(Math.random() * symbols.length)];
}

function weightedSlotSymbols(game, boosted = false) {
  if (game.id !== "horus") return [...game.symbols];
  const base = ["👑", "🪲", "🐈", "🐍", "🪙", "🪙", "🔷", "🔷", "🔷", "🔷"];
  const wildChance = boosted ? ["👁️", "👁️"] : ["👁️"];
  const scatterChance = boosted ? ["?"] : Math.random() < 0.42 ? ["?"] : [];
  return [...base, ...wildChance, ...scatterChance];
}

function scoreSlot(game, reels, bet, context = {}) {
  let win = 0;
  let message = "Kein Treffer.";
  let freeSpins = 0;
  const winCells = [];
  const hits = [];
  const scatterCount = reels.flat().filter((symbol) => symbol === game.scatter).length;
  if (game.id === "horus" && scatterCount >= 3) {
    freeSpins += game.freeSpinTrigger || 10;
    win += Math.round(bet * (context.free ? 1.4 : 0.8));
    hits.push(`${scatterCount}x ? · 10 Freispiele`);
    reels.forEach((col, colIndex) => col.forEach((symbol, rowIndex) => {
      if (symbol === game.scatter) winCells.push(`${colIndex}:${rowIndex}`);
    }));
  } else if (scatterCount >= 3 && Math.random() < 0.45) {
    freeSpins += 5;
    win += Math.round(bet * 1.1);
    hits.push("Feature gestartet: 5 Freispiele");
  }
  const lines = slotLines(game, reels);
  lines.forEach((entry) => {
    const line = entry.symbols;
    const scored = scoreLine(line, game.id === "chunks" ? null : game.wild);
    if (scored.count >= 3) {
      const mult = slotMultiplier(game, scored.symbol, scored.count);
      const freeBoost = game.id === "horus" && context.free ? 1.35 : 1;
      const lineFactor = game.id === "horus" ? 0.48 : 0.56;
      const lineWin = Math.round(bet * mult * lineFactor * freeBoost);
      win += lineWin;
      hits.push(`${scored.count}x ${scored.symbol} (${entry.name})`);
      entry.cells.slice(0, scored.count).forEach((cell) => winCells.push(cell));
    }
  });
  if (hits.length) message = hits.join(" · ");
  return { win, message, freeSpins, winCells };
}

function slotMultiplier(game, symbol, count) {
  const base = game.pays?.[symbol] || 2;
  if (game.reels === 3) return base;
  if (count >= 5) return base;
  if (count === 4) return Math.max(2, Math.round(base * 0.45));
  return Math.max(1, Math.round(base * 0.18));
}

function slotLines(game, reels) {
  if (game.id === "horus") {
    return [
      ["mitte", [1, 1, 1, 1, 1]],
      ["oben", [0, 0, 0, 0, 0]],
      ["unten", [2, 2, 2, 2, 2]],
      ["V runter", [0, 1, 2, 1, 0]],
      ["V hoch", [2, 1, 0, 1, 2]],
      ["Zickzack oben", [0, 0, 1, 2, 2]],
      ["Zickzack unten", [2, 2, 1, 0, 0]],
      ["Treppe runter", [0, 1, 1, 1, 2]],
      ["Treppe hoch", [2, 1, 1, 1, 0]],
      ["Tempel", [1, 0, 1, 2, 1]]
    ].map(([name, rowsForLine]) => makeSlotLine(name, reels, rowsForLine));
  }
  const lineShapes = game.reels === 3
    ? [
      ["oben", [0, 0, 0]],
      ["mitte", [1, 1, 1]],
      ["unten", [2, 2, 2]],
      ["diagonal runter", [0, 1, 2]],
      ["diagonal hoch", [2, 1, 0]]
    ]
    : [
      ["oben", [0, 0, 0, 0, 0]],
      ["mitte", [1, 1, 1, 1, 1]],
      ["unten", [2, 2, 2, 2, 2]],
      ["diagonal runter", [0, 1, 2, 1, 0]],
      ["diagonal hoch", [2, 1, 0, 1, 2]]
    ];
  const forwardLines = lineShapes.map(([name, rowsForLine]) => makeSlotLine(name, reels, rowsForLine));
  if (game.id === "pharaoh") {
    const reverseLines = forwardLines.map((line) => ({
      name: `${line.name} rechts`,
      symbols: [...line.symbols].reverse(),
      cells: [...line.cells].reverse()
    }));
    return [...forwardLines, ...reverseLines];
  }
  return forwardLines;
}

function makeSlotLine(name, reels, rowsForLine) {
  return {
    name,
    symbols: rowsForLine.map((row, col) => reels[col][row]),
    cells: rowsForLine.map((row, col) => `${col}:${row}`)
  };
}

function scoreLine(line, wild) {
  const base = wild ? line.find((symbol) => symbol !== wild) : line[0];
  if (!base) return { symbol: wild, count: line.length };
  let count = 0;
  for (const symbol of line) {
    if (symbol === base || (wild && symbol === wild)) count += 1;
    else break;
  }
  if (wild && line[0] === wild && count < 3) return { symbol: base, count: 0 };
  return { symbol: base, count };
}

function card(name, text, label, index, disabled = false, kind = "") {
  const record = findCatalogItemByName(name);
  const idLine = record ? `<small class="item-id">ID: ${record.id}</small>` : "";
  return `
    <article class="item-card">
      <div>
        <h3>${name}</h3>
        <p>${text}${idLine}</p>
      </div>
      <button class="mini-button" data-index="${index}" ${kind ? `data-kind="${kind}"` : ""} ${disabled ? "disabled" : ""}>${label}</button>
    </article>
  `;
}

