    if (!WINDOW_APPS_V56.has(activeApp)) return;
    const shell = els.dialog?.querySelector?.(".device-shell");
    const screen = shell?.querySelector?.(".device-screen");
    const view = shell?.querySelector?.(".device-app-view");
    if (!shell || !screen || !view) return;

