    if (!bankProfilesV58.length) return `<div class="jk-bank-search-empty-v59"><b>Kein Empfänger gefunden</b><small>${escapeHtml(bankSearchMessageV59 || "Prüfe die Eingabe und versuche es erneut.")}</small></div>`;
